/// 可保存、命名、切换、对比的 System Prompt 预设。
/// 内容完全由用户掌控；{{变量}} 在发送前由客户端做纯文本插值。
class PromptPreset {
  String id;
  String name;
  String content;
  int updatedAt;
  bool builtin;

  PromptPreset({
    required this.id,
    required this.name,
    required this.content,
    int? updatedAt,
    this.builtin = false,
  }) : updatedAt = updatedAt ?? DateTime.now().millisecondsSinceEpoch;

  static const List<String> varNames = [
    'query',
    'date',
    'time',
    'model',
    'language',
    'sources',
    'tier',
  ];

  static final RegExp _var = RegExp(r'\{\{\s*([a-zA-Z_]+)\s*\}\}');

  /// 提取内容里用到的变量，供 UI 提示。
  static List<String> variablesOf(String text) => _var
      .allMatches(text)
      .map((m) => m.group(1) ?? '')
      .where((e) => e.isNotEmpty)
      .toSet()
      .toList();

  /// 纯文本插值；未知变量原样保留，不会抛错。
  String render({
    String query = '',
    String model = '',
    String language = '简体中文',
    String sources = '',
    String tier = '',
  }) {
    final now = DateTime.now();
    final date =
        '${now.year}-${now.month.toString().padLeft(2, '0')}-${now.day.toString().padLeft(2, '0')}';
    final time =
        '${now.hour.toString().padLeft(2, '0')}:${now.minute.toString().padLeft(2, '0')}';
    final map = <String, String>{
      'query': query,
      'date': date,
      'time': time,
      'model': model,
      'language': language,
      'sources': sources,
      'tier': tier,
    };
    return content.replaceAllMapped(
        _var, (m) => map[m.group(1)] ?? m.group(0) ?? '');
  }

  PromptPreset copy({String? id, String? name}) => PromptPreset(
        id: id ?? 'p_${DateTime.now().microsecondsSinceEpoch}',
        name: name ?? this.name,
        content: content,
        updatedAt: DateTime.now().millisecondsSinceEpoch,
        builtin: false,
      );

  Map<String, dynamic> toJson() => {
        'id': id,
        'name': name,
        'content': content,
        'updatedAt': updatedAt,
        'builtin': builtin,
      };

  factory PromptPreset.fromJson(Map<dynamic, dynamic> j) => PromptPreset(
        id: (j['id'] ?? '').toString(),
        name: (j['name'] ?? '未命名预设').toString(),
        content: (j['content'] ?? '').toString(),
        updatedAt: (j['updatedAt'] as num?)?.toInt(),
        builtin: j['builtin'] == true,
      );
}

