  /// 要完全离线时在设置里切回内置离线识别。
  String sttEngineId = 'ovh-whisper';
  String sttModel = '';
  String sttBaseUrl = '';

  /// v4.11：说完静音自动停止识别，并把结果**放进输入框**。
  ///
  /// 语音识别一律不替用户按发送键：识别错一两个字是常态，必须先让人
  /// 看一眼、改一下，再自己点发送。旧的 `sttAutoSend`（识别完直接发）
  /// 已移除，旧配置里的同名键会被忽略，避免升级后仍旧自动发出去。
  bool sttAutoStopOnSilence = true;

