/// 风险等级。只读类可以静默跑；写入与外部动作默认需要用户明确授权。
enum AgentRisk { read, workspace, external, system, network }

/// 授权分组。四个开关都在「设置 → 设备智能体」里，默认全关。
class AgentGrant {
  final bool workspace;
  final bool external;
  final bool system;
  final bool network;

  /// v4.25：设备缓存清理与可访问文件删除，只有「完全权限」才放开。
  final bool device;

  const AgentGrant({
    this.workspace = false,
    this.external = false,
    this.system = false,
    this.network = false,
    this.device = false,
  });

  bool allows(String grant) => switch (grant) {
        '' => true,
        'workspace' => workspace,
        'external' => external,
        'system' => system,
        'network' => network,
        'device' => device,
        _ => false,
      };

  static String labelOf(String grant) => switch (grant) {
        'workspace' => '文件与脚本',
        'external' => '应用与网页',
        'system' => '日历与闹钟',
        'network' => '网页抓取',
        'device' => '设备清理',
        _ => '只读',
      };
}

class AgentTool {
  final String id;
  final String name;
  final String summary;
  final String usage;
  final AgentRisk risk;
  final String grant;

  const AgentTool({
    required this.id,
    required this.name,
    required this.summary,
    required this.usage,
    required this.risk,
    this.grant = '',
  });

  String get shortId => id.startsWith('agent.') ? id.substring(6) : id;

  String get riskLabel => switch (risk) {
        AgentRisk.read => '只读',
        AgentRisk.workspace => '写工作区',
        AgentRisk.external => '调起外部应用',
        AgentRisk.system => '系统数据',
        AgentRisk.network => '网络读取',
      };

  /// 只读且无副作用的工具可以在「每次确认」开启时依然静默执行。
  bool get needsConfirmation => risk != AgentRisk.read;
}

