    summary: '只读：本应用缓存、临时文件、工作区各占多少空间，手机还剩多少可用',
    usage: '无参数',
    risk: AgentRisk.read,
  ),
  AgentTool(
    id: 'agent.files.search',
    name: '查找文件',
    summary: '按文件名关键词在本应用可访问的目录里查找，只读列出路径与大小',
    usage: 'query(文件名关键词，可空), limit(默认 60)',
    risk: AgentRisk.read,
  ),
  AgentTool(
    id: 'agent.storage.clean',
    name: '清理缓存与临时文件',
    summary: '清理本应用缓存、code_cache 与工作区临时文件，回收存储空间',
    usage: '无参数',
    risk: AgentRisk.system,
    grant: 'device',
  ),
  AgentTool(
    id: 'agent.files.delete',
    name: '删除缓存文件',
    summary: '删除一个文件（仅限缓存与工作区目录内，越界路径一律拒绝）',
    usage: 'path(必填，完整路径，来自「查找文件」的结果)',
    risk: AgentRisk.system,
    grant: 'device',
  ),
  AgentTool(
    id: 'agent.storage.settings',
    name: '打开系统存储设置',
    summary: '打开系统存储页，由用户自行清理其它应用的缓存',
    usage: '无参数',
    risk: AgentRisk.external,
    grant: 'external',
  ),
];

AgentTool? agentToolById(String id) {
  for (final t in kAgentTools) {
    if (t.id == id || t.shortId == id) return t;
  }
  return null;
}

/// 从模型输出里解析本机工具调用。
///
/// 复用 OpenApiPlugin 里那套稳健的 JSON 扫描（fenced / 内联 / 括号平衡），
/// 但**只认 `agent.` 前缀或本机工具短名**，这样同时启用 OpenAPI 插件时两边
/// 不会互相把对方的工具 JSON 吞掉。
Map<String, dynamic>? parseAgentToolCall(String text) {
  final call = OpenApiPlugin.parseToolCall(text);
  if (call == null) return null;
  final raw = call['tool'].toString().trim();
  final tool = agentToolById(raw);
  if (tool == null) return null;
  return {
    'tool': tool.id,
    'arguments': call['arguments'] as Map<String, dynamic>,
    'name': tool.name,
  };
}

/// 注入 System Prompt 的本机能力说明。
String buildAgentPrompt({
  required DeviceInfo info,
  required AgentGrant grant,
  required String workspaceRoot,
  required bool confirmEach,
}) {
  final b = StringBuffer();
  b.writeln('[本机能力] 你运行在用户这台手机上，可以真正操作设备，而不只是回答问题。'
      '默认仍然直接回答；只有用户明确要求你「打开 / 查找 / 保存 / 设置 / 运行」时才调用工具。');
  b.writeln('[设备信息] ${info.promptSummary}');
  b.writeln('[隔离工作区] 你有一个专属文件夹（$workspaceRoot），写文件、跑脚本都在这里进行。'
      '只接受相对路径；绝对路径、..、隐藏文件、符号链接一律被拒绝。'
      '覆盖写会自动备份旧版，删除只是移入回收站，不会真正丢失文件。');
  b.writeln('[设备清理与找文件] agent.storage.info 看占用、agent.files.search 按文件名查找、'
      'agent.storage.clean 清理本应用缓存、agent.files.delete 删除缓存文件、'
      'agent.storage.settings 打开系统存储页。'
      'Android 沙箱限制：只能访问本应用目录与可访问的公共目录，'
      '**无法**清理其它应用的缓存或读取它们的私有文件。遇到这类请求请如实说明，'
      '并调起系统存储设置让用户自己操作，绝不声称已经帮用户清理了整台手机。');
  b.writeln('[工具调用格式] 需要调用工具时，只输出一行 JSON，不附加解释、不要放进代码块：');
  b.writeln('{"tool":"agent.工具ID","arguments":{"参数名":"值"}}');
  b.writeln('可用工具（共 ${kAgentTools.length} 个，方括号为当前授权状态）：');
  for (final t in kAgentTools) {
    final on = grant.allows(t.grant);
    b.writeln('- ${t.id} | ${t.name} | ${t.summary} | 参数: ${t.usage} | '
        '${t.grant.isEmpty ? "可直接用" : "[${on ? "已授权" : "未授权"}] ${AgentGrant.labelOf(t.grant)}"}');
  }
  b.writeln('调用后会收到「[工具执行结果]」，届时请用自然语言总结实际做了什么，'
      '不要再输出工具 JSON；未获授权或执行失败时如实说明，不要反复重试同一个调用。');
  if (confirmEach) {
    b.writeln('[风险确认] 写文件、打开应用、日历闹钟等动作会在界面上先请用户点「允许」，'
        '用户可能拒绝；请把这一步当作正常结果处理。');
  }
  b.writeln(AgentScriptRunner.syntaxPrompt);
  b.writeln('[硬边界] 你不能执行任意系统命令、安装软件、读取其它应用的数据、'
      '修改系统设置、清理其它应用的缓存或删除工作区之外的用户文件。'
      '做不到的请求直接说明原因并给出替代做法。');
  return b.toString();
}

/// 一次待用户确认的动作（非模态确认条展示用）。
class AgentAction {
  final String tool;
  final String toolName;
  final String preview;
  final Map<String, dynamic> args;

  const AgentAction({
    required this.tool,
    required this.toolName,
    required this.preview,
    required this.args,
  });
}

class AgentExecution {
  final String tool;
  final String toolName;
  final bool ok;
  final String message;
  final String? missingGrant;
  final bool declined;

  const AgentExecution({
    required this.tool,
    required this.toolName,
    required this.ok,
    required this.message,
    this.missingGrant,
    this.declined = false,
  });

  /// 回灌给模型的结果文本。
  String get asToolResult => ok
      ? '[工具 $toolName 执行结果]\n$message'
      : (declined
          ? '[工具 $toolName 未执行] 用户拒绝了这次操作。请改用文字说明，不要重试。'
          : '[工具 $toolName 未执行] $message');
}

/// 本机工具执行器。所有动作都在这里收敛：授权检查 → 用户确认 → 执行 → 审计日志。
class AgentRuntime {
  AgentRuntime({
    required this.workspace,
    required this.grant,
    required this.deviceInfo,
    DeviceBridge? device,
    this.confirm,
    this.confirmEach = true,
  }) : device = device ?? DeviceBridge();

  final AgentWorkspace workspace;
  final AgentGrant grant;
  final DeviceInfo deviceInfo;
  final DeviceBridge device;
  final Future<bool> Function(AgentAction action)? confirm;
  final bool confirmEach;

  static String _arg(Map<String, dynamic> a, String key, [String fallback = '']) {
    final v = a[key];
    if (v == null) return fallback;
    return v.toString();
  }

  static int _int(Map<String, dynamic> a, String key, int fallback) {
    final v = a[key];
    if (v is num) return v.toInt();
    return int.tryParse(v?.toString() ?? '') ?? fallback;
  }

  String previewOf(AgentTool t, Map<String, dynamic> a) {
    final path = _arg(a, 'path', _arg(a, 'from'));
    return switch (t.id) {
      'agent.workspace.write' || 'agent.workspace.append' =>
        '写入文件：$path（${_arg(a, 'content').length} 字）',
      'agent.workspace.run' => '运行任务脚本（${_arg(a, 'script').length} 字）',
      'agent.workspace.delete' => '移入回收站：$path',
      'agent.workspace.rename' => '重命名：$path → ${_arg(a, 'to')}',
      'agent.workspace.restore' => '从回收站恢复：${_arg(a, 'name')}',
      'agent.workspace.mkdir' => '新建文件夹：$path',
      'agent.app.open' => '打开应用：${_arg(a, 'name', _arg(a, 'package'))}',
      'agent.web.open' => '打开网页：${_arg(a, 'url', _arg(a, 'query'))}',
      'agent.web.fetch' => '抓取网页：${_arg(a, 'url')}',
      'agent.calendar.add' => '新建日程：${_arg(a, 'title')}',
      'agent.alarm.set' => '设置闹钟：${_arg(a, 'hour')}:${_arg(a, 'minute')}',
      'agent.share.text' => '调起分享：${_arg(a, 'text')}',
      'agent.clipboard.set' => '写入剪贴板：${_arg(a, 'text')}',
      'agent.toast' => '屏幕提示：${_arg(a, 'text')}',
      'agent.storage.clean' => '清理本应用缓存与临时文件',
      'agent.files.delete' => '删除文件：${_arg(a, 'path')}',
      'agent.files.search' => '查找文件：${_arg(a, 'query', '全部')}',
      _ => '${t.name} ${_arg(a, 'path')}'.trim(),
    };
  }

  Future<AgentExecution> execute(String toolId, Map<String, dynamic> args) async {
    final t = agentToolById(toolId);
    if (t == null) {
      return AgentExecution(
          tool: toolId, toolName: toolId, ok: false, message: '未知本机工具：$toolId');
    }
    if (!grant.allows(t.grant)) {
      final msg = '该操作需要「${AgentGrant.labelOf(t.grant)}」授权，'
          '请到 设置 → 设备智能体 打开对应开关后再试。';
      await _log(t, false, '未授权：${t.name}');
      return AgentExecution(
          tool: t.id,
          toolName: t.name,
          ok: false,
          message: msg,
          missingGrant: t.grant);
    }
    if (confirmEach && t.needsConfirmation && confirm != null) {
      final ok = await confirm!(AgentAction(
        tool: t.id,
        toolName: t.name,
        preview: previewOf(t, args),
        args: args,
      ));
      if (!ok) {
        await _log(t, false, '用户拒绝：${previewOf(t, args)}');
        return AgentExecution(
            tool: t.id,
            toolName: t.name,
            ok: false,
            declined: true,
            message: '用户拒绝');
      }
    }

    try {
      final msg = await _run(t, args);
      await _log(t, true, previewOf(t, args));
      return AgentExecution(
          tool: t.id, toolName: t.name, ok: true, message: msg);
    } catch (e) {
      final msg = '执行失败：$e';
      await _log(t, false, '${previewOf(t, args)} → $e');
      return AgentExecution(
          tool: t.id, toolName: t.name, ok: false, message: msg);
    }
  }

  Future<void> _log(AgentTool t, bool ok, String detail) async {
    try {
      await workspace.log(AgentLogEntry(
        at: DateTime.now().millisecondsSinceEpoch,
        tool: t.id,
        detail: detail,
        ok: ok,
      ));
    } catch (_) {}
  }

  Future<String> _run(AgentTool t, Map<String, dynamic> a) async {
    switch (t.id) {
      case 'agent.device.info':
        return deviceInfo.promptSummary;

      case 'agent.app.list':
        final kw = _arg(a, 'keyword').toLowerCase();
        final apps = await device.apps();
        final list = kw.isEmpty
            ? apps
            : apps.where((x) =>
                x.label.toLowerCase().contains(kw) ||
                x.packageName.toLowerCase().contains(kw)).toList();
        if (list.isEmpty) return '没有找到可启动的应用（可能需要系统权限或未安装桌面应用）。';
        final rows = list
            .take(60)
            .map((x) => '- ${x.label} → ${x.packageName}${x.system ? "（系统应用）" : ""}')
            .join('\n');
        return '共 ${list.length} 个应用：\n$rows';

      case 'agent.workspace.list':
        final entries = await workspace.list(_arg(a, 'path'));
        if (entries.isEmpty) return '工作区当前为空。';
        final rows = entries
            .map((e) => '- ${e.isDir ? "[目录] " : ""}${e.rel}  ${e.sizeLabel}')
            .join('\n');
        return '工作区共 ${entries.length} 项：\n$rows';

      case 'agent.workspace.read':
        final path = _arg(a, 'path');
        if (path.isEmpty) return '缺少 path 参数';
        return '文件 $path 内容：\n${await workspace.read(path)}';

      case 'agent.workspace.usage':
        final u = await workspace.usage();
        return '工作区：${u.files} 个文件，${(u.bytes / 1024).toStringAsFixed(1)} KB；'
            '回收站 ${u.trashFiles} 个条目。';

      case 'agent.workspace.write':
        return workspace.write(_arg(a, 'path'), _arg(a, 'content'));

      case 'agent.workspace.append':
        return workspace.append(_arg(a, 'path'), _arg(a, 'content'));

      case 'agent.workspace.mkdir':
        return workspace.mkdir(_arg(a, 'path'));

      case 'agent.workspace.delete':
        return workspace.delete(_arg(a, 'path'));

      case 'agent.workspace.rename':
        return workspace.rename(_arg(a, 'from'), _arg(a, 'to'));

      case 'agent.workspace.restore':
        return workspace.restore(_arg(a, 'name'));

      case 'agent.workspace.clearTrash':
        return workspace.clearTrash();

      case 'agent.workspace.run':
        final script = _arg(a, 'script');
        if (script.trim().isEmpty) return '缺少 script 参数';
        final r = await AgentScriptRunner(workspace).run(
          script,
          deviceModel: deviceInfo.model,
          deviceBrand: deviceInfo.brand,
        );
        final head = r.ok
            ? '脚本执行完成，共 ${r.steps} 条指令：'
            : '脚本在第 ${r.steps} 条指令中断：${r.error}';
        return '$head\n${r.output.isEmpty ? "（无输出）" : r.output}';

      case 'agent.web.fetch':
        return _fetch(_arg(a, 'url'));

      case 'agent.web.open':
        var url = _arg(a, 'url');
        final q = _arg(a, 'query');
        if (url.isEmpty && q.isNotEmpty) {
          url = 'https://www.bing.com/search?q=${Uri.encodeQueryComponent(q)}';
        }
        if (url.isEmpty) return '需要 url 或 query 参数';
        final ok = await device.openUrl(url);
        return ok
            ? '已在手机浏览器中打开：$url'
            : '未能打开浏览器（系统可能没有可用浏览器），链接：$url';

      case 'agent.app.open':
        var pkg = _arg(a, 'package');
        final name = _arg(a, 'name');
        if (pkg.isEmpty && name.isNotEmpty) {
          final apps = await device.apps();
          final k = name.toLowerCase();
          final hit = apps.where((x) =>
              x.label.toLowerCase() == k ||
              x.label.toLowerCase().contains(k) ||
              x.packageName.toLowerCase().contains(k));
          if (hit.isEmpty) {
            return '手机上没找到叫「$name」的可启动应用。可先用 agent.app.list 查看全部应用。';
          }
          pkg = hit.first.packageName;
          final ok = await device.openApp(pkg);
          return ok
              ? '已打开「${hit.first.label}」（$pkg）'
              : '找到「${hit.first.label}」但启动失败，可能受系统限制';
        }
        if (pkg.isEmpty) return '需要 name 或 package 参数';
        final ok = await device.openApp(pkg);
        return ok ? '已启动 $pkg' : '启动失败：未找到该应用或系统拒绝了启动';

      case 'agent.share.text':
        final ok = await device.shareText(_arg(a, 'text'));
        return ok ? '已调起系统分享面板' : '分享失败（系统没有可用的分享目标）';

      case 'agent.clipboard.set':
        final text = _arg(a, 'text');
        try {
          await Clipboard.setData(ClipboardData(text: text));
          return '已复制 ${text.length} 字到剪贴板';
        } catch (_) {
          final ok = await device.setClipboard(text);
          return ok ? '已复制到剪贴板' : '写入剪贴板失败';
        }

      case 'agent.toast':
        final ok = await device.toast(_arg(a, 'text'));
        return ok ? '已显示提示' : '提示显示失败';

      case 'agent.calendar.add':
        return _calendar(a);

      case 'agent.alarm.set':
        final h = _int(a, 'hour', -1);
        final m = _int(a, 'minute', 0);
        if (h < 0 || h > 23 || m < 0 || m > 59) {
          return '时间不合法：hour 需 0-23，minute 需 0-59';
        }
        final ok = await device.setAlarm(
            hour: h, minute: m, label: _arg(a, 'label', 'Aigent'));
        return ok
            ? '已打开系统时钟的「设置闹钟」页（$h:$m），需你点保存才会生效'
            : '未能调起系统时钟，请确认手机已安装时钟应用';

      // ---- v4.25 设备清理与文件查找 ----
      case 'agent.storage.info': {
        final s = await device.storageSummary();
        if (s == null) return '未能读取存储信息（此设备可能不支持）';
        return '缓存 ${StorageSummary.human(s.cacheBytes)} · '
            '临时文件 ${StorageSummary.human(s.tempBytes)} · '
            '工作区 ${StorageSummary.human(s.workspaceBytes)}；'
            '手机可用 ${StorageSummary.human(s.freeBytes)} / '
            '共 ${StorageSummary.human(s.totalBytes)}，'
            '可清理约 ${StorageSummary.human(s.reclaimable)}。';
      }

      case 'agent.files.search': {
        final q = _arg(a, 'query');
        final files = await device.searchFiles(q, limit: _int(a, 'limit', 60));
        if (files.isEmpty) {
          return q.isEmpty
              ? '当前可访问目录里没有文件。'
              : '没有找到文件名包含「$q」的文件。'
                  'Android 沙箱限制：只能搜索本应用目录与可访问的公共目录。';
        }
        final b = StringBuffer('找到 ${files.length} 个文件：\n');
        for (final f in files.take(20)) {
          b.writeln('- ${f.name} · ${StorageSummary.human(f.size)} · ${f.path}');
        }
        if (files.length > 20) b.writeln('（还有 ${files.length - 20} 个未列出）');
        return b.toString().trim();
      }

      case 'agent.storage.clean': {
        final r = await device.cleanCache();
        if (r == null) return '清理失败：设备未返回清理结果';
        return '已释放 ${StorageSummary.human(r.freedBytes)}，'
            '清理 ${r.removedFiles} 个文件。'
            '其它应用的缓存需由你在系统存储设置里手动清理。';
      }

      case 'agent.files.delete': {
        final path = _arg(a, 'path');
        if (path.isEmpty) return '缺少 path 参数';
        final ok = await device.deleteFile(path);
        return ok
            ? '已删除：$path'
            : '删除被拒绝：$path 不在允许删除的缓存 / 工作区目录内，或文件不存在。';
      }

      case 'agent.storage.settings': {
        final ok = await device.openStorageSettings();
        return ok
            ? '已打开系统存储设置，请在这里手动清理其它应用的缓存。'
            : '未能打开系统存储设置';
      }

      default:
        return '工具尚未实现：${t.id}';
    }
  }

  Future<String> _calendar(Map<String, dynamic> a) async {
    final title = _arg(a, 'title');
    if (title.isEmpty) return '缺少 title 参数';
    final raw = _arg(a, 'start');
    DateTime start;
    if (raw.isEmpty) {
      start = DateTime.now().add(const Duration(hours: 1));
    } else if (RegExp(r'^\+?\d+$').hasMatch(raw)) {
      start = DateTime.now()
          .add(Duration(minutes: int.tryParse(raw.replaceFirst('+', '')) ?? 60));
    } else {
      start = DateTime.tryParse(raw) ??
          DateTime.now().add(const Duration(hours: 1));
    }
    final minutes = _int(a, 'minutes', 60).clamp(1, 24 * 60);
    final end = start.add(Duration(minutes: minutes));
    final ok = await device.addCalendar(
      title: title,
      startMillis: start.millisecondsSinceEpoch,
      endMillis: end.millisecondsSinceEpoch,
      description: _arg(a, 'description'),
      location: _arg(a, 'location'),
    );
    return ok
        ? '已打开系统日历「新建事件」页：$title（${start.toString().substring(0, 16)}，'
            '$minutes 分钟），需你点保存才会写入日历'
        : '未能调起系统日历，请确认手机已安装日历应用';
  }

  /// 抓取公开网页正文。显式拦掉内网 / 回环 / 元数据地址，避免模型被诱导
  /// 去探测局域网或云元数据服务（SSRF）。
  Future<String> _fetch(String url) async {
    final uri = Uri.tryParse(url.trim());
    if (uri == null || !uri.hasScheme || !['http', 'https'].contains(uri.scheme)) {
      return '只接受 http / https 网址';
    }
    final host = uri.host.toLowerCase();
    if (isBlockedHost(host)) {
      return '出于安全考虑，禁止抓取本机 / 内网 / 元数据地址：$host';
    }
    final dio = Dio(BaseOptions(
      connectTimeout: const Duration(seconds: 8),
      receiveTimeout: const Duration(seconds: 10),
      maxRedirects: 3,
      responseType: ResponseType.plain,
      headers: {'User-Agent': 'Mozilla/5.0 (Aigent/4.7; Android)'},
    ));
    final resp = await dio.get<String>(url);
    final body = resp.data ?? '';
    if (body.length > 200000) {
      return '网页过大（${body.length} 字符），已放弃读取。可用 agent.web.open 在浏览器里查看。';
    }
    final text = _htmlToText(body);
    final clipped = text.length > 12000 ? '${text.substring(0, 12000)}\n…（已截断）' : text;
    return '网页 $url 的正文（${text.length} 字）：\n$clipped';
  }

  /// 内网 / 回环 / 云元数据主机黑名单（公开以便回归测试）。
  static bool isBlockedHost(String h) {
    if (h.isEmpty || h == 'localhost' || h.endsWith('.local') || h == '::1') {
      return true;
    }
    if (h.contains('metadata') || h == '169.254.169.254') return true;
    final v4 = RegExp(r'^(\d+)\.(\d+)\.(\d+)\.(\d+)$').firstMatch(h);
    if (v4 != null) {
      final a = int.parse(v4.group(1)!);
      final b = int.parse(v4.group(2)!);
      if (a == 127 || a == 10 || a == 0 || (a == 169 && b == 254)) return true;
      if (a == 192 && b == 168) return true;
      if (a == 172 && b >= 16 && b <= 31) return true;
      if (a == 100 && b >= 64 && b <= 127) return true;
    }
    return false;
  }

  static String _htmlToText(String html) {
    var s = html
        .replaceAll(RegExp(r'<script[\s\S]*?</script>', caseSensitive: false), ' ')
        .replaceAll(RegExp(r'<style[\s\S]*?</style>', caseSensitive: false), ' ')
        .replaceAll(RegExp(r'<!--[\s\S]*?-->'), ' ')
        .replaceAll(RegExp(r'<br\s*/?>|</p>|</div>|</li>|</h[1-6]>',
            caseSensitive: false), '\n')
        .replaceAll(RegExp(r'<[^>]+>'), ' ')
        .replaceAll('&nbsp;', ' ')
        .replaceAll('&amp;', '&')
        .replaceAll('&lt;', '<')
        .replaceAll('&gt;', '>')
        .replaceAll('&quot;', '"')
        .replaceAll('&#39;', "'")
        .replaceAll(RegExp(r'&#(\d+);'), '');
    s = s
        .split('\n')
        .map((l) => l.replaceAll(RegExp(r'[ \t]+'), ' ').trim())
        .where((l) => l.isNotEmpty)
        .join('\n');
    return s.trim();
  }
}

/// 把模型输出里可能夹带的工具 JSON 清掉，避免最终答案里残留一行生硬的结构。
String stripAgentToolJson(String text) {
  final t = text.trim();
  final call = parseAgentToolCall(t);
  if (call == null) return text;
  return t
      .replaceAll(RegExp(r'\{[^{}]*"tool"\s*:\s*"agent\.[^{}]*\}'), '')
      .replaceAll(RegExp(r'```(?:tool|json)?\s*[\s\S]*?```', caseSensitive: false), '')
      .trim();
}

import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:path_provider/path_provider.dart';

import 'device_bridge.dart';

/// 智能体的**独立工作目录**。
///
/// 这是整个「真干活」能力的物理边界：
///  - 根目录固定在应用专属目录 `aigent_workspace/`，卸载即清理，
///    绝不指向相册、Download、SD 卡根目录或任何用户已有文件夹；
///  - 所有相对路径都经过 [_safe] 校验：拒绝绝对路径、`..`、盘符、
///    隐藏文件与符号链接逃逸，任何越界尝试直接抛错，不做「尽力而为」；
///  - 覆盖写之前先把旧版本备份到 `.trash/`，删除不是真删而是移入
///    回收站，随时可恢复 —— 用户最担心的「文件丢失 / 损坏」在结构上
///    就不可能发生；
///  - 单文件与总数量都有上限，避免模型一轮循环把存储写满；
///  - 每次动作都追加一条审计日志，设置页可查、可回溯。
class WorkspaceException implements Exception {
  final String message;
  const WorkspaceException(this.message);
  @override
  String toString() => message;
}

class WorkspaceEntry {
  final String rel;
  final String name;
  final bool isDir;
  final int size;
  final int modifiedMs;

  const WorkspaceEntry({
    required this.rel,
    required this.name,
    required this.isDir,
    required this.size,
    required this.modifiedMs,
  });

  String get sizeLabel {
    if (isDir) return '文件夹';
    if (size < 1024) return '$size B';
    if (size < 1024 * 1024) return '${(size / 1024).toStringAsFixed(1)} KB';
    return '${(size / 1048576).toStringAsFixed(1)} MB';
  }
}

class AgentLogEntry {
  final int at;
  final String tool;
  final String detail;
  final bool ok;

  const AgentLogEntry({
    required this.at,
    required this.tool,
    required this.detail,
    this.ok = true,
  });

  Map<String, dynamic> toJson() => {
        'at': at,
        'tool': tool,
        'detail': detail,
        'ok': ok,
      };

  factory AgentLogEntry.fromJson(Map<dynamic, dynamic> j) => AgentLogEntry(
        at: (j['at'] as num?)?.toInt() ?? 0,
        tool: (j['tool'] ?? '').toString(),
        detail: (j['detail'] ?? '').toString(),
        ok: j['ok'] != false,
      );
}

class AgentWorkspace {
  AgentWorkspace(this.root);

  /// 工作区根目录（绝对路径）。
  final String root;

  /// 单文件上限 2 MB；总文件数上限 300；日志保留 500 条。
  static const int maxFileBytes = 2 * 1024 * 1024;
  static const int maxFiles = 300;
  static const int maxLogLines = 500;

  static const String trashDirName = '.trash';
  static const String logFileName = 'agent_log.jsonl';

  Directory get _rootDir => Directory(root);
  String get trashPath => p.join(root, trashDirName);
  String get logPath => p.join(root, logFileName);

  /// 打开（或创建）真机上的工作区。原生通道拿不到路径时逐级降级，
  /// 保证单元测试 / 桌面环境也有一个可用目录。
  static Future<AgentWorkspace> open({DeviceBridge? bridge}) async {
    String? path;
    try {
      path = await (bridge ?? DeviceBridge()).workspaceRoot();
    } catch (_) {}
    if (path == null || path.isEmpty) {
      try {
        path = (await getExternalStorageDirectory())?.path;
      } catch (_) {}
    }
    if (path == null || path.isEmpty) {
      try {
        path = (await getApplicationDocumentsDirectory()).path;
      } catch (_) {}
    }
    path ??= p.join(Directory.systemTemp.path, 'aigent_workspace');
    final ws = AgentWorkspace(p.join(path, 'aigent_workspace'));
    await ws.ensure();
    return ws;
  }

  Future<void> ensure() async {
    if (!_rootDir.existsSync()) {
      await _rootDir.create(recursive: true);
    }
    final trash = Directory(trashPath);
    if (!trash.existsSync()) await trash.create(recursive: true);
  }

  /// 把相对路径解析成绝对路径，并做全部安全校验。
  /// 传入空字符串表示根目录本身，仅允许 [list] 使用。
  String _safe(String rel, {bool allowRoot = false}) {
    final t = rel.trim().replaceAll('\\', '/');
    if (t.isEmpty) {
      if (allowRoot) return root;
      throw const WorkspaceException('路径不能为空');
    }
    if (p.isAbsolute(t) || t.startsWith('/') || t.startsWith('\\')) {
      throw const WorkspaceException('只允许工作区内的相对路径，不接受绝对路径');
    }
    if (RegExp(r'^[A-Za-z]:').hasMatch(t)) {
      throw const WorkspaceException('不接受盘符路径');
    }
    final parts = p.posix.split(t);
    if (parts.any((e) => e == '..')) {
      throw const WorkspaceException('路径不能包含 ..（禁止跳出工作区）');
    }
    if (parts.any((e) => e.startsWith('.') && e != '.')) {
      throw const WorkspaceException('不允许访问隐藏文件或系统保留目录');
    }
    if (parts.contains(trashDirName) || parts.contains(logFileName)) {
      throw const WorkspaceException('该路径由系统保留，不可直接操作');
    }
    final target = p.normalize(p.join(root, t));
    if (!p.isWithin(root, target)) {
      throw const WorkspaceException('路径越出了工作区');
    }
    return target;
  }

  /// 符号链接逃逸检查：真实路径必须仍在根目录内。
  void _assertNoEscape(String target) {
    final rootReal = _rootDir.resolveSymbolicLinksSync();
    bool inside(String real) => real == rootReal || p.isWithin(rootReal, real);
    final parent = Directory(p.dirname(target));
    if (parent.existsSync() && !inside(parent.resolveSymbolicLinksSync())) {
      throw const WorkspaceException('目录链接指向了工作区之外');
    }
    final f = File(target);
    if (f.existsSync() && !inside(f.resolveSymbolicLinksSync())) {
      throw const WorkspaceException('文件链接指向了工作区之外');
    }
    final d = Directory(target);
    if (d.existsSync() && !inside(d.resolveSymbolicLinksSync())) {
      throw const WorkspaceException('目录链接指向了工作区之外');
    }
  }

  String _rel(String abs) => p.relative(abs, from: root).replaceAll('\\', '/');

  bool _isReserved(FileSystemEntity e) =>
      p.basename(e.path) == trashDirName ||
      p.basename(e.path) == logFileName ||
      p.basename(e.path).startsWith('.');

  int _seq = 0;

  /// 把「相对路径」编码进回收站条目名（/ → __），恢复时才能回到原子目录。
  /// 微秒时间戳 + 自增序号：同一毫秒里连续覆盖 / 删除也不会重名或排序颠倒。
  String _trashName(String relName) {
    final ts = DateTime.now().microsecondsSinceEpoch;
    _seq++;
    final safe = relName
        .replaceAll('/', '__')
        .replaceAll(RegExp(r'[^\w.\-\u4e00-\u9fff]'), '_');
    return '${ts}_${_seq}_$safe';
  }

  Future<void> _checkQuota({required int incomingBytes}) async {
    if (incomingBytes > maxFileBytes) {
      throw WorkspaceException(
          '内容超过单文件上限 ${(maxFileBytes / 1048576).toStringAsFixed(0)} MB，已拒绝写入');
    }
    var count = 0;
    await for (final e in _rootDir.list(recursive: true, followLinks: false)) {
      if (e is File &&
          !_isReserved(e) &&
          !p.isWithin(trashPath, e.path)) {
        count++;
      }
    }
    if (count >= maxFiles) {
      throw const WorkspaceException('工作区文件数已达上限 $maxFiles，请先清理');
    }
  }

  /// 覆盖前备份旧内容；返回备份文件名（无旧文件则返回空串）。
  Future<String> _backup(File f) async {
    if (!f.existsSync()) return '';
    final name = _trashName('${_rel(f.path)}.bak');
    final dest = p.join(trashPath, name);
    await f.copy(dest);
    return name;
  }

  Future<List<WorkspaceEntry>> list([String rel = '']) async {
    await ensure();
    final dir = Directory(_safe(rel, allowRoot: true));
    if (!dir.existsSync()) {
      throw const WorkspaceException('文件夹不存在');
    }
    final out = <WorkspaceEntry>[];
    await for (final e in dir.list(followLinks: false)) {
      if (_isReserved(e)) continue;
      final stat = e.statSync();
      out.add(WorkspaceEntry(
        rel: _rel(e.path),
        name: p.basename(e.path),
        isDir: stat.type == FileSystemEntityType.directory,
        size: stat.size,
        modifiedMs: stat.modified.millisecondsSinceEpoch,
      ));
    }
    out.sort((a, b) {
      if (a.isDir != b.isDir) return a.isDir ? -1 : 1;
      return a.name.toLowerCase().compareTo(b.name.toLowerCase());
    });
    return out;
  }

  Future<String> read(String rel) async {
    await ensure();
    final path = _safe(rel);
    _assertNoEscape(path);
    final f = File(path);
    if (!f.existsSync()) throw const WorkspaceException('文件不存在');
    if (f.lengthSync() > maxFileBytes) {
      throw const WorkspaceException('文件超过 2 MB，拒绝一次性读入上下文');
    }
    return f.readAsStringSync();
  }

  /// 写文件。默认允许覆盖，但覆盖前会先把旧版本存入回收站。
  Future<String> write(String rel, String content) async {
    await ensure();
    final path = _safe(rel);
    _assertNoEscape(path);
    final bytes = utf8.encode(content).length;
    if (!File(path).existsSync()) await _checkQuota(incomingBytes: bytes);
    if (bytes > maxFileBytes) {
      throw WorkspaceException(
          '内容超过单文件上限 ${(maxFileBytes / 1048576).toStringAsFixed(0)} MB');
    }
    final parent = Directory(p.dirname(path));
    if (!parent.existsSync()) await parent.create(recursive: true);
    final f = File(path);
    final backup = await _backup(f);
    await f.writeAsString(content, flush: true);
    final tail = backup.isEmpty ? '' : '（旧版已备份为 $backup）';
    return '已写入 ${_rel(path)}，${_human(bytes)}$tail';
  }

  Future<String> append(String rel, String content) async {
    await ensure();
    final path = _safe(rel);
    _assertNoEscape(path);
    final f = File(path);
    final old = f.existsSync() ? await f.readAsString() : '';
    final next = old + content;
    final bytes = utf8.encode(next).length;
    if (!f.existsSync()) await _checkQuota(incomingBytes: bytes);
    if (bytes > maxFileBytes) {
      throw const WorkspaceException('追加后超过单文件 2 MB 上限，已放弃');
    }
    final parent = Directory(p.dirname(path));
    if (!parent.existsSync()) await parent.create(recursive: true);
    final backup = await _backup(f);
    await f.writeAsString(next, flush: true);
    final tail = backup.isEmpty ? '' : '（追加前版本已备份为 $backup）';
    return '已追加到 ${_rel(path)}，现共 ${_human(bytes)}$tail';
  }

  Future<String> mkdir(String rel) async {
    await ensure();
    final path = _safe(rel);
    _assertNoEscape(path);
    final d = Directory(path);
    if (d.existsSync()) return '文件夹 ${_rel(path)} 已存在';
    await d.create(recursive: true);
    return '已新建文件夹 ${_rel(path)}';
  }

  /// 删除 = 移入回收站，永不真删。
  Future<String> delete(String rel) async {
    await ensure();
    final path = _safe(rel);
    _assertNoEscape(path);
    final entity = FileSystemEntity.typeSync(path);
    if (entity == FileSystemEntityType.notFound) {
      throw const WorkspaceException('要删除的文件不存在');
    }
    final dest = p.join(trashPath, _trashName(_rel(path)));
    if (entity == FileSystemEntityType.directory) {
      await Directory(path).rename(dest);
    } else {
      await File(path).rename(dest);
    }
    return '已把 ${_rel(path)} 移入回收站（未真正删除，可在设置页恢复）';
  }

  Future<String> rename(String from, String to) async {
    await ensure();
    final src = _safe(from);
    final dst = _safe(to);
    _assertNoEscape(src);
    _assertNoEscape(dst);
    if (FileSystemEntity.typeSync(src) == FileSystemEntityType.notFound) {
      throw const WorkspaceException('源文件不存在');
    }
    if (File(dst).existsSync() || Directory(dst).existsSync()) {
      throw const WorkspaceException('目标文件已存在，请先删除或换名');
    }
    final parent = Directory(p.dirname(dst));
    if (!parent.existsSync()) await parent.create(recursive: true);
    if (Directory(src).existsSync()) {
      await Directory(src).rename(dst);
    } else {
      await File(src).rename(dst);
    }
    return '已把 ${_rel(src)} 重命名为 ${_rel(dst)}';
  }

  Future<List<WorkspaceEntry>> trashList() async {
    await ensure();
    final dir = Directory(trashPath);
    final out = <WorkspaceEntry>[];
    await for (final e in dir.list(followLinks: false)) {
      final stat = e.statSync();
      out.add(WorkspaceEntry(
        rel: p.basename(e.path),
        name: p.basename(e.path),
        isDir: stat.type == FileSystemEntityType.directory,
        size: stat.size,
        modifiedMs: stat.modified.millisecondsSinceEpoch,
      ));
    }
    // 按条目名（时间戳前缀）倒序：文件系统 mtime 在同一毫秒内会并列，
    // 「恢复最近一条」必须稳定指向最后一次操作，而不是随机挑一个。
    out.sort((a, b) => b.rel.compareTo(a.rel));
    return out;
  }

  Future<String> restore(String trashName) async {
    await ensure();
    if (trashName.contains('/') ||
        trashName.contains('\\') ||
        trashName.startsWith('..')) {
      throw const WorkspaceException('回收站条目名不合法');
    }
    final src = p.join(trashPath, trashName);
    if (!File(src).existsSync() && !Directory(src).existsSync()) {
      throw const WorkspaceException('回收站里没有这个条目');
    }
    // 去掉「微秒_序号_」前缀与 .bak 后缀，再把 __ 还原成 /，回到原子目录。
    // 同时兼容旧格式的「毫秒_」前缀。
    var name = trashName.replaceFirst(RegExp(r'^\d+_(?:\d+_)?'), '');
    if (name.endsWith('.bak')) name = name.substring(0, name.length - 4);
    name = name.replaceAll('__', '/');
    if (name.isEmpty) name = 'restored.txt';
    var dest = _safe(name);
    var i = 1;
    while (File(dest).existsSync() || Directory(dest).existsSync()) {
      final ext = p.extension(name);
      final stem = name.substring(0, name.length - ext.length);
      dest = _safe('${stem}_$i$ext');
      i++;
    }
    final parent = Directory(p.dirname(dest));
    if (!parent.existsSync()) await parent.create(recursive: true);
    if (Directory(src).existsSync()) {
      await Directory(src).rename(dest);
    } else {
      await File(src).rename(dest);
    }
    return '已恢复为 ${_rel(dest)}';
  }

  Future<String> clearTrash() async {
    await ensure();
    final dir = Directory(trashPath);
    var n = 0;
    await for (final e in dir.list(followLinks: false)) {
      await e.delete(recursive: true);
      n++;
    }
    return '已永久清空回收站的 $n 个条目（此操作不可撤销）';
  }

  Future<({int files, int bytes, int trashFiles})> usage() async {
    await ensure();
    var files = 0;
    var bytes = 0;
    var trash = 0;
    await for (final e in _rootDir.list(recursive: true, followLinks: false)) {
      if (e is! File) continue;
      if (p.isWithin(trashPath, e.path)) {
        trash++;
      } else if (!_isReserved(e)) {
        files++;
        bytes += e.statSync().size;
      }
    }
    return (files: files, bytes: bytes, trashFiles: trash);
  }

  Future<void> log(AgentLogEntry e) async {
    await ensure();
    final f = File(logPath);
    final line = jsonEncode(e.toJson());
    if (!f.existsSync()) {
      await f.writeAsString('$line\n', flush: true);
      return;
    }
    final lines = await f.readAsLines();
    lines.add(line);
    final trimmed = lines.length > maxLogLines
        ? lines.sublist(lines.length - (maxLogLines * 4 ~/ 5))
        : lines;
    final tmp = File('$logPath.tmp');
    await tmp.writeAsString('${trimmed.join('\n')}\n', flush: true);
    await tmp.rename(logPath);
  }

  Future<List<AgentLogEntry>> readLog({int limit = 80}) async {
    await ensure();
    final f = File(logPath);
    if (!f.existsSync()) return const <AgentLogEntry>[];
    final lines = await f.readAsLines();
    final start = lines.length > limit ? lines.length - limit : 0;
    final out = <AgentLogEntry>[];
    for (final l in lines.sublist(start)) {
      if (l.trim().isEmpty) continue;
      try {
        out.add(AgentLogEntry.fromJson(
            jsonDecode(l) as Map<dynamic, dynamic>));
      } catch (_) {}
    }
    return out.reversed.toList();
  }

  String _human(int bytes) => bytes < 1024
      ? '$bytes B'
      : bytes < 1048576
          ? '${(bytes / 1024).toStringAsFixed(1)} KB'
          : '${(bytes / 1048576).toStringAsFixed(1)} MB';
}

import 'dart:convert';

import 'package:shared_preferences/shared_preferences.dart';

import '../models/models.dart';
import 'llm_client.dart' show LlmRequest;

/// 「命中缓存」的两类来源。
///
/// - `prompt`：服务端提示词缓存（OpenAI `prompt_tokens_details.cached_tokens`、
///   Anthropic `cache_read_input_tokens` 等）。请求照常发出，但命中的输入
///   token 按折扣计价，是真实省下的钱。
/// - `response`：本地响应复用。完全相同的请求（同地址、同模型、同消息、
///   同采样参数）在有效期内直接返回上次的回答，**不再发起网络请求**。
///   主对话是流式 `chat()`，不走这条路径，所以正常聊天永远拿到新回答；
///   受益的是圆桌会议、模拟人生、小游戏、深度研究这类重复度高的内部调用。
enum CacheHitKind { prompt, response }

class CacheHitEntry {
  final int at;
  final String model;
  final CacheHitKind kind;
  final int tokens;
  final String summary;

  const CacheHitEntry({
    required this.at,
    required this.model,
    required this.kind,
    required this.tokens,
    this.summary = '',
  });

  String get kindId => kind == CacheHitKind.prompt ? 'prompt' : 'response';

  Map<String, dynamic> toJson() => {
        'at': at,
        'model': model,
        'kind': kindId,
        'tokens': tokens,
        if (summary.isNotEmpty) 'summary': summary,
      };

  factory CacheHitEntry.fromJson(Map<dynamic, dynamic> j) => CacheHitEntry(
        at: (j['at'] as num?)?.toInt() ?? 0,
        model: (j['model'] ?? '').toString(),
        kind: j['kind'] == 'prompt'
            ? CacheHitKind.prompt
            : CacheHitKind.response,
        tokens: (j['tokens'] as num?)?.toInt() ?? 0,
        summary: (j['summary'] ?? '').toString(),
      );
}

/// 命中台账。累计数字与最近记录分开存，记录只留最新 200 条，
/// 避免长期使用后 JSON 无限膨胀。
class CacheLedger {
  CacheLedger();

  static const int maxRecords = 200;

  int promptHits = 0;
  int responseHits = 0;
  int promptTokens = 0;
  int responseTokens = 0;
  final List<CacheHitEntry> records = [];

  int get hits => promptHits + responseHits;
  int get tokens => promptTokens + responseTokens;

  /// 按模型汇总的命中 token，供查看页分组展示。
  Map<String, int> get byModel {
    final m = <String, int>{};
    for (final r in records) {
      m[r.model] = (m[r.model] ?? 0) + r.tokens;
    }
    return m;
  }

  void add(CacheHitEntry e) {
    records.insert(0, e);
    if (records.length > maxRecords) records.removeRange(maxRecords, records.length);
    if (e.kind == CacheHitKind.prompt) {
      promptHits++;
      promptTokens += e.tokens;
    } else {
      responseHits++;
      responseTokens += e.tokens;
    }
  }

  void clear() {
    promptHits = 0;
    responseHits = 0;
    promptTokens = 0;
    responseTokens = 0;
    records.clear();
  }

  Map<String, dynamic> toJson() => {
        'promptHits': promptHits,
        'responseHits': responseHits,
        'promptTokens': promptTokens,
        'responseTokens': responseTokens,
        'records': [for (final r in records) r.toJson()],
      };

  factory CacheLedger.fromJson(Map<dynamic, dynamic> j) {
    final l = CacheLedger();
    l.promptHits = (j['promptHits'] as num?)?.toInt() ?? 0;
    l.responseHits = (j['responseHits'] as num?)?.toInt() ?? 0;
    l.promptTokens = (j['promptTokens'] as num?)?.toInt() ?? 0;
    l.responseTokens = (j['responseTokens'] as num?)?.toInt() ?? 0;
    final r = j['records'];
    if (r is List) {
      for (final e in r) {
        if (e is Map) l.records.add(CacheHitEntry.fromJson(e));
      }
      if (l.records.length > maxRecords) {
        l.records.removeRange(maxRecords, l.records.length);
      }
    }
    return l;
  }
}

class CachedAnswer {
  final String text;
  final TokenUsage? usage;
  final int at;

  const CachedAnswer({required this.text, this.usage, required this.at});

  Map<String, dynamic> toJson() => {
        'text': text,
        'at': at,
        if (usage != null) 'usage': usage!.toJson(),
      };

  factory CachedAnswer.fromJson(Map<dynamic, dynamic> j) => CachedAnswer(
        text: (j['text'] ?? '').toString(),
        at: (j['at'] as num?)?.toInt() ?? 0,
        usage: j['usage'] is Map
            ? TokenUsage.fromJson(Map<dynamic, dynamic>.from(j['usage'] as Map))
            : null,
      );
}

/// 本地响应缓存。纯 Dart 数据结构，持久化交给 [CacheStore]，方便单测。
class ResponseCache {
  ResponseCache({this.enabled = true, this.maxEntries = 120})
      : _entries = <String, CachedAnswer>{};

  bool enabled;
  final int maxEntries;

  /// 命中有效期：6 小时。过期的回答会被丢弃，不会把上周的结论端出来。
  static const int ttlMs = 6 * 60 * 60 * 1000;

  final Map<String, CachedAnswer> _entries;
  int hitCount = 0;

  int get size => _entries.length;

  /// 稳定哈希（FNV-1a 64 位）。不用 `String.hashCode`：它只在单个进程内
  /// 稳定，而缓存要落盘、重启后继续命中。
  static String keyFor(LlmRequest req) {
    String payload;
    try {
      payload = jsonEncode([
        req.baseUrl.trim(),
        req.model.trim(),
        req.messages,
        req.temperature,
        req.topP,
        req.maxTokens,
        req.reasoningEffort,
        req.deepThinking,
        req.thinkingBudget,
      ]);
    } catch (_) {
      // 消息里偶尔会塞进不可序列化的对象，此时退化为「不可能命中」的 key，
      // 让请求照常发出，绝不因为缓存逻辑把功能弄坏。
      payload = 'unserializable:${DateTime.now().microsecondsSinceEpoch}';
    }
    var h = 0x23d25b;
    for (final unit in payload.codeUnits) {
      h ^= unit;
      h = (h * 0x100000001b3) & 0x7fffffffffffffff;
    }
    return 'c${h.toRadixString(16)}';
  }

  /// 取最后一条用户消息做展示摘要，避免把整段 System Prompt 塞进记录。
  static String summaryOf(LlmRequest req) {
    for (final m in req.messages.reversed) {
      if (m['role'] == 'user') {
        final s = (m['content'] ?? '').toString().replaceAll('\n', ' ').trim();
        return s.length > 46 ? '${s.substring(0, 46)}…' : s;
      }
    }
    return '';
  }

  CachedAnswer? get(String key) {
    final now = DateTime.now().millisecondsSinceEpoch;
    final v = _entries[key];
    if (v == null) return null;
    if (v.text.trim().isEmpty || now - v.at > ttlMs) {
      _entries.remove(key);
      return null;
    }
    hitCount++;
    return v;
  }

  void put(String key, String text, TokenUsage? usage) {
    if (text.trim().isEmpty || text.length > 60000) return;
    _entries[key] = CachedAnswer(
        text: text, usage: usage, at: DateTime.now().millisecondsSinceEpoch);
    if (_entries.length > maxEntries) {
      // 简单 LRU 近似：按写入时间淘汰最旧的一半。
      final sorted = _entries.entries.toList()
        ..sort((a, b) => a.value.at.compareTo(b.value.at));
      for (final e in sorted.take(_entries.length - maxEntries)) {
        _entries.remove(e.key);
      }
    }
  }

  void clear() {
    _entries.clear();
    hitCount = 0;
  }

  Map<String, dynamic> toJson() => {
        'hitCount': hitCount,
        'entries': {
          for (final e in _entries.entries) e.key: e.value.toJson(),
        },
      };

  void load(Map<dynamic, dynamic> j) {
    hitCount = (j['hitCount'] as num?)?.toInt() ?? 0;
    final e = j['entries'];
    if (e is Map) {
      e.forEach((k, v) {
        if (v is Map) {
          _entries[k.toString()] =
              CachedAnswer.fromJson(Map<dynamic, dynamic>.from(v));
        }
      });
    }
  }
}

/// 命中台账与响应缓存的落盘。和会话历史分开：历史可能有几 MB，
/// 这里只有几十 KB，用 SharedPreferences 原子写入即可。
class CacheStore {
  CacheStore({Map<String, String>? memory}) : _memory = memory;

  final Map<String, String>? _memory;
  static const String kLedger = 'cache.ledger.v1';
  static const String kResponses = 'cache.responses.v1';

  Future<String?> _read(String key) async {
    final m = _memory;
    if (m != null) return m[key];
    return (await SharedPreferences.getInstance()).getString(key);
  }

  Future<void> _write(String key, String value) async {
    final m = _memory;
    if (m != null) {
      m[key] = value;
      return;
    }
    await (await SharedPreferences.getInstance()).setString(key, value);
  }

  Future<void> load(CacheLedger ledger, ResponseCache cache) async {
    try {
      final l = await _read(kLedger);
      if (l != null && l.isNotEmpty) {
        final v = jsonDecode(l);
        if (v is Map) {
          final loaded = CacheLedger.fromJson(Map<dynamic, dynamic>.from(v));
          ledger.promptHits = loaded.promptHits;
          ledger.responseHits = loaded.responseHits;
          ledger.promptTokens = loaded.promptTokens;
          ledger.responseTokens = loaded.responseTokens;
          ledger.records
            ..clear()
            ..addAll(loaded.records);
        }
      }
      final r = await _read(kResponses);
      if (r != null && r.isNotEmpty) {
        final v = jsonDecode(r);
        if (v is Map) cache.load(Map<dynamic, dynamic>.from(v));
      }
    } catch (_) {
      // 存档损坏就当空，不让页面起不来。
    }
  }

  Future<void> save(CacheLedger ledger, ResponseCache cache) async {
    await _write(kLedger, jsonEncode(ledger.toJson()));
    await _write(kResponses, jsonEncode(cache.toJson()));
  }

  Future<void> clear() async {
    await _write(kLedger, '{}');
    await _write(kResponses, '{}');
  }
}

import 'dart:io' show Platform;

import 'package:flutter/services.dart';

