enum FreeKind { publicSource, local }

/// 一个无需密钥的 OpenAI 兼容端点。
class FreeEndpoint {
  final String id;
  final String name;

  /// 提供方，用于把同一家的多个模型收在一起显示。
  final String provider;
  final String baseUrl;
  final String model;
  final FreeKind kind;
  final String note;
  final bool vision;
  final List<String> fallbackModels;

  const FreeEndpoint({
    required this.id,
    required this.name,
    this.provider = '',
    required this.baseUrl,
    required this.model,
    this.kind = FreeKind.publicSource,
    this.note = '',
    this.vision = false,
    this.fallbackModels = const [],
  });

  String get providerLabel => provider.isEmpty ? name : provider;

  FreeEndpoint copyWith({String? model, String? name}) => FreeEndpoint(
        id: id,
        name: name ?? this.name,
        provider: provider,
        baseUrl: baseUrl,
        model: model ?? this.model,
        kind: kind,
        note: note,
        vision: vision,
        fallbackModels: fallbackModels,
      );
}

