/// 一次探测的结果。
class FreeHit {
  final FreeEndpoint endpoint;
  final bool ok;
  final int latencyMs;
  final List<String> models;
  final String error;
  final int status;

  const FreeHit({
    required this.endpoint,
    required this.ok,
    required this.latencyMs,
    this.models = const [],
    this.error = '',
    this.status = 0,
  });

  String get name => endpoint.name;
  String get baseUrl => endpoint.baseUrl;
  String get provider => endpoint.providerLabel;
  bool get vision => endpoint.vision;

  /// 可用于接入的模型列表：成功时第一个一定是探测通过的那个。
  List<String> get usableModels => models.isEmpty ? [endpoint.model] : models;
}

class _ChatResult {
  final bool ok;
  final int status;
  final String body;
  const _ChatResult(this.ok, this.status, this.body);
}

/// 免密模型探测。
///
/// 只看 `/models` 是不可靠的：很多公开网关会返回完整模型列表，但真正
/// 发起对话时回 402（要额度）、429（要等）或 401（要 Key）。所以这里
/// 以「一次 1 token 的真实对话」作为唯一判定标准。
class FreePool {
  static final Dio _dio = Dio(BaseOptions(
    connectTimeout: const Duration(seconds: 10),
    receiveTimeout: const Duration(seconds: 25),
    sendTimeout: const Duration(seconds: 15),
    responseType: ResponseType.plain,
    validateStatus: (_) => true,
    followRedirects: true,
  ));

  static String _trim(String s) {
    var b = s.trim();
    while (b.endsWith('/')) {
      b = b.substring(0, b.length - 1);
    }
    if (b.endsWith('/chat/completions')) {
      b = b.substring(0, b.length - '/chat/completions'.length);
    }
    return b;
  }

  /// 把 HTTP 状态码翻译成用户能判断下一步的短句。
  static String explain(int status, String body) {
    final b = body.toLowerCase();
    if (status == 0) {
      return b.contains('timeout') ? '超时未响应' : '域名不可达';
    }
    if (status == 401) return '需要密钥（401）';
    if (status == 403) return '拒绝访问（403），可能地区受限';
    if (status == 402) return '需要订阅或额度（402）';
    if (status == 404) return '路径不对（404）';
    if (status == 408) return '对方超时（408）';
    if (status == 429) return '限流或当日额度用尽（429）';
    if (status >= 500) return '对方服务异常（$status）';
    return 'HTTP $status';
  }

  /// 判断返回体是不是一段真的对话结果，避免把网关的 200 错误页当成功。
  static bool looksLikeCompletion(String body) {
    final b = body.trim();
    if (b.isEmpty) return false;
    if (!b.contains('"choices"') && !b.contains('"content"')) return false;
    if (b.contains('"error"') && !b.contains('"choices"')) return false;
    return true;
  }

  static Future<_ChatResult> _chat(
      String base, String model, String key) async {
    final sw = Stopwatch()..start();
    try {
      final resp = await _dio.post<String>(
        '$base/chat/completions',
        data: '{"model":"$model","messages":[{"role":"user","content":"hi"}],'
            '"max_tokens":1,"stream":false}',
        options: Options(
          headers: <String, dynamic>{
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            if (key.trim().isNotEmpty) 'Authorization': 'Bearer ${key.trim()}',
          },
        ),
      );
      sw.stop();
      final code = resp.statusCode ?? 0;
      final body = resp.data ?? '';
      if (code == 200 && looksLikeCompletion(body)) {
        return _ChatResult(true, code, body);
      }
      return _ChatResult(false, code, body);
    } on DioException catch (e) {
      sw.stop();
      final timeout = e.type == DioExceptionType.connectionTimeout ||
          e.type == DioExceptionType.receiveTimeout ||
          e.type == DioExceptionType.sendTimeout;
      return _ChatResult(false, 0, timeout ? 'timeout' : 'unreachable');
    } catch (e) {
      sw.stop();
      return _ChatResult(false, 0, e.toString());
    }
  }

  /// 探测单个来源。成功时会把 `/models` 里的模型一并带回。
  static Future<FreeHit> probe(FreeEndpoint e, {String key = ''}) async {
    final sw = Stopwatch()..start();
    final base = _trim(e.baseUrl);
    var listed = const <String>[];

    // 模型列表只是加分项，失败不阻断对话探测。
    // 有的端点把清单挂在父路径上（text.pollinations.ai/openai → /models）。
    final modelUrls = <String>['$base/models'];
    if (base.endsWith('/openai')) {
      modelUrls
          .add('${base.substring(0, base.length - '/openai'.length)}/models');
    }
    for (final u in modelUrls) {
      try {
        final r = await _dio.get<String>(
          u,
          options: Options(headers: <String, dynamic>{
            'Accept': 'application/json',
            if (key.trim().isNotEmpty) 'Authorization': 'Bearer ${key.trim()}',
          }, receiveTimeout: const Duration(seconds: 8)),
        );
        if ((r.statusCode ?? 0) == 200) {
          final list = RelayProbe.parseModels(r.data);
          if (list.isNotEmpty) {
            listed = list;
            break;
          }
        }
      } catch (_) {}
    }

    final candidates = <String>[];
    void add(String m) {
      final v = m.trim();
      if (v.isNotEmpty && !candidates.contains(v)) candidates.add(v);
    }

    add(e.model);
    for (final m in e.fallbackModels) {
      add(m);
    }
    for (final m in listed.take(4)) {
      add(m);
    }
    if (candidates.isEmpty) add('gpt-3.5-turbo');

    String? okModel;
    var lastStatus = 0;
    var lastBody = '';
    // 最多试两个模型，避免一个来源就拖掉一分钟。
    for (final m in candidates.take(2)) {
      final r = await _chat(base, m, key);
      lastStatus = r.status;
      lastBody = r.body;
      if (r.ok) {
        okModel = m;
        break;
      }
      // 认证 / 额度类错误换模型也没用，直接收手。
      if (r.status == 401 || r.status == 402 || r.status == 403) break;
    }

    sw.stop();
    if (okModel != null) {
      final models = <String>[okModel];
      for (final m in listed) {
        if (!models.contains(m)) models.add(m);
      }
      return FreeHit(
        endpoint: e,
        ok: true,
        latencyMs: sw.elapsedMilliseconds,
        models: models.take(12).toList(),
      );
    }
    return FreeHit(
      endpoint: e,
      ok: false,
      latencyMs: sw.elapsedMilliseconds,
      status: lastStatus,
      error: lastStatus == 200
          ? '返回的不是对话结果，可能被网关拦截'
          : explain(lastStatus, lastBody),
    );
  }

  /// 并发探测，默认 6 路。十几条源分两批跑完，比 3 路快一倍；
  /// 公开源本身有按 IP 的并发限制，再高就容易自己把自己限流。
  static Future<List<FreeHit>> probeAll({
    required List<FreeEndpoint> endpoints,
    String key = '',
    int concurrency = 6,
    ValueChanged<double>? onProgress,
  }) async {
    final hits = <FreeHit>[];
    if (endpoints.isEmpty) {
      onProgress?.call(1);
      return hits;
    }
    var done = 0;
    for (var i = 0; i < endpoints.length; i += concurrency) {
      final chunk = endpoints.skip(i).take(concurrency).toList();
      final part = await Future.wait(chunk.map((e) => probe(e, key: key)));
      hits.addAll(part);
      done += chunk.length;
      onProgress?.call(done / endpoints.length);
    }
    // 可用的排前面，其次按延迟。
    hits.sort((a, b) {
      if (a.ok != b.ok) return a.ok ? -1 : 1;
      return a.latencyMs.compareTo(b.latencyMs);
    });
    return hits;
  }

  /// 一键接入用的「最优源」：延迟最低的可用项。
  static FreeHit? fastest(List<FreeHit> hits) {
    FreeHit? best;
    for (final h in hits) {
      if (!h.ok) continue;
      if (best == null || h.latencyMs < best.latencyMs) best = h;
    }
    return best;
  }

  /// 从已有连接里挑出「本机 / 内网 + 没填 Key」的，并入免密池。
  /// 这样用户自己跑的 g4f、Ollama 不必再手动录一遍。
  static List<FreeEndpoint> localFromProfiles(List<ApiProfile> profiles) {
    final out = <FreeEndpoint>[];
    for (final p in profiles) {
      if (p.apiKey.trim().isNotEmpty) continue;
      final host = p.hostLabel;
      final localish =
          RelayProbe.isLoopback(host) || RelayProbe.isPrivateHost(host);
      if (!localish) continue;
      if (p.baseUrl.trim().isEmpty) continue;
      out.add(FreeEndpoint(
        id: 'local_${p.id}',
        name: p.name.isEmpty ? '本机服务' : p.name,
        provider: '本机 / 内网',
        baseUrl: p.baseUrl,
        model: p.model.isEmpty
            ? (p.cachedModels.isNotEmpty
                ? p.cachedModels.first
                : 'gpt-3.5-turbo')
            : p.model,
        kind: FreeKind.local,
        note: '来自你的连接配置',
        fallbackModels: p.cachedModels.take(3).toList(),
      ));
    }
    return out;
  }
}

import 'dart:convert';
import 'dart:io';

import 'package:path_provider/path_provider.dart';

import '../models/models.dart';

/// 一次落盘的完整快照：会话 + 当前会话 + 用量统计。
///
/// 以前这三样只在内存里，杀掉进程就全没了；现在统一写进应用私有目录的
/// 一个 JSON 文件，冷启动时原样读回来。
class HistorySnapshot {
  final List<Conversation> conversations;
  final String activeId;
  final Map<String, dynamic>? usage;

  const HistorySnapshot({
    required this.conversations,
    required this.activeId,
    this.usage,
  });
}

/// 会话历史的本地存储。
///
/// 用文件而不是 SharedPreferences：一条带图片的消息可能几百 KB，
/// SharedPreferences 是整份 XML 读写的，塞进去会让启动和保存都变慢。
/// 写入走「临时文件 + rename」，避免写一半被杀进程留下半个 JSON。
class HistoryStore {
  /// 测试可注入临时目录；生产走 path_provider。
  final Future<Directory> Function()? dirProvider;

  HistoryStore({this.dirProvider});

  static const String fileName = 'aigent_history.json';

  /// 会话数上限：再多也没人翻，留着只会拖慢启动。
  static const int maxConversations = 80;

  /// 单会话消息上限。
  static const int maxMessages = 400;

  /// 单张图片进历史的体积上限；超过只留文件名，不存字节。
  static const int maxImageBytes = 1200 * 1024;

  Future<File> _file() async {
    final d = dirProvider != null
        ? await dirProvider!()
        : await getApplicationSupportDirectory();
    if (!await d.exists()) await d.create(recursive: true);
    return File('${d.path}/$fileName');
  }

  Future<HistorySnapshot?> load() async {
    try {
      final f = await _file();
      if (!await f.exists()) return null;
      final raw = await f.readAsString();
      if (raw.trim().isEmpty) return null;
      final map = jsonDecode(raw);
      if (map is! Map) return null;
      final list = map['conversations'];
      final convs = <Conversation>[];
      if (list is List) {
        for (final e in list.whereType<Map>()) {
          final c = Conversation.fromJson(Map<dynamic, dynamic>.from(e));
          if (c.id.isEmpty) continue;
          // 恢复出来的一定不是「生成中」：上次的流早就断了。
          for (final m in c.messages) {
            m.streaming = false;
          }
          c.generating = false;
          c.status = '';
          convs.add(c);
        }
      }
      final usage = map['usage'];
      return HistorySnapshot(
        conversations: convs,
        activeId: (map['activeId'] ?? '').toString(),
        usage: usage is Map ? Map<String, dynamic>.from(usage) : null,
      );
    } catch (_) {
      // 文件损坏不该让应用起不来：挪到一边，下次从空历史开始。
      try {
        final f = await _file();
        if (await f.exists()) {
          await f.rename('${f.path}.bad');
        }
      } catch (_) {}
      return null;
    }
  }

  Future<void> save(HistorySnapshot snapshot) async {
    try {
      final convs = _prepare(snapshot.conversations);
      final payload = <String, dynamic>{
        'v': 1,
        'savedAt': DateTime.now().toIso8601String(),
        'activeId': snapshot.activeId,
        'conversations': [for (final c in convs) c.toJson()],
        if (snapshot.usage != null) 'usage': snapshot.usage,
      };
      final text = jsonEncode(payload);
      final f = await _file();
      final tmp = File('${f.path}.tmp');
      await tmp.writeAsString(text, flush: true);
      await tmp.rename(f.path);
    } catch (_) {
      // 存储满 / 权限异常：不影响当前会话继续用，只是这次没存上。
    }
  }

  Future<void> clear() async {
    try {
      final f = await _file();
      if (await f.exists()) await f.delete();
    } catch (_) {}
  }

  /// 落盘前裁剪：旧会话整条丢弃，超长会话保留最近的消息，
  /// 超大图片只留文件名——宁可少存一张图，也不能让文件无限膨胀。
  ///
  /// 全程只动副本：内存里的会话和消息不能因为「存了一次盘」就被截断。
  List<Conversation> _prepare(List<Conversation> all) {
    final sorted = List<Conversation>.of(all)
      ..sort((a, b) => b.at.compareTo(a.at));
    final keep = sorted.take(maxConversations).toList();
    final out = <Conversation>[];
    for (final c in keep) {
      final msgs = c.messages.length > maxMessages
          ? c.messages.sublist(c.messages.length - maxMessages)
          : c.messages;
      final cloned = <ChatMessage>[];
      for (final m in msgs) {
        final copy = _cloneMessage(m);
        copy.attachments = [
          for (final a in m.attachments)
            (a.imageBytes != null && a.imageBytes!.length > maxImageBytes)
                ? Attachment(
                    id: a.id,
                    name: a.name,
                    kind: a.kind,
                    size: a.size,
                    text: a.text,
                    imageMime: a.imageMime,
                  )
                : a,
        ];
        cloned.add(copy);
      }
      out.add(Conversation(
        id: c.id,
        title: c.title,
        at: c.at,
        messages: cloned,
      )..personaId = c.personaId);
    }
    return out;
  }

  ChatMessage _cloneMessage(ChatMessage m) {
    final c = ChatMessage(
      id: m.id,
      role: m.role,
      content: m.content,
      at: m.at,
      attachments: List<Attachment>.of(m.attachments),
      citations: List<Citation>.of(m.citations),
    );
    c.thinking = m.thinking;
    c.model = m.model;
    c.tierLabel = m.tierLabel;
    c.error = m.error;
    c.searchQuery = m.searchQuery;
    c.elapsedMs = m.elapsedMs;
    c.usage = m.usage;
    c.toolName = m.toolName;
    c.toolOk = m.toolOk;
    c.toolStep = m.toolStep;
    c.toolMs = m.toolMs;
    return c;
  }
}

