/// 圆桌会议、模拟人生、AI 小游戏共用同一份来源：用户先选一家连接，
/// 再进入这一家的模型列表挑具体模型。密钥只在内存中传递，绝不落盘。
class ProviderGroup {
  final String id;
  final String name;
  final String host;
  final String baseUrl;
  final String apiKey;
  final List<String> models;
  final bool active;

  const ProviderGroup({
    required this.id,
    required this.name,
    required this.host,
    required this.baseUrl,
    required this.apiKey,
    required this.models,
    this.active = false,
  });
}

/// 一次两级选择的结果。
class ModelChoice {
  final String baseUrl;
  final String apiKey;
  final String model;
  final String providerName;

  const ModelChoice({
    required this.baseUrl,
    required this.apiKey,
    required this.model,
    required this.providerName,
  });

  String get label => '$providerName · $model';
}

/// 某个连接下可见的模型：当前模型优先，其次是该连接缓存的模型。
///
/// [activeModels] 是活动连接刚刚刷新到内存里的列表（可能还没写回 profile），
/// 由调用方从 AppState 传入；非活动连接只看自己的缓存，避免串台。
List<String> modelsForProfile(
  AppSettings s,
  ApiProfile p, {
  List<String> activeModels = const [],
}) {
  final isActive = p.id == s.activeProfileId;
  final raw = <String>[
    if (isActive) s.model,
    p.model,
    if (isActive) ...activeModels,
    ...p.cachedModels,
  ];
  final seen = <String>{};
  final out = <String>[];
  for (final m in raw) {
    final v = m.trim();
    if (v.isEmpty || !seen.add(v)) continue;
    out.add(v);
  }
  return out;
}

/// 把设置里的多连接整理成可展示的分组列表。
List<ProviderGroup> buildProviderGroups(
  AppSettings s, {
  List<String> activeModels = const [],
}) {
  return [
    for (final p in s.profiles)
      ProviderGroup(
        id: p.id,
        name: p.name,
        host: p.hostLabel,
        baseUrl: p.baseUrl,
        apiKey: p.apiKey,
        models: modelsForProfile(s, p, activeModels: activeModels),
        active: p.id == s.activeProfileId,
      ),
  ];
}

/// 「沿用当前对话模型」的快捷结果。
ModelChoice currentChatChoice(AppSettings s) => ModelChoice(
      baseUrl: s.baseUrl,
      apiKey: s.apiKey,
      model: s.model,
      providerName: s.activeProfile.name,
    );

/// 按关键词过滤模型 ID（大小写不敏感）。
List<String> filterModels(List<String> models, String query) {
  final q = query.trim().toLowerCase();
  if (q.isEmpty) return models;
  return models.where((m) => m.toLowerCase().contains(q)).toList();
}

/// 按地址从当前连接里补回密钥（存档不写密钥）。
String apiKeyForBaseUrl(AppSettings s, String baseUrl) {
  if (baseUrl.trim() == s.baseUrl.trim()) return s.apiKey;
  for (final p in s.profiles) {
    if (p.baseUrl.trim() == baseUrl.trim()) return p.apiKey;
  }
  return '';
}

/// 把「记住的模型」还原成可直接发请求的 [ModelChoice]。
/// 没记住、或记住的模型已失效时，一律退回当前对话模型，避免请求打到空地址。
ModelChoice resolveModelChoice(
  AppSettings s, {
  String? baseUrl,
  String? model,
  String? providerName,
}) {
  final b = (baseUrl ?? '').trim();
  final m = (model ?? '').trim();
  if (b.isEmpty || m.isEmpty) return currentChatChoice(s);
  final name = (providerName ?? '').trim().isNotEmpty
      ? providerName!.trim()
      : providerNameFor(s, b);
  return ModelChoice(
    baseUrl: b,
    apiKey: apiKeyForBaseUrl(s, b),
    model: m,
    providerName: name,
  );
}

/// 按 baseUrl 找连接名，用于把存档里只有地址的席位显示成可读文字。
String providerNameFor(AppSettings s, String baseUrl) {
  for (final p in s.profiles) {
    if (p.baseUrl.trim() == baseUrl.trim()) return p.name;
  }
  if (baseUrl.trim() == s.baseUrl.trim()) return s.activeProfile.name;
  try {
    final h = Uri.parse(baseUrl).host;
    if (h.isNotEmpty) return h;
  } catch (_) {}
  return baseUrl;
}

import 'dart:convert';
import 'package:dio/dio.dart';

class ApiParam {
  final String name;
  final String location;
  final String type;
  final bool required;

  const ApiParam({
    required this.name,
    required this.location,
    this.type = 'string',
    this.required = false,
  });

  Map<String, dynamic> toJson() => {
        'name': name,
        'location': location,
        'type': type,
        'required': required,
      };

  factory ApiParam.fromJson(Map<dynamic, dynamic> j) => ApiParam(
        name: (j['name'] ?? '').toString(),
        location: (j['location'] ?? 'query').toString(),
        type: (j['type'] ?? 'string').toString(),
        required: j['required'] == true,
      );
}

class ApiOperation {
  final String id;
  final String method;
  final String path;
  final String summary;
  final List<ApiParam> params;
  final Map<String, dynamic> bodySchema;

  const ApiOperation({
    required this.id,
    required this.method,
    required this.path,
    required this.summary,
    required this.params,
    this.bodySchema = const {},
  });

  Map<String, dynamic> toJson() => {
        'id': id,
        'method': method,
        'path': path,
        'summary': summary,
        'params': params.map((e) => e.toJson()).toList(),
        'bodySchema': bodySchema,
      };

  factory ApiOperation.fromJson(Map<dynamic, dynamic> j) => ApiOperation(
        id: (j['id'] ?? '').toString(),
        method: (j['method'] ?? 'get').toString(),
        path: (j['path'] ?? '/').toString(),
        summary: (j['summary'] ?? '').toString(),
        params: ((j['params'] as List?) ?? [])
            .whereType<Map>()
            .map((e) => ApiParam.fromJson(e))
            .toList(),
        bodySchema: j['bodySchema'] is Map
            ? Map<String, dynamic>.from(j['bodySchema'] as Map)
            : const {},
      );
}

/// 从 Swagger / OpenAPI JSON 生成工具清单，并代理模型发起真实 HTTP 请求。
class OpenApiPlugin {
  final String source;
  final String title;
  final String baseUrl;
  final List<ApiOperation> operations;
  final int loadedAt;
  final Dio _dio = Dio(BaseOptions(
    connectTimeout: const Duration(seconds: 15),
    receiveTimeout: const Duration(seconds: 25),
    sendTimeout: const Duration(seconds: 15),
    responseType: ResponseType.plain,
    validateStatus: (_) => true,
  ));

  OpenApiPlugin({
    required this.source,
    required this.title,
    required this.baseUrl,
    required this.operations,
    int? loadedAt,
  }) : loadedAt = loadedAt ?? DateTime.now().millisecondsSinceEpoch;

  Map<String, dynamic> toJson() => {
        'source': source,
        'title': title,
        'baseUrl': baseUrl,
        'operations': operations.map((e) => e.toJson()).toList(),
        'loadedAt': loadedAt,
      };

  factory OpenApiPlugin.fromJson(Map<dynamic, dynamic> j) => OpenApiPlugin(
        source: (j['source'] ?? '').toString(),
        title: (j['title'] ?? '').toString(),
        baseUrl: (j['baseUrl'] ?? '').toString(),
        operations: ((j['operations'] as List?) ?? [])
            .whereType<Map>()
            .map((e) => ApiOperation.fromJson(e))
            .toList(),
        loadedAt: (j['loadedAt'] as num?)?.toInt(),
      );

  static Future<OpenApiPlugin> load(String url, {String? apiKey}) async {
    final dio = Dio(BaseOptions(
      connectTimeout: const Duration(seconds: 15),
      receiveTimeout: const Duration(seconds: 25),
      validateStatus: (_) => true,
    ));
    final resp = await dio.get<dynamic>(
      url,
      options: Options(
        responseType: ResponseType.plain,
        headers: {
          if (apiKey != null && apiKey.isNotEmpty)
            'Authorization': 'Bearer $apiKey'
        },
      ),
    );
    final code = resp.statusCode ?? 0;
    if (code < 200 || code >= 300) {
      throw StateError('拉取 OpenAPI 文档失败：HTTP $code');
    }
    final raw = resp.data;
    Map<String, dynamic> doc;
    try {
      final v = raw is String ? jsonDecode(raw) : raw;
      if (v is! Map) throw StateError('文档根节点不是对象');
      doc = Map<String, dynamic>.from(v);
    } catch (e) {
      throw StateError('OpenAPI 文档不是合法 JSON：$e');
    }

    final src = Uri.tryParse(url);
    var base = '';
    final servers = doc['servers'];
    if (servers is List && servers.isNotEmpty && servers.first is Map) {
      base = (servers.first['url'] ?? '').toString();
    }
    if (base.isEmpty) {
      final host = (doc['host'] ?? '').toString();
      if (host.isNotEmpty) {
        final schemes = doc['schemes'];
        final scheme = (schemes is List && schemes.isNotEmpty)
            ? schemes.first.toString()
            : (src?.scheme.isNotEmpty == true ? src!.scheme : 'https');
        base = '$scheme://$host${(doc['basePath'] ?? '').toString()}';
      }
    }
    if (base.isEmpty && src != null) {
      base = '${src.scheme}://${src.host}${src.hasPort ? ':${src.port}' : ''}';
    }
    if (base.startsWith('/') && src != null) {
      base = src.resolve(base).toString();
    }
    while (base.endsWith('/')) {
      base = base.substring(0, base.length - 1);
    }

    final info = doc['info'];
    final title =
        info is Map ? (info['title'] ?? 'OpenAPI 插件').toString() : 'OpenAPI 插件';

    final ops = <ApiOperation>[];
    final paths = doc['paths'];
    const methods = {'get', 'post', 'put', 'patch', 'delete'};
    if (paths is Map) {
      paths.forEach((pathKey, methodsMap) {
        if (methodsMap is! Map) return;
        final common = methodsMap['parameters'];
        methodsMap.forEach((mKey, op) {
          final method = mKey.toString().toLowerCase();
          if (!methods.contains(method) || op is! Map) return;
          final operation = Map<String, dynamic>.from(op);
          final ps = <ApiParam>[];
          void collect(dynamic list) {
            if (list is! List) return;
            for (final p in list) {
              if (p is! Map) continue;
              final pm = Map<String, dynamic>.from(p);
              final loc = (pm['in'] ?? 'query').toString();
              final schema = pm['schema'];
              ps.add(ApiParam(
                name: (pm['name'] ?? '').toString(),
                location: loc,
                type: schema is Map
                    ? (schema['type'] ?? 'string').toString()
                    : 'string',
                required: pm['required'] == true,
              ));
            }
          }

          collect(common);
          collect(operation['parameters']);

          Map<String, dynamic> bodySchema = const {};
          final rb = operation['requestBody'];
          if (rb is Map) {
            final content = rb['content'];
            if (content is Map) {
              dynamic ct = content['application/json'];
              if (ct == null) {
                for (final v in content.values) {
                  ct = v;
                  break;
                }
              }
              if (ct is Map && ct['schema'] is Map) {
                bodySchema = Map<String, dynamic>.from(ct['schema'] as Map);
              }
            }
          }
          if (bodySchema['properties'] is Map) {
            (bodySchema['properties'] as Map).forEach((k, v) {
              ps.add(ApiParam(
                name: k.toString(),
                location: 'body',
                type: v is Map ? (v['type'] ?? 'string').toString() : 'string',
                required: (bodySchema['required'] is List) &&
                    (bodySchema['required'] as List).contains(k),
              ));
            });
          }

          final safe = '$method ${pathKey.toString()}'
              .replaceAll(RegExp(r'[^A-Za-z0-9]+'), '_');
          final id = (operation['operationId'] ?? safe).toString();
          ops.add(ApiOperation(
            id: id,
            method: method,
            path: pathKey.toString(),
            summary: (operation['summary'] ?? operation['description'] ?? '')
                .toString(),
            params: ps,
            bodySchema: bodySchema,
          ));
        });
      });
    }
    if (ops.isEmpty) throw StateError('文档中没有可调用的 paths 操作');
    return OpenApiPlugin(
        source: url, title: title, baseUrl: base, operations: ops);
  }

  String get toolPrompt {
    final b = StringBuffer();
    b.writeln('[外部工具] 你可以调用 HTTP 插件 API 来完成任务。');
    b.writeln('需要调用工具时，只输出下面这一行 JSON，不要附加解释：');
    b.writeln('{"tool":"操作ID","arguments":{"参数名":"值"}}');
    b.writeln('可用工具（来自 $title，共 ${operations.length} 个）：');
    for (final o in operations.take(50)) {
      final args = o.params.isEmpty
          ? '无参数'
          : o.params
              .map((p) => '${p.name}(${p.location}${p.required ? ',必填' : ''})')
              .join(', ');
      b.writeln(
          '- ${o.id} | ${o.method.toUpperCase()} ${o.path} | ${o.summary} | 参数: $args');
    }
    b.writeln('你会收到工具返回的结果，然后请用自然语言给出最终答案，不要再输出工具 JSON。');
    return b.toString();
  }

  /// 从模型输出中定位工具调用 JSON（支持 fenced block 与内联对象，括号平衡扫描）。
  static Map<String, dynamic>? parseToolCall(String text) {
    final fenced =
        RegExp(r'```(?:tool|json)?\s*([\s\S]*?)```', caseSensitive: false);
    for (final m in fenced.allMatches(text)) {
      final j = _try(text: m.group(1) ?? '');
      if (j != null) return j;
    }
    final whole = _try(text: text.trim());
    if (whole != null) return whole;

    for (var i = 0; i < text.length; i++) {
      if (text.codeUnitAt(i) != 0x7B) continue; // '{'
      var depth = 0;
      var inStr = false;
      var esc = false;
      for (var j = i; j < text.length; j++) {
        final c = text[j];
        if (inStr) {
          if (esc) {
            esc = false;
          } else if (c == r'\') {
            esc = true;
          } else if (c == '"') {
            inStr = false;
          }
          continue;
        }
        if (c == '"') {
          inStr = true;
        } else if (c == '{') {
          depth++;
        } else if (c == '}') {
          depth--;
          if (depth == 0) {
            final r = _try(text: text.substring(i, j + 1));
            if (r != null) return r;
            break;
          }
        }
      }
    }
    return null;
  }

  static Map<String, dynamic>? _try({required String text}) {
    final t = text.trim();
    if (!t.startsWith('{')) return null;
    try {
      final v = jsonDecode(t);
      if (v is Map && v['tool'] != null) {
        final args = v['arguments'] ?? v['args'] ?? v['parameters'];
        return {
          'tool': v['tool'].toString(),
          'arguments': args is Map
              ? Map<String, dynamic>.from(args)
              : <String, dynamic>{},
        };
      }
    } catch (_) {}
    return null;
  }

  ApiOperation? find(String id) {
    for (final o in operations) {
      if (o.id == id) return o;
    }
    return null;
  }

  Future<String> call(String opId, Map<String, dynamic> args,
      {String? apiKey}) async {
    final op = find(opId);
    if (op == null) throw StateError('未知工具：$opId');

    var path = op.path;
    final query = <String, dynamic>{};
    final headers = <String, String>{
      'Content-Type': 'application/json',
      'Accept': 'application/json, text/plain, */*',
      if (apiKey != null && apiKey.isNotEmpty)
        'Authorization': 'Bearer $apiKey',
    };
    final body = <String, dynamic>{};

    for (final e in args.entries) {
      if (path.contains('{${e.key}}')) {
        path = path.replaceAll(
            '{${e.key}}', Uri.encodeComponent(e.value.toString()));
        continue;
      }
      ApiParam? meta;
      for (final p in op.params) {
        if (p.name == e.key) {
          meta = p;
          break;
        }
      }
      final loc = meta?.location ?? (op.method == 'get' ? 'query' : 'body');
      switch (loc) {
        case 'path':
          break;
        case 'header':
          headers[e.key] = e.value.toString();
          break;
        case 'body':
          body[e.key] = e.value;
          break;
        default:
          query[e.key] = e.value;
      }
    }

    final uri = baseUrl + (path.startsWith('/') ? path : '/$path');
    final resp = await _dio.request<dynamic>(
      uri,
      queryParameters: query.isEmpty ? null : query,
      data: body.isEmpty ? null : jsonEncode(body),
      options: Options(
        method: op.method.toUpperCase(),
        headers: headers,
        responseType: ResponseType.plain,
        validateStatus: (_) => true,
      ),
    );
    var out = resp.data == null ? '' : resp.data.toString();
    if (out.length > 8000) out = '${out.substring(0, 8000)}\n…（结果已截断）';
    return 'HTTP ${resp.statusCode}\n$out';
  }
}

import 'dart:convert';

import 'package:dio/dio.dart';

/// 一个模型公开报价，单位统一为「美元 / 每百万 token」。
class ModelPrice {
  final String id;
  final double inputPerM;
  final double outputPerM;

  /// 命中服务端提示词缓存时的输入单价；没有单列报价时按输入价的一半估。
  final double cachedPerM;

  const ModelPrice({
    required this.id,
    required this.inputPerM,
    required this.outputPerM,
    this.cachedPerM = 0,
  });

  bool get valid => inputPerM > 0 || outputPerM > 0;

  double get effectiveCachedPerM =>
      cachedPerM > 0 ? cachedPerM : inputPerM * 0.5;

  Map<String, dynamic> toJson() => {
        'id': id,
        'in': inputPerM,
        'out': outputPerM,
        'cached': cachedPerM,
      };

  factory ModelPrice.fromJson(Map<dynamic, dynamic> j) => ModelPrice(
        id: (j['id'] ?? '').toString(),
        inputPerM: (j['in'] as num?)?.toDouble() ?? 0,
        outputPerM: (j['out'] as num?)?.toDouble() ?? 0,
        cachedPerM: (j['cached'] as num?)?.toDouble() ?? 0,
      );
}

class PriceFetchResult {
  final Map<String, ModelPrice> prices;
  final String source;
  final String error;

  const PriceFetchResult({
    required this.prices,
    required this.source,
    this.error = '',
  });

  bool get ok => prices.isNotEmpty;
  int get count => prices.length;
}

/// 实时价格表。
///
/// 说明：OpenAI / Anthropic 等官方接口并没有「按调用返回单价」的公开端点，
/// 账单查询需要单独的 Admin Key，客户端不该持有。这里改从两份**公开费率表**
/// 拉价（LiteLLM 维护的 model_prices 与 OpenRouter 的 /models），按当前模型名
/// 匹配单价，再乘以本地已经记下的真实 token 数得出估算费用。
/// 估算值只用于自查，正式账单以服务商后台为准。
class PriceCatalog {
  PriceCatalog({Dio? dio})
      : _dio = dio ??
            Dio(BaseOptions(
              connectTimeout: const Duration(seconds: 12),
              receiveTimeout: const Duration(seconds: 25),
              sendTimeout: const Duration(seconds: 12),
              validateStatus: (_) => true,
            ));

  final Dio _dio;

  static const String kLiteLlm =
      'https://raw.githubusercontent.com/BerriAI/litellm/main/model_prices_and_context_window.json';
  static const String kOpenRouter = 'https://openrouter.ai/api/v1/models';

  /// 主源失败自动回落备源，两个都失败返回带 error 的空结果，不抛异常。
  Future<PriceFetchResult> refresh() async {
    final errors = <String>[];
    final lite = await _get(kLiteLlm);
    if (lite != null) {
      final m = parseLiteLlm(lite);
      if (m.isNotEmpty) return PriceFetchResult(prices: m, source: 'LiteLLM');
    } else {
      errors.add('LiteLLM 价格表');
    }
    final or = await _get(kOpenRouter);
    if (or != null) {
      final m = parseOpenRouter(or);
      if (m.isNotEmpty) return PriceFetchResult(prices: m, source: 'OpenRouter');
    } else {
      errors.add('OpenRouter');
    }
    return PriceFetchResult(
      prices: const {},
      source: '',
      error: errors.isEmpty ? '价格表为空' : '${errors.join(' / ')} 均不可用',
    );
  }

  Future<dynamic> _get(String url) async {
    try {
      final r = await _dio.get<dynamic>(url);
      if ((r.statusCode ?? 0) < 200 || (r.statusCode ?? 0) >= 300) return null;
      final d = r.data;
      if (d is String) return jsonDecode(d);
      return d;
    } catch (_) {
      return null;
    }
  }

  /// LiteLLM：{"gpt-4o": {"input_cost_per_token": 2.5e-6, ...}}
  /// 单价是「美元 / token」，乘 1e6 换算成「美元 / 百万 token」。
  static Map<String, ModelPrice> parseLiteLlm(dynamic data) {
    if (data is! Map) return const {};
    final out = <String, ModelPrice>{};
    data.forEach((key, value) {
      if (key == 'sample_spec' || value is! Map) return;
      final id = key.toString().trim().toLowerCase();
      if (id.isEmpty) return;
      final i = _num(value['input_cost_per_token']) * 1000000;
      final o = _num(value['output_cost_per_token']) * 1000000;
      final c = _num(value['cache_read_input_token_cost']) * 1000000;
      if (i <= 0 && o <= 0) return;
      final p = ModelPrice(id: id, inputPerM: i, outputPerM: o, cachedPerM: c);
      _put(out, id, p);
    });
    return out;
  }

  /// OpenRouter：{"data":[{"id":"openai/gpt-4o","pricing":{"prompt":"0.0000025",...}}]}
  static Map<String, ModelPrice> parseOpenRouter(dynamic data) {
    final list = data is Map ? data['data'] : null;
    if (list is! List) return const {};
    final out = <String, ModelPrice>{};
    for (final e in list) {
      if (e is! Map) continue;
      final id = (e['id'] ?? '').toString().trim().toLowerCase();
      final pr = e['pricing'];
      if (id.isEmpty || pr is! Map) continue;
      final i = _num(pr['prompt']) * 1000000;
      final o = _num(pr['completion']) * 1000000;
      final c = _num(pr['input_cache_read']) * 1000000;
      if (i <= 0 && o <= 0) continue;
      _put(out, id,
          ModelPrice(id: id, inputPerM: i, outputPerM: o, cachedPerM: c));
    }
    return out;
  }

  /// 同一个模型同时以完整 id 和去掉供应商前缀的短名登记，
  /// 这样 `openai/gpt-4o` 和 `gpt-4o` 都能查到。
  static void _put(Map<String, ModelPrice> out, String id, ModelPrice p) {
    out[id] = p;
    if (id.contains('/')) {
      final short = id.split('/').last;
      if (short.isNotEmpty) out.putIfAbsent(short, () => p);
    }
  }

  static double _num(dynamic v) {
    if (v is num) return v.toDouble();
    if (v is String) return double.tryParse(v.trim()) ?? 0;
    return 0;
  }

  /// 按模型名找单价：精确 → 去供应商前缀 → 去日期 / 版本后缀 → 最长前缀。
  /// 网关常给 `gpt-4o-2024-08-06`、`claude-sonnet-4-5-20250929` 这类带版本
  /// 的名字，精确匹配会落空，所以必须做归一化。
  static ModelPrice? lookup(Map<String, ModelPrice> table, String model) {
    var m = model.trim().toLowerCase();
    if (m.isEmpty || table.isEmpty) return null;
    final direct = table[m];
    if (direct != null) return direct;
    if (m.contains('/')) m = m.split('/').last;
    final short = table[m];
    if (short != null) return short;

    final base = m
        // gpt-4o-2024-08-06 / claude-...-20250929 / qwen-20250101
        .replaceAll(RegExp(r'[-_]?20\d{2}-?\d{2}-?\d{2}$'), '')
        .replaceAll(RegExp(r'[-_:](latest|preview)$'), '')
        .replaceAll(RegExp(r'[-_]v\d+(\.\d+)?$'), '');
    if (base != m) {
      final hit = table[base];
      if (hit != null) return hit;
    }

    ModelPrice? best;
    var bestLen = 0;
    for (final e in table.entries) {
      final k = e.key.contains('/') ? e.key.split('/').last : e.key;
      if (k.length > bestLen && m.startsWith(k) && k.length >= 3) {
        best = e.value;
        bestLen = k.length;
      }
    }
    return best;
  }

  /// 美元 → 人民币。
  static double toCny(double usd, double rate) => usd * rate;

  /// 按单价算一次请求的钱（¥）。
  static double costOf({
    required int prompt,
    required int completion,
    required double inputPerM,
    required double outputPerM,
    double cachedTokens = 0,
    double cachedPerM = 0,
    double usdToCny = 1,
  }) {
    final p = (prompt - cachedTokens).toDouble();
    final cached = cachedTokens.clamp(0, prompt.toDouble()).toDouble();
    final usd = p / 1000000 * inputPerM +
        completion / 1000000 * outputPerM +
        cached / 1000000 * cachedPerM;
    return usd * usdToCny;
  }
}

import 'dart:convert';

import 'package:dio/dio.dart';

/// 一条 GitHub 仓库搜索结果。
class RepoResult {
  final String fullName;
  final String description;
  final String url;
  final String language;
  final int stars;
  final String pushedAt;
  final bool archived;

  const RepoResult({
    required this.fullName,
    required this.description,
    required this.url,
    this.language = '',
    this.stars = 0,
    this.pushedAt = '',
    this.archived = false,
  });

  /// 列表里用的一行元信息：star · 语言 · 最近更新。
  String get metaLine {
    final bits = <String>[];
    if (stars > 0) bits.add(_stars(stars));
    if (language.isNotEmpty) bits.add(language);
    if (pushedAt.length >= 10) bits.add(pushedAt.substring(0, 10));
    if (archived) bits.add('已归档');
    return bits.join(' · ');
  }

  static String _stars(int n) {
    if (n >= 1000) {
      final k = n / 1000;
      return '${k.toStringAsFixed(k >= 10 ? 0 : 1)}k stars';
    }
    return '$n stars';
  }
}

class ProjectSearchException implements Exception {
  final String message;
  const ProjectSearchException(this.message);
  @override
  String toString() => message;
}

/// 全网搜索开源项目。
///
/// 内置目录只能覆盖「我知道的」项目，用户要的是「全部」。这里直接查
/// GitHub 仓库搜索，按 star 排序，能翻到目录里没有的新实现。
/// 不登录也能用，代价是接口按 IP 限流（每分钟十次左右）。
class ProjectSearch {
  static final Dio _dio = Dio(BaseOptions(
    connectTimeout: const Duration(seconds: 8),
    receiveTimeout: const Duration(seconds: 15),
    responseType: ResponseType.plain,
    validateStatus: (_) => true,
    followRedirects: true,
    headers: const {'Accept': 'application/vnd.github+json'},
  ));

  /// 首页给的快捷词，覆盖三类需求：网页版反代、免密、公益站。
  static const List<String> quickQueries = [
    '2api',
    'free-api',
    'chatgpt 反代',
    '公益 API',
  ];

  static Future<List<RepoResult>> search(String query, {int limit = 15}) async {
    final q = query.trim();
    if (q.isEmpty) return const [];
    final uri = Uri.https('api.github.com', '/search/repositories', {
      'q': q,
      'sort': 'stars',
      'order': 'desc',
      'per_page': '$limit',
    });
    try {
      final resp = await _dio.get<String>(uri.toString());
      final code = resp.statusCode ?? 0;
      if (code == 403 || code == 429) {
        throw const ProjectSearchException('GitHub 限流了，等一分钟再搜，或先用内置目录');
      }
      if (code != 200) {
        throw ProjectSearchException('搜索失败（HTTP $code）');
      }
      return parse(resp.data);
    } on ProjectSearchException {
      rethrow;
    } on DioException {
      throw const ProjectSearchException('连不上 GitHub，检查网络后再试');
    }
  }

  /// 解析 GitHub 的返回体。[data] 允许是 JSON 字符串或已解码的对象。
  static List<RepoResult> parse(dynamic data) {
    dynamic v = data;
    if (v is String) {
      try {
        v = jsonDecode(v);
      } catch (_) {
        return const [];
      }
    }
    if (v is! Map) return const [];
    final items = v['items'];
    if (items is! List) return const [];
    final out = <RepoResult>[];
    for (final e in items) {
      if (e is! Map) continue;
      final name = (e['full_name'] ?? '').toString();
      if (name.isEmpty) continue;
      out.add(RepoResult(
        fullName: name,
        description: (e['description'] ?? '').toString(),
        url: (e['html_url'] ?? 'https://github.com/$name').toString(),
        language: (e['language'] ?? '').toString(),
        stars: (e['stargazers_count'] as num?)?.toInt() ?? 0,
        pushedAt: (e['pushed_at'] ?? '').toString(),
        archived: e['archived'] == true,
      ));
    }
    return out;
  }
}

