/// 把流式正文里的「思考段」拆出来。
///
/// 很多 OpenAI 兼容网关（DeepSeek-R1、QwQ、各类中转）并不返回
/// `reasoning_content` 字段，而是把思考直接写进 content：
///
/// ```
/// <thinking>用户问的是……先看前提……</thinking>
/// 结论是……
/// ```
///
/// 如果不拆，用户会看到一大段自我对话混在答案正文里；而如果整段丢掉，
/// 又会出现「深度思考看不到在思考什么」。这里做增量拆分：思考进思考区，
/// 正文只留答案。
///
/// 流式下标签会被切成两半（`<thi` + `nking>`），所以未闭合的尾巴要留下来
/// 等下一个 chunk，不能提前吐出去。
class ThinkSplitter {
  bool _inside = false;

  /// 可能是半个标签的尾巴，等下一块拼上再判断。
  String _tail = '';

  static const List<String> _openTags = [
    '<thinking>',
    '<think>',
    '<reasoning>',
    '<thought>',
    '<思考>',
  ];

  static const List<String> _closeTags = [
    '</thinking>',
    '</think>',
    '</reasoning>',
    '</thought>',
    '</思考>',
  ];

  bool get inside => _inside;

  /// 输入一块增量，返回拆分后的正文与思考。
  ThinkPiece add(String chunk) {
    if (chunk.isEmpty) return const ThinkPiece();
    final text = _tail + chunk;
    _tail = '';
    return _scan(text);
  }

  /// 流结束时调用，吐出残留的尾巴。
  ThinkPiece flush() {
    if (_tail.isEmpty) return const ThinkPiece();
    final rest = _tail;
    _tail = '';
    return _inside ? ThinkPiece(thinking: rest) : ThinkPiece(content: rest);
  }

  ThinkPiece _scan(String text) {
    final content = StringBuffer();
    final thinking = StringBuffer();
    var i = 0;
    while (i < text.length) {
      if (!_inside) {
        final hit = _next(text, i, _openTags);
        if (hit == null) {
          // 末尾可能是半个开标签，留到下一块。
          final keep = _partialTail(text, i, _openTags);
          content.write(text.substring(i, text.length - keep));
          if (keep > 0) _tail = text.substring(text.length - keep);
          break;
        }
        content.write(text.substring(i, hit.index));
        _inside = true;
        i = hit.index + hit.length;
      } else {
        final hit = _next(text, i, _closeTags);
        if (hit == null) {
          final keep = _partialTail(text, i, _closeTags);
          thinking.write(text.substring(i, text.length - keep));
          if (keep > 0) _tail = text.substring(text.length - keep);
          break;
        }
        thinking.write(text.substring(i, hit.index));
        _inside = false;
        i = hit.index + hit.length;
      }
    }
    return ThinkPiece(content: content.toString(), thinking: thinking.toString());
  }

  _Hit? _next(String s, int from, List<String> tags) {
    _Hit? best;
    for (final t in tags) {
      final idx = s.indexOf(t, from);
      if (idx < 0) continue;
      if (best == null || idx < best.index) best = _Hit(idx, t.length);
    }
    return best;
  }

  /// 末尾若正好是某个标签的前缀（如 `<thi`），返回需要保留的字符数。
  int _partialTail(String s, int from, List<String> tags) {
    final avail = s.length - from;
    final max = avail < 16 ? avail : 16;
    for (var len = max; len >= 1; len--) {
      final tail = s.substring(s.length - len);
      for (final t in tags) {
        if (t.length > len && t.startsWith(tail)) return len;
      }
    }
    return 0;
  }
}

class _Hit {
  final int index;
  final int length;
  const _Hit(this.index, this.length);
}

class ThinkPiece {
  final String content;
  final String thinking;
  const ThinkPiece({this.content = '', this.thinking = ''});
  bool get isEmpty => content.isEmpty && thinking.isEmpty;
}

/// 语音引擎目录（TTS 朗读 + STT 语音输入）。
///
/// 设计原则和「免密模型」一致：**只放确认可用的通道**，并明确标出
/// 是否需要密钥、是否离线。免费通道会随时失效，所以每一项都写清
/// 回落方案；系统语音永远是最后的兜底（不联网、不花钱、不失效）。
///
/// 所有云端引擎尽量收敛到 OpenAI 兼容协议（`/audio/speech`、
/// `/audio/transcriptions`），这样 OpenAI、Groq、硅基流动、DeepInfra、
/// One API、gpt4free、本地 whisper.cpp 全都用同一段代码。
library;

/// 传输协议族。
/// - [system]：系统内置（Android TTS / SpeechRecognizer），离线可用；
/// - [openai]：OpenAI 兼容，POST 音频二进制或 multipart 上传；
/// - [urlQuery]：GET 拼 URL 直出 mp3，无需密钥（有道 / 百度 / SE）；
/// - [elevenLabs]：ElevenLabs 私有协议，音质最好但按字符计费。
enum VoiceProto {
  system,
  openAI,
  urlQuery,
  elevenLabs,

  /// 微软 Edge「大声朗读」：WebSocket + 私有签名，免密钥。
  edge,

  /// Fish Audio：自有协议，音色用 reference_id。
  fish,

  /// Azure 语音服务：SSML + 订阅密钥 + 区域。
  azure,
}

/// 一个 TTS 引擎。
class TtsEngine {
  final String id;
  final String name;
  final String summary;

  /// 标签：免费 / 离线 / 需 Key / 高音质。用于列表右侧的短标记。
  final String badge;
  final VoiceProto proto;

  /// 固定根地址；空字符串表示「跟随当前连接」。
  final String baseUrl;
  final bool needsKey;
  final List<String> voices;

  /// 与 [voices] 一一对应的实际取值。为空时直接用 [voices]。
  /// 界面上显示「晓晓」，请求里必须是 `zh-CN-XiaoxiaoNeural`。
  final List<String> voiceIds;
  final String note;

  const TtsEngine({
    required this.id,
    required this.name,
    required this.summary,
    required this.badge,
    required this.proto,
    this.baseUrl = '',
    this.needsKey = false,
    this.voices = const [],
    this.voiceIds = const [],
    this.note = '',
  });

  /// 把界面上的音色名换成接口要的值。
  String voiceId(String label) {
    if (label.isEmpty) return voices.isEmpty ? '' : _idAt(0);
    final i = voices.indexOf(label);
    return i >= 0 ? _idAt(i) : label;
  }

  String _idAt(int i) =>
      i < voiceIds.length ? voiceIds[i] : (i < voices.length ? voices[i] : '');

  bool get followsConnection => baseUrl.isEmpty;
  bool get isFree => badge == '免费' || badge == '离线';
}

/// 一个 STT 引擎。
///
/// v4.4 起额外记录「是否本地 / 速度 / 准确度 / 中文优化」，这四个维度
/// 直接决定设置页的标签和默认排序——用户要的是「快、本地、准、多选」，
/// 只给一串名字没法判断该选哪个。
class SttEngine {
  final String id;
  final String name;
  final String summary;
  final String badge;
  final VoiceProto proto;
  final String baseUrl;
  final bool needsKey;

  /// 默认模型名，空表示用服务端默认。
  final String model;
  final String note;

  /// 数据不出手机（系统离线识别 / 本机服务）。
  final bool offline;

  /// 1~3：1 偏慢、3 极快（含网络往返与首字延迟的综合估计）。
  final int speed;

  /// 1~3：1 够用、3 中文标点与专有名词表现最好。
  final int accuracy;

  /// 对中文口语做过专门优化。
  final bool zhOptimized;

  /// 地址完全由用户填写（[baseUrl] 为空时不视为「跟随当前连接」）。
  final bool custom;

  /// 需自行在电脑 / 局域网部署服务，手机本身没有。
  final bool experimental;

  const SttEngine({
    required this.id,
    required this.name,
    required this.summary,
    required this.badge,
    required this.proto,
    this.baseUrl = '',
    this.needsKey = false,
    this.model = '',
    this.note = '',
    this.offline = false,
    this.speed = 2,
    this.accuracy = 2,
    this.zhOptimized = false,
    this.custom = false,
    this.experimental = false,
  });

  bool get followsConnection => baseUrl.isEmpty && !custom;
  bool get isLocal => offline;
  String get speedLabel => switch (speed) {
        3 => '极快',
        2 => '较快',
        _ => '较慢',
      };
  String get accuracyLabel => switch (accuracy) {
        3 => '很准',
        2 => '准确',
        _ => '一般',
      };

  /// 设置页每行右侧的短标签：本地优先，其次速度 / 准确度 / 中文。
  List<String> get tags => [
        if (experimental) '需部署',
        if (custom) '自定义',
        if (offline && !experimental) '本地',
        speedLabel,
        accuracyLabel,
        if (zhOptimized) '中文佳',
        if (needsKey) '需 Key',
      ];
}

