  Future<String?> _writeTemp(List<int> bytes, String ext) async {
    try {
      final dir = await getTemporaryDirectory();
      final f = File(
          '${dir.path}/aigent_tts_${DateTime.now().millisecondsSinceEpoch}.$ext');
      await f.writeAsBytes(bytes, flush: true);
      return f.path;
    } catch (_) {
      return null;
    }
  }

  void _deleteQuietly(String path) {
    try {
      final f = File(path);
      if (f.existsSync()) f.deleteSync();
    } catch (_) {}
  }

  /// 去掉 Markdown 标记：朗读时不该把 `**`、链接地址、代码块都念出来。
  static String stripMarkdown(String src) {
    var s = src;
    s = s.replaceAll(RegExp(r'```[\s\S]*?```'), '。代码块已跳过。');
    s = s.replaceAll(RegExp(r'!\[[^\]]*\]\([^)]*\)'), '');
    // 链接只保留文字：Dart 的 replaceAll 不解析 $1，必须用 replaceAllMapped，
    // 否则会把「文档」念成「美元一」。
    s = s.replaceAllMapped(
        RegExp(r'\[([^\]]*)\]\([^)]*\)'), (m) => m.group(1) ?? '');
    s = s.replaceAll(RegExp(r'<[^>]+>'), '');
    s = s.replaceAll(RegExp(r'^#{1,6}\s*', multiLine: true), '');
    s = s.replaceAll(RegExp(r'^\s*[-*+]\s+', multiLine: true), '');
    s = s.replaceAll(RegExp(r'[*_`>|]'), '');
    s = s.replaceAll(RegExp(r'\n{2,}'), '\n');
    return s.trim();
  }

  /// 按句子边界切段。免费通道对长度敏感，硬切会把词切坏。
  static List<String> chunk(String src, int max) {
    final out = <String>[];
    var rest = src.trim();
    while (rest.length > max) {
      var cut = -1;
      for (var i = max; i > max ~/ 3; i--) {
        final c = rest[i - 1];
        if (c == '。' ||
            c == '！' ||
            c == '？' ||
            c == '.' ||
            c == '!' ||
            c == '?' ||
            c == '\n' ||
            c == '；' ||
            c == ';') {
          cut = i;
          break;
        }
      }
      if (cut <= 0) cut = max;
      out.add(rest.substring(0, cut).trim());
      rest = rest.substring(cut).trim();
    }
    if (rest.isNotEmpty) out.add(rest);
    return out;
  }

  static String _trimSlash(String s) {
    var v = s.trim();
    while (v.endsWith('/')) {
      v = v.substring(0, v.length - 1);
    }
    return v;
  }

  /// 原生层的英文异常直接甩给用户，只会让人以为是手机坏了。
  /// 这里只翻译「有明确下一步」的几类，其余原样保留方便排查。
  static String friendlySttError(String raw) {
    final s = raw.toLowerCase();
    if (s.contains('peer field id') || s.contains('com.sun.jna')) {
      return '离线识别引擎没加载起来（安装包的压缩步骤裁掉了原生库的必要字段）。'
          '在 设置 → 语音 里先把引擎切成「系统语音」就能用；'
          '装 4.9.3 及之后的版本会彻底修复。';
    }
    if (s.contains('model') &&
        (s.contains('not found') || s.contains('no such file'))) {
      return '离线语音包不完整，去 设置 → 语音 重新解压一次。';
    }
    if (s.contains('out of memory') || s.contains('oom')) {
      return '内存不足，离线模型加载失败。关掉一些后台应用再试。';
    }
    return raw;
  }

  static String _short(Object e) {
    final s = e.toString();
    return s.length > 90 ? '${s.substring(0, 90)}…' : s;
  }

  /// 把 HTTP 错误翻译成「下一步该做什么」，而不是甩一个状态码。
  static String explainTtsError(DioException e) {
    final code = e.response?.statusCode ?? 0;
    final base = _trimSlash(e.requestOptions.baseUrl);
    switch (code) {
      case 401:
        return '密钥无效或未填（401）。检查这条连接 / 语音引擎的 Key。';
      case 402:
        return '额度不足（402）。这条通道要付费或免费额度已用完。';
      case 403:
        return '被拒绝（403）。可能是该模型未对当前账号开放。';
      case 404:
        return '这个地址没有 /audio/speech（404）。该服务商可能只做对话，'
            '换「系统语音」或有道 / 百度。';
      case 429:
        return '请求太频繁（429）。等一会儿再试，或换成系统语音。';
      default:
        if (e.type == DioExceptionType.connectionTimeout ||
            e.type == DioExceptionType.receiveTimeout) {
          return '超时。检查网络，或换系统语音。';
        }
        if (e.type == DioExceptionType.connectionError) {
          return '连不上 $base。检查地址与网络。';
        }
        return '请求失败${code == 0 ? '' : '（$code）'}：${e.message ?? ''}';
    }
  }

  static String explainSttError(DioException e) {
    final code = e.response?.statusCode ?? 0;
    switch (code) {
      case 401:
        return '密钥无效（401）。转写接口需要 Key。';
      case 404:
        return '这个地址没有 /audio/transcriptions（404）。'
            '换成「系统识别」，或填支持 Whisper 的接口。';
      case 413:
        return '录音太大（413）。说短一点再试。';
      case 429:
        return '请求太频繁（429）。稍后再试。';
      default:
        if (e.type == DioExceptionType.connectionError) {
          return '连不上转写服务。';
        }
        return '转写失败${code == 0 ? '' : '（$code）'}';
    }
  }
}

import 'package:flutter/material.dart';

/// v4.15 皮肤系统：整套语义色由一份「预设 + 自定义」配置生成。
///
/// 设计原则和 v4 最初的 Quiet Depth 一致——只有画布、纸面、墨色三层，
/// 强调色只用于可点的地方。主题不是换一堆花哨颜色，而是换这三层的
/// 冷暖与明度关系：GitHub 的纸白、Nord 的冷灰、Gruvbox 的暖褐，
/// 各自成立但都不抢内容。
///
/// 所有界面代码仍在用 `C.ink` / `MuseC.bubble(dark)` 这类固定名字，
/// 这里把名字映射到当前皮肤，换肤时不用改任何调用点。
class Palette {
  final Color bg;
  final Color surface;
  final Color chip;
  final Color sink;
  final Color line;
  final Color hair;
  final Color border;
  final Color borderStrong;
  final Color ink;
  final Color ink2;
  final Color ink3;
  final Color accent;
  final Color bubble;
  final Color ok;
  final Color warn;
  final Color danger;

  const Palette({
    required this.bg,
    required this.surface,
    required this.chip,
    required this.sink,
    required this.line,
    required this.hair,
    required this.border,
    required this.borderStrong,
    required this.ink,
    required this.ink2,
    required this.ink3,
    required this.accent,
    required this.bubble,
    required this.ok,
    required this.warn,
    required this.danger,
  });

  /// 从「画布 / 纸面 / 强调色」三颗种子派生整张色板。
  /// 只让用户挑这三样，其余明度关系由代码保证，避免自定义出一套读不清的字。
  factory Palette.seed({
    required Color bg,
    required Color surface,
    required Color accent,
    required bool dark,
  }) {
    Color mix(Color a, Color b, double t) =>
        Color.lerp(a, b, t.clamp(0.0, 1.0))!;
    final ink = dark ? const Color(0xFFF2F2F5) : const Color(0xFF15171B);
    return Palette(
      bg: bg,
      surface: surface,
      chip: mix(surface, ink, dark ? 0.075 : 0.055),
      sink: mix(surface, ink, dark ? 0.05 : 0.035),
      line: mix(surface, ink, dark ? 0.15 : 0.10),
      hair: mix(surface, ink, dark ? 0.10 : 0.065),
      border: mix(surface, ink, dark ? 0.17 : 0.12),
      borderStrong: mix(surface, ink, dark ? 0.36 : 0.28),
      ink: ink,
      ink2: mix(ink, bg, dark ? 0.40 : 0.42),
      ink3: mix(ink, bg, dark ? 0.58 : 0.60),
      accent: accent,
      bubble: accent,
      ok: dark ? const Color(0xFF7EC699) : const Color(0xFF2F6B4F),
      warn: dark ? const Color(0xFFE0B060) : const Color(0xFF8A6A33),
      danger: dark ? const Color(0xFFF08A8A) : const Color(0xFFB04444),
    );
  }
}

/// 一套主题预设。亮暗各一张色板，随系统 / 设置切换。
class SkinPreset {
  final String id;
  final String name;
  final String note;
  final Palette light;
  final Palette dark;
  final Color swatch; // 设置页色卡用

  const SkinPreset({
    required this.id,
    required this.name,
    required this.note,
    required this.light,
    required this.dark,
    required this.swatch,
  });
}

/// 全局皮肤。由 `main.dart` 在构建 MaterialApp 前写入；
/// 设置页改动后整页重建，立即生效。
class Skin {
  static Palette light = kSkinPresets.first.light;
  static Palette dark = kSkinPresets.first.dark;

  /// 圆角强度：0.6（硬朗）~ 1.4（圆润）。只影响带圆角的容器。
  static double radius = 1.0;

  static SkinPreset get preset => _active;
  static SkinPreset _active = kSkinPresets.first;

  static void applyPreset(SkinPreset p, {double radiusScale = 1.0}) {
    _active = p;
    light = p.light;
    dark = p.dark;
    radius = radiusScale;
  }

  /// 自定义：三颗种子 + 圆角，亮暗共用同一支强调色。
  static void applyCustom({
    required Color accent,
    Color? canvasLight,
    Color? canvasDark,
    double radiusScale = 1.0,
  }) {
    final l = canvasLight ?? const Color(0xFFF6F7F9);
    final d = canvasDark ?? const Color(0xFF0B0B0D);
    final p = SkinPreset(
      id: 'custom',
      name: '自定义',
      note: '你的配方',
      light: Palette.seed(
        bg: l,
        surface: _paperOver(l),
        accent: accent,
        dark: false,
      ),
      dark: Palette.seed(
        bg: d,
        surface: _paperOver(d),
        accent: accent,
        dark: true,
      ),
      swatch: accent,
    );
    applyPreset(p, radiusScale: radiusScale);
  }

  /// 纸面比画布亮一档（浅色）或亮两档（深色），保证卡片浮得起来。
  static Color _paperOver(Color bg) {
    final isDark = bg.computeLuminance() < 0.4;
    return Color.lerp(bg, Colors.white, isDark ? 0.075 : 0.62)!;
  }

  static SkinPreset? byId(String id) {
    for (final p in kSkinPresets) {
      if (p.id == id) return p;
    }
    return null;
  }
}

