  // ---- v4.25 命中缓存 ----
  /// 命中台账（累计数字 + 最近记录）与本地响应缓存，独立于会话历史落盘。
  final CacheLedger cacheLedger = CacheLedger();
  final ResponseCache responseCache = ResponseCache();
  CacheStore cacheStore = CacheStore();

  // ---- v4.25 实时价格 ----
  final PriceCatalog priceCatalog = PriceCatalog();

