  // ------------------------------------------------------------ 设备智能体

  /// 首帧之后静默加载：设备信息 + 隔离工作区 + 审计日志。
  /// 全是本地 IO，不发起网络请求，不拖慢冷启动。
  Future<void> _initAgent() => refreshAgentData();

  /// 重新读取设备信息、确保工作区就绪并刷新审计日志。设置页可手动触发。
  Future<void> refreshAgentData() async {
    try {
      deviceInfo = await DeviceBridge().info();
      agentWorkspace ??= await AgentWorkspace.open();
      await refreshAgentLog(notify: false);
    } catch (_) {
      // 没有原生通道（单测 / 桌面）时保留 fallback 信息，界面照常可用。
    }
    notifyListeners();
  }

  Future<void> refreshAgentLog({bool notify = true}) async {
    final ws = agentWorkspace;
    agentLog = ws == null ? <AgentLogEntry>[] : await ws.readLog();
    if (notify) notifyListeners();
  }

  /// 每次工具调用都按当前设置重建：授权开关一改，下一轮立即生效。
  AgentRuntime buildAgentRuntime() => AgentRuntime(
        workspace: agentWorkspace!,
        grant: agentGrant,
        deviceInfo: deviceInfo,
        confirm: _confirmAgentAction,
        confirmEach: settings.agentConfirmEach,
      );

  /// 非模态确认：把动作挂到界面上等用户点「允许 / 跳过」，不弹阻塞对话框。
  /// 90 秒无操作自动按「跳过」处理，生成流程不会永久卡住。
  Future<bool> _confirmAgentAction(AgentAction action) async {
    resolveAgentAction(false);
    final c = Completer<bool>();
    _agentApproval = c;
    pendingAgentAction = action;
    notifyListeners();
    try {
      return await c.future.timeout(
        const Duration(seconds: 90),
        onTimeout: () => false,
      );
    } finally {
      pendingAgentAction = null;
      if (identical(_agentApproval, c)) _agentApproval = null;
      notifyListeners();
    }
  }

  void resolveAgentAction(bool allow) {
    final c = _agentApproval;
    if (c != null && !c.isCompleted) c.complete(allow);
  }

  Future<String> clearAgentTrash() async {
    final ws = agentWorkspace;
    if (ws == null) return '工作区尚未就绪';
    final msg = await ws.clearTrash();
    await refreshAgentLog(notify: false);
    notifyListeners();
    return msg;
  }

  // -------------------------------------------------------------- Prompt 组装

  /// 组装最终 System Prompt。设置页的「预览请求体」直接调用它，
  /// 看到的就是真实生效内容：当前预设 + {{变量}} 插值 + 检索/文件/工具上下文。
  /// 客户端不追加任何审查或反审查指令 —— 模型行为由模型与用户自己的预设决定。
  String buildSystemPrompt({
    String query = '',
    String searchContext = '',
    String fileContext = '',
    String sources = '',
    bool withTools = true,
    Persona? persona,
  }) {
    final sys = StringBuffer();
    final langName = replyLangPrompt(settings.replyLang);
    final base = settings.activePreset
        .render(
          query: query,
          model: settings.model,
          language: langName.isEmpty ? '简体中文' : langName,
          sources: sources,
          tier: settings.tier.label,
        )
        .trim();
    sys.writeln(base.isEmpty ? kDefaultSystemPrompt : base);
    // 明确指定对话语言时，用一行短指令兜住模型的自选行为；
    // auto 时完全不追加，避免改变默认表现。
    if (langName.isNotEmpty) {
      sys.writeln('[语言] 用$langName回答（代码、命令、专有名词保持原样）。');
    }
    // 人物形象：名字 + 角色设定作为一段身份说明注入，让形象不只是贴图。
    // 这是普通的角色 / 语气设定，不含任何审查规避意图。
    final p = persona ?? activePersona;
    // 没有形象（名字为空）就完全不注入身份段，别让模型自称「」。
    if (settings.personaEnabled && p.name.trim().isNotEmpty) {
      sys.writeln('[身份] 你的名字是「${p.name}」。'
          '${p.tagline.trim().isEmpty ? '' : '一句话定位：${p.tagline.trim()}。'}'
          '${p.roleHint.trim().isEmpty ? '保持克制、精确、诚实的表达。' : p.roleHint.trim()}');
    }
    if (settings.deepThinking) {
      sys.writeln('[推理指令] 先在内部完成逐步推理与自我校验，再输出精炼结论；不要输出原始思维链。');
    }
    if (searchContext.isNotEmpty) sys.writeln(searchContext);
    if (fileContext.isNotEmpty) sys.writeln(fileContext);
    if (withTools && settings.pluginEnabled && plugin != null) {
      sys.writeln(plugin!.toolPrompt);
    }
    // 本机能力：只有用户显式打开「设备智能体」才注入工具清单与设备信息。
    // 关闭时 System Prompt 与旧版完全一致，不产生任何额外 token 或行为变化。
    if (withTools && settings.agentEnabled) {
      sys.writeln(buildAgentPrompt(
        info: deviceInfo,
        grant: agentGrant,
        workspaceRoot: agentWorkspace?.root ?? '应用专属目录 /aigent_workspace',
        confirmEach: settings.agentConfirmEach,
      ));
    }
    return sys.toString();
  }

  Map<String, dynamic> previewBody(String userText) {
    final t = settings.tier;
    final req = LlmRequest(
      baseUrl: settings.baseUrl,
      apiKey: settings.apiKey,
      model: settings.model,
      messages: [
        {'role': 'system', 'content': buildSystemPrompt(query: userText)},
        {'role': 'user', 'content': userText.isEmpty ? '（示例提问）' : userText},
      ],
      maxTokens: t.maxTokens,
      temperature: t.temperature,
      topP: t.topP,
      thinkingBudget: t.thinkingBudget,
      reasoningEffort: t.reasoningEffort,
      deepThinking: settings.deepThinking,
    );
    final body = req.toBody();
    body.remove('stream');
    (body['messages'] as List).last = {
      'role': 'user',
      'content': userText.isEmpty ? '（示例提问）' : userText,
    };
    body['api_key'] = settings.apiKey.isEmpty ? '<未设置>' : '<已加密隐藏>';
    return body;
  }

  static final RegExp _hazard = RegExp(
    r'(rm\s+-rf\s+/system|dd\s+if=\S+\s+of=/dev/block|format\s+/system|wipe\s+data|flash_image\s+/system)',
    caseSensitive: false,
  );

  /// 危险命令示例的展示提示。客户端不做内容拦截，但把执行边界说清楚：
  /// 系统命令从不执行，智能体只跑隔离工作区里经授权的受限任务脚本。
  String? guardNotice(String text) {
    if (_hazard.hasMatch(text)) {
      return '文本中包含涉及系统分区写入的命令示例。本应用不会执行系统命令；'
          '智能体只能在隔离工作区内运行受限任务脚本，且需你逐次授权。';
    }
    return null;
  }

  // ------------------------------------------------------------------ 生成

  Map<String, dynamic> _toApiMessage(ChatMessage m) {
    final img = FileExtractService.imageMessage(
        m.content, m.attachments, settings.visionFormat);
    if (img != null) return img;
    return {
      'role': m.role == Role.user ? 'user' : 'assistant',
      'content': m.content,
    };
  }

  /// 当前模型 ID 看起来是否支持视觉（仅提示，不阻断发送）。
  bool get currentModelLikelyVision => looksLikeVisionModel(settings.model);

  bool get hasPendingImages => pending.any((a) => a.isImage);

  /// 选了图片但模型看起来不支持视觉时，输入台给出的明确提示。
  /// 这是「图片识别不了」最常见的原因，必须在发送前让用户看见。
  String? get visionHint {
    if (!hasPendingImages || currentModelLikelyVision) return null;
    if (settings.visionHintDismissed) return null;
    if (settings.visionFormat == VisionFormat.textOnly) return null;
    return '「${settings.model}」看起来不是视觉模型，可能无法识别图片。'
        '请换用带视觉能力的模型，或到 设置 → 多模态 切换发送格式。';
  }

  List<ImageDiag> get imageDiagnostics => FileExtractService.diagnose(pending);

  /// 待发图片编码进 JSON 后的大致字节数（base64 膨胀 ≈ 4/3）。
  int get imagePayloadBytes => pending
      .where((a) => a.isImage)
      .fold<int>(0, (n, a) => n + ((a.imageBytes!.length + 2) ~/ 3) * 4);

  /// 请求体偏大时给出预警：中转网关常见 413 / 提前断开连接。
  String? get imageSizeHint {
    final b = imagePayloadBytes;
    if (b <= 3 * 1024 * 1024) return null;
    final mb = (b / 1048576).toStringAsFixed(1);
    return '待发图片编码后约 $mb MB，部分中转网关会因此拒绝请求'
        '（HTTP 413 或 Connection closed）。建议减少图片数量或压缩后重试。';
  }

  /// 批量语义刷新：文字成小段出现，消除「一个字一个字蹦」的割裂感。
  /// 判定见 [shouldFlushStream]；force 用于停止 / 一轮结束时一次清空。
  /// 流上下文按会话传入，后台会话生成时不会写到当前活动会话。
  void _flush(_StreamCtx ctx, {bool force = false}) {
    final t = ctx.target;
    if (t == null || ctx.buf.isEmpty) return;
    final pending = ctx.buf.toString();
    final now = DateTime.now().millisecondsSinceEpoch;
    if (!force) {
      final age = ctx.lastFlush == 0 ? 0 : now - ctx.lastFlush;
      if (!shouldFlushStream(pending, age, ctx.firstFlush)) return;
    }
    t.append(pending);
    ctx.buf.clear();
    ctx.lastFlush = now;
    ctx.firstFlush = false;
  }

  static LlmRequest _withMessages(LlmRequest r, List<Map<String, dynamic>> m) =>
      LlmRequest(
        baseUrl: r.baseUrl,
        apiKey: r.apiKey,
        model: r.model,
        messages: m,
        maxTokens: r.maxTokens,
        temperature: r.temperature,
        topP: r.topP,
        thinkingBudget: r.thinkingBudget,
        reasoningEffort: r.reasoningEffort,
        deepThinking: r.deepThinking,
        extraBody: r.extraBody,
      );

  Future<void> send(String raw) async {
    final conv = active;
    // 只拦「本会话」重复生成：别的会话在生成不会影响这里，支持并行。
    if (conv.generating) return;
    final text = raw.trim();
    if (text.isEmpty && conv.draftAttachments.isEmpty) return;

    // 全新安装不再预设模型名。没有模型就不发请求，否则会带着空的
    // `model` 打到接口上，用户只会看到一句莫名其妙的 401 / 400。
    if (settings.model.trim().isEmpty) {
      globalError = '尚未选择模型。请先到「设置 → 连接与模型」添加连接并选定一个模型。';
      conv.status = '尚未选择模型';
      notifyListeners();
      return;
    }

    // 新消息一发出就停掉上一段朗读：否则回答边生成边被旧声音盖住，
    // 也会把刚合成的音频白白播完。
    unawaited(VoiceService.instance.stop());

    // 捕获本次生成所属的会话与流上下文：此后即使用户切到别的会话，
    // 状态文案与流式文本也只落回原会话，绝不串台。
    final ctx = _stream(conv.id);
    if (conv.messages.isEmpty) {
      conv.title = text.isEmpty
          ? '多模态任务'
          : (text.length > 18 ? '${text.substring(0, 18)}…' : text);
    }

    final attachments = List<Attachment>.of(conv.draftAttachments);
    final userMsg = ChatMessage(
      id: _id(),
      role: Role.user,
      content: text,
      attachments: attachments,
    );
    final answer = ChatMessage(
      id: _id(),
      role: Role.assistant,
      content: '',
      thinking: settings.deepThinking ? ThinkingTrace() : null,
      streaming: true,
      model: settings.model,
      tierLabel: settings.tier.label,
    );
    conv.messages.add(userMsg);
    conv.messages.add(answer);
    conv.draftAttachments = [];
    conv.generating = true;
    globalError = null;
    conv.status = '准备中';
    // 取消令牌提前创建：停止按钮在「检索阶段」也能立即生效，不再出现卡死。
    ctx.cancel = CancelToken();
    ctx.sw
      ..reset()
      ..start();
    notifyListeners();
    // 用户消息与占位回答先落一次盘：即便生成中途被杀进程，
    // 重开也能看到自己问过什么、答案停在哪。
    scheduleHistorySave();

    // ---------- 联网检索 ----------
    // 只有 searchActive（总开关 + 至少一个已启用源）为真时才会进入这里，
    // 且界面状态文案与真实行为共用同一个判定，杜绝「关了还显示联网」。
    var searchContext = '';
    if (settings.searchActive && text.isNotEmpty) {
      conv.status = '联网检索中…';
      notifyListeners();
      try {
        final hits = await searchSvc.search(text, settings, cancel: ctx.cancel);
        // 检索期间被停止 / 期间关闭了联网：不再写入任何检索相关状态。
        if (!(ctx.cancel?.isCancelled ?? false) && settings.searchActive) {
          final cites = SearchService.toCitations(hits);
          searchContext = SearchService.buildContext(hits);
          answer.setCitations(cites);
          answer.searchQuery = text;
          conv.status = cites.isEmpty
              ? '未检索到结果，继续作答'
              : '已合并 ${settings.activeSources.length} 个源 · ${cites.length} 条资料';
        }
      } catch (e) {
        if (!(ctx.cancel?.isCancelled ?? false) && settings.searchActive) {
          conv.status = '检索失败，继续作答：$e';
        }
      }
      notifyListeners();
    }

    // 检索过程中用户点了停止：移除空占位回答，干净收尾，不再请求模型。
    if (ctx.cancel?.isCancelled ?? false) {
      conv.messages.remove(answer);
      conv.generating = false;
      conv.status = '';
      ctx.cancel = null;
      ctx.target = null;
      notifyListeners();
      return;
    }

    // ---------- 组装上下文 ----------
    final sys = buildSystemPrompt(
      query: text,
      searchContext: searchContext,
      fileContext: FileExtractService.textContext(attachments),
      sources: answer.citations.isEmpty
          ? ''
          : answer.citations.map((c) => c.title).join('、'),
      persona: settings.personaFor(conv.personaId),
    );
    final messages = <Map<String, dynamic>>[
      {'role': 'system', 'content': sys},
    ];
    final keep = settings.tier.historyLimit * 2;
    final from = conv.messages.length - 1 - keep < 0
        ? 0
        : conv.messages.length - 1 - keep;
    for (var i = from; i < conv.messages.length - 1; i++) {
      final m = conv.messages[i];
      if (m.role == Role.assistant && m.content.trim().isEmpty) continue;
      if (m.role == Role.tool) continue;
      messages.add(_toApiMessage(m));
    }

    final t = settings.tier;
    var req = LlmRequest(
      baseUrl: settings.baseUrl,
      apiKey: settings.apiKey,
      model: settings.model,
      messages: messages,
      maxTokens: t.maxTokens,
      temperature: t.temperature,
      topP: t.topP,
      thinkingBudget: t.thinkingBudget,
      reasoningEffort: t.reasoningEffort,
      deepThinking: settings.deepThinking,
      includeUsage: settings.usageTracking,
    );
    // 网关未返回 usage 时，用这份输入文本做本地估算。
    final promptSnapshot = messages
        .map((m) => m['content'] is String ? m['content'] as String : '')
        .join('\n');

    TokenUsage? apiUsage;
    String? finalError;
    // 智能体每一轮最多跑 agentMaxSteps 步；插件仍保留原来的 5 轮预算。
    final maxRounds = 5 + (settings.agentEnabled ? settings.agentMaxSteps : 0);
    var agentSteps = 0;
    ctx.target = answer;
    ctx.buf.clear();
    ctx.lastFlush = 0;
    ctx.firstFlush = true;
    ctx.flushTimer?.cancel();
    ctx.flushTimer =
        Timer.periodic(const Duration(milliseconds: 140), (_) => _flush(ctx));

    try {
      for (var round = 0; round < maxRounds; round++) {
        ctx.buf.clear();
        ctx.lastFlush = 0;
        ctx.firstFlush = true;
        answer.setStreaming(true);
        answer.thinking?.markRunning();
        conv.status = settings.deepThinking ? '深度思考中…' : '生成中…';
        notifyListeners();

        var cancelled = false;
        // 有的网关把思考写进正文的 <thinking> 标签里：边收边拆，
        // 思考进思考区，正文只留答案，标签本身不落到用户眼前。
        final splitter = ThinkSplitter();
        await for (final c in llm.chat(req, cancel: ctx.cancel)) {
          if (c.error != null) {
            finalError = c.error;
            break;
          }
          if (c.cancelled) {
            cancelled = true;
            break;
          }
          if (c.reasoning.isNotEmpty) answer.thinking?.append(c.reasoning);
          final piece = splitter.add(c.content);
          if (piece.thinking.isNotEmpty) {
            answer.thinking?.append(piece.thinking);
          }
          if (piece.content.isNotEmpty) ctx.buf.write(piece.content);
          if (c.usage != null) apiUsage = c.usage;
          _flush(ctx);
        }
        final tail = splitter.flush();
        if (tail.thinking.isNotEmpty) answer.thinking?.append(tail.thinking);
        if (tail.content.isNotEmpty) ctx.buf.write(tail.content);
        _flush(ctx, force: true);
        answer.thinking?.markDone();
        if (finalError != null || cancelled) break;

        final full = answer.content;

        // ---------- 本机工具调用循环 ----------
        // 和插件共用「模型输出 → 解析 → 执行 → 结果回灌」这一轮机制，
        // 但只认 agent.* 前缀，每一步都过授权 + 用户确认 + 审计日志。
        if (settings.agentEnabled &&
            agentWorkspace != null &&
            agentSteps < settings.agentMaxSteps) {
          final call = parseAgentToolCall(full);
          if (call != null) {
            agentSteps++;
            final toolId = call['tool'] as String;
            final toolName = call['name'] as String;
            final args = call['arguments'] as Map<String, dynamic>;
            conv.status = '请求执行：$toolName';
            notifyListeners();

            final sw = Stopwatch()..start();
            final exec = await buildAgentRuntime().execute(toolId, args);
            sw.stop();

            // 操作卡片插在最终回答之前；Role.tool 不会进入发给模型的历史，
            // 也不会被当成一条普通回答朗读 / 导出。
            final toolMsg = ChatMessage(
              id: _id(),
              role: Role.tool,
              content: exec.message,
              toolName: toolName,
              toolOk: exec.ok,
              toolStep: agentSteps,
              toolMs: sw.elapsedMilliseconds,
            );
            final at = conv.messages.length - 1;
            conv.messages.insert(at < 0 ? 0 : at, toolMsg);

            answer.content = '';
            answer.setStreaming(true);
            messages.add({'role': 'assistant', 'content': full});
            messages.add({
              'role': 'user',
              'content':
                  '${exec.asToolResult}\n请据此用自然语言给出最终答案，不要再输出工具 JSON。',
            });
            req = _withMessages(req, messages);
            conv.status = exec.ok
                ? '已执行 $toolName · 整理结果中…'
                : '$toolName 未执行 · 继续作答';
            unawaited(refreshAgentLog());
            notifyListeners();
            continue;
          }
        }

        // 步数用尽后模型仍在输出工具 JSON：给一句明确说明，别把生硬的
        // JSON 当作最终答案展示出来。
        if (settings.agentEnabled &&
            agentSteps >= settings.agentMaxSteps &&
            parseAgentToolCall(full) != null) {
          answer.content = '已达到单次任务的操作步数上限'
              '（${settings.agentMaxSteps} 步）。已完成的操作见上方记录；'
              '需要继续的话，再发一条消息即可。';
        }

        // ---------- 插件工具调用循环 ----------
        if (settings.pluginEnabled && plugin != null) {
          final call = OpenApiPlugin.parseToolCall(full);
          if (call != null) {
            final opId = call['tool'] as String;
            final args = call['arguments'] as Map<String, dynamic>;
            conv.status = '调用插件 $opId…';
            notifyListeners();
            String result;
            try {
              result = await plugin!.call(opId, args, apiKey: settings.apiKey);
            } catch (e) {
              result = '工具调用失败：$e';
            }
            answer.content = '';
            answer.setStreaming(true);
            messages.add({'role': 'assistant', 'content': full});
            messages.add({
              'role': 'user',
              'content':
                  '[工具 $opId 的返回结果]\n$result\n请据此用自然语言给出最终答案，不要再输出工具 JSON。',
            });
            req = _withMessages(req, messages);
            conv.status = '已调用 $opId，整理答案中…';
            notifyListeners();
            continue;
          }
        }
        break;
      }
    } catch (e) {
      final msg = e.toString();
      if (msg.contains('Connection closed while receiving data') ||
          msg.contains('HttpException')) {
        finalError = '网关在传输中关闭了连接。若本次附带了图片，'
            '多为图片请求体过大或该中转不支持多模态；'
            '可在 设置 → 多模态 缩小图片 / 切换发送格式后重试。';
      } else {
        finalError = '生成异常：$e';
      }
    } finally {
      ctx.flushTimer?.cancel();
      ctx.flushTimer = null;
      _flush(ctx, force: true);
      ctx.target = null;
      ctx.cancel = null;
      answer.finish(err: finalError);
      answer.elapsedMs = ctx.sw.elapsedMilliseconds;

      // 网关未返回 usage 时用本地估算兜底，并明确标注为估算值。
      final usage =
          apiUsage ?? TokenUsage.estimate(promptSnapshot, answer.content);
      answer.usage = usage;
      tokenStats.add(usage, model: settings.model);
      _recordPromptCache(usage, settings.model);
      scheduleHistorySave();

      if (settings.autoRecord) {
        final body = req.toBody();
        body.remove('stream');
        _addRecord(ExperimentRecord(
          id: _id(),
          at: DateTime.now().millisecondsSinceEpoch,
          kind: 'chat',
          presetName: settings.activePreset.name,
          model: settings.model,
          tier: t.label,
          query: text,
          params: {
            'max_tokens': t.maxTokens,
            'temperature': t.temperature,
            'top_p': t.topP,
            'thinking_budget': t.thinkingBudget,
            'reasoning_effort': t.reasoningEffort,
            'web_search': settings.searchActive,
            'preset': settings.activePreset.name,
          },
          requestBody: const JsonEncoder.withIndent('  ').convert(body),
          responseRaw: answer.content,
          elapsedMs: ctx.sw.elapsedMilliseconds,
          error: finalError,
          usage: usage,
        ));
      }
      conv.generating = false;
      conv.status = '';
      notifyListeners();

      // 自动朗读：只在用户仍停在这个会话时出声。
      // 后台会话回答完就突然开口，是很吓人的体验。
      final spoken = answer.content.trim();
      if (settings.autoSpeak &&
          settings.ttsEnabled &&
          !settings.voiceMuted &&
          finalError == null &&
          spoken.isNotEmpty &&
          active.id == conv.id) {
        unawaited(speak(spoken));
      }
    }
  }

  void _addRecord(ExperimentRecord r) {
    records.insert(0, r);
    if (records.length > 120) records.removeRange(120, records.length);
  }

  void clearRecords() {
    records.clear();
    notifyListeners();
  }

  void resetTokenStats() {
    tokenStats.reset();
    notifyListeners();
    unawaited(flushHistory());
  }

  /// 本地费用估算（¥）。单价为 0 时返回 null。
  double? get estimatedCost {
    final i = settings.priceInPerM;
    final o = settings.priceOutPerM;
    if (i <= 0 && o <= 0) return null;
    return tokenStats.prompt / 1000000 * i +
        tokenStats.completion / 1000000 * o;
  }

  String exportRecordsMarkdown() {
    final b = StringBuffer();
    b.writeln('# Aigent 实验记录');
    b.writeln('\n共 ${records.length} 条 · 累计 ${tokenStats.total} tok');
    for (final r in records) {
      b.writeln('\n${r.toMarkdown()}');
    }
    return b.toString();
  }

  String exportRecordsJson() => const JsonEncoder.withIndent('  ')
      .convert(records.map((r) => r.toJson()).toList());

  String exportUsageCsv() {
    final b = StringBuffer();
    b.writeln('model,prompt_tokens,completion_tokens,total_tokens,requests');
    for (final e in tokenStats.byModel.entries) {
      b.writeln('"${e.key.replaceAll('"', '""')}",${e.value.prompt},'
          '${e.value.completion},${e.value.total},');
    }
    b.writeln('ALL,${tokenStats.prompt},${tokenStats.completion},'
        '${tokenStats.total},${tokenStats.requests}');
    return b.toString();
  }

  /// 只停止当前活动会话的生成；后台其它会话不受影响。
  void stop() {
    final ctx = _streams[activeId];
    ctx?.cancel?.cancel('用户停止');
    // 有动作正等用户确认时，停止一律按「跳过」收尾，不能让生成流程悬挂。
    resolveAgentAction(false);
    // 立即撤掉状态栏，避免检索阶段停止后仍停在「联网检索中…」。
    if (active.status.isNotEmpty) {
      active.status = '';
      notifyListeners();
    }
    // 研究工作流的取消令牌也挂在同一会话的上下文上。
    if (researching) {
      ctx?.cancel?.cancel('用户停止');
    }
  }

  Future<void> regenerate() async {
    final msgs = active.messages;
    if (msgs.isEmpty) return;
    var last = '';
    for (var i = msgs.length - 1; i >= 0; i--) {
      if (msgs[i].role == Role.user) {
        last = msgs[i].content;
        break;
      }
    }
    final removeFrom = msgs.lastIndexWhere((m) => m.role == Role.user);
    if (removeFrom >= 0) {
      msgs.removeRange(removeFrom, msgs.length);
      notifyListeners();
    }
    if (last.isNotEmpty) await send(last);
  }

  // ------------------------------------------------------------ 深度研究工作流

  String get researchStatusLabel => researching
      ? '${researchStage.label}${researchStep > 0 ? ' · $researchStep/$researchTotal' : ''}'
      : researchStage.label;

  /// 一次工作流内所有子请求共用同一个取消令牌，停止按钮随时可中断。
  Future<({String text, TokenUsage? usage})> _researchStep({
    required String system,
    required String user,
    required String label,
    required CancelToken? cancel,
  }) async {
    final t = settings.tier;
    final req = LlmRequest(
      baseUrl: settings.baseUrl,
      apiKey: settings.apiKey,
      model: settings.model,
      messages: [
        {'role': 'system', 'content': system},
        {'role': 'user', 'content': user},
      ],
      maxTokens: t.maxTokens,
      temperature: t.temperature,
      topP: t.topP,
      thinkingBudget: t.thinkingBudget,
      reasoningEffort: t.reasoningEffort,
      deepThinking: settings.deepThinking,
      includeUsage: settings.usageTracking,
    );
    final r = await llm.completeWithUsage(req, cancel: cancel);
    final usage = r.usage ?? TokenUsage.estimate('$system\n$user', r.text);
    // 命中本地响应缓存时并没有发出请求，不能把同一笔 token 再算进累计
    // 用量与花费；命中记录已由 LlmClient.onCacheHit 写进缓存台账。
    if (!r.fromCache) {
      tokenStats.add(usage, model: settings.model);
      _recordPromptCache(usage, settings.model);
    }
    scheduleHistorySave();
    if (settings.autoRecord) {
      final body = req.toBody();
      body.remove('stream');
      _addRecord(ExperimentRecord(
        id: _id(),
        at: DateTime.now().millisecondsSinceEpoch,
        kind: 'research',
        presetName: '${settings.activePreset.name} · $label',
        model: settings.model,
        tier: settings.tier.label,
        query: user.length > 200 ? '${user.substring(0, 200)}…' : user,
        params: {
          'phase': label,
          'max_tokens': t.maxTokens,
          'temperature': t.temperature,
          'top_p': t.topP,
        },
        requestBody: const JsonEncoder.withIndent('  ').convert(body),
        responseRaw: r.text,
        elapsedMs: 0,
        usage: usage,
      ));
    }
    return (text: r.text, usage: usage);
  }

  static List<String> _parseSections(String outline, int n) {
    final lines = outline
        .split('\n')
        .map((l) => l.trim())
        .where((l) => l.isNotEmpty)
        .map((l) => l
            .replaceAll(RegExp(r'^#{1,4}\s*'), '')
            .replaceAll(RegExp(r'^\s*(?:\d+[\.、）)]?|[-*•])\s*'), '')
            .trim())
        .where((l) => l.length > 1 && l.length < 80)
        .toList();
    final seen = <String>{};
    final out = <String>[];
    for (final l in lines) {
      if (seen.add(l)) out.add(l);
      if (out.length >= n) break;
    }
    var i = 1;
    while (out.length < n) {
      out.add('补充视角 ${i++}');
    }
    return out;
  }

  /// 检索 → 大纲 → 逐节展开 → 汇总核对，产出一份可导出的 Markdown 报告。
  Future<void> runResearch(String topic) async {
    final q = topic.trim();
    final conv = active;
    if (q.isEmpty || conv.generating || researching) return;

    // 与 send 一样捕获会话与流上下文，切换会话后状态只落回原会话。
    final ctx = _stream(conv.id);
    if (conv.messages.isEmpty) {
      conv.title = q.length > 18 ? '${q.substring(0, 18)}…' : q;
    }
    final answer = ChatMessage(
      id: _id(),
      role: Role.assistant,
      content: '',
      streaming: true,
      model: settings.model,
      tierLabel: settings.tier.label,
    );
    conv.messages.add(ChatMessage(id: _id(), role: Role.user, content: q));
    conv.messages.add(answer);

    ctx.cancel = CancelToken();
    ctx.sw
      ..reset()
      ..start();
    researchTopic = q;
    researchReport = '';
    researchStep = 0;
    researchTotal = settings.sectionCount;
    researchStage = ResearchStage.searching;
    conv.generating = true;
    globalError = null;
    conv.status = '检索资料…';
    notifyListeners();

    var cancelled = false;
    String? error;
    final persona = settings.personaFor(conv.personaId);
    try {
      // ---- 阶段 1：多源检索（仅在联网真正开启时） ----
      var sourceBlock = '（本次未启用联网检索，章节内容基于模型自身知识，请自行核实。）';
      if (settings.searchActive) {
        final hits = await searchSvc.search(q, settings, cancel: ctx.cancel);
        if (!(ctx.cancel?.isCancelled ?? false)) {
          final cites = SearchService.toCitations(hits);
          answer.setCitations(cites);
          answer.searchQuery = q;
          if (hits.isNotEmpty) {
            sourceBlock = SearchService.buildContext(hits);
          }
        }
      }
      if (ctx.cancel?.isCancelled ?? false) {
        cancelled = true;
        throw StateError('已取消');
      }

      // ---- 阶段 2：拟定大纲 ----
      researchStage = ResearchStage.outlining;
      conv.status = '拟定大纲…';
      notifyListeners();
      final outline = await _researchStep(
        label: '大纲',
        cancel: ctx.cancel,
        system: buildSystemPrompt(query: q, withTools: false, persona: persona),
        user: '研究主题：$q\n\n请只输出 $researchTotal 个互不重叠的章节标题，'
            '每行一个，不要编号、不要解释、不要额外文字。'
            '章节应覆盖：背景与定义、关键事实、不同观点与争议、局限与开放问题。\n\n'
            '可用资料：\n$sourceBlock',
      );
      final sections = _parseSections(outline.text, researchTotal);

      // ---- 阶段 3：逐节展开 ----
      answer.append('# $q\n\n');
      final parts = <String>[];
      for (var i = 0; i < sections.length; i++) {
        if (ctx.cancel?.isCancelled ?? false) {
          cancelled = true;
          throw StateError('已取消');
        }
        researchStage = ResearchStage.drafting;
        researchStep = i + 1;
        researchTotal = sections.length;
        conv.status = '逐节展开 ${i + 1}/${sections.length}';
        notifyListeners();

        final r = await _researchStep(
          label: '章节 ${i + 1}',
          cancel: ctx.cancel,
          system:
              buildSystemPrompt(query: q, withTools: false, persona: persona),
          user: '研究主题：$q\n当前章节：${sections[i]}\n'
              '已有章节：${parts.isEmpty ? "无" : parts.map((p) => p.split("\n").first).join("、")}\n\n'
              '请只写这一章，300-500 字，不要重复其他章节内容。'
              '有资料时以 [1] [2] 标注依据，区分「资料所述」与「推断」。\n\n'
              '资料：\n$sourceBlock',
        );
        final section = '## ${sections[i]}\n\n${r.text.trim()}';
        parts.add(section);
        answer.append('$section\n\n');
      }

      // ---- 阶段 4：汇总核对 ----
      researchStage = ResearchStage.verifying;
      conv.status = '核对引用…';
      notifyListeners();
      final date =
          '${DateTime.now().year}-${DateTime.now().month.toString().padLeft(2, '0')}-'
          '${DateTime.now().day.toString().padLeft(2, '0')}';
      final b = StringBuffer();
      b.writeln('# $q');
      b.writeln('\n> Aigent 深度研究 · ${settings.activePreset.name} · '
          '${settings.model} · ${settings.tier.label} · $date');
      b.writeln('\n## 资料来源\n');
      if (answer.citations.isNotEmpty) {
        for (final c in answer.citations) {
          b.writeln('[${c.index}] ${c.title} — ${c.url}');
        }
      } else {
        b.writeln(sourceBlock);
      }
      b.writeln('\n---\n');
      b.writeln(parts.join('\n\n'));
      b.writeln('\n---\n');
      b.writeln('本报告由多轮模型调用自动汇总，请核实关键事实与来源后再引用。');
      researchReport = b.toString();
    } catch (e) {
      if (!cancelled) error = '$e';
    } finally {
      answer.finish(err: cancelled ? null : error);
      answer.elapsedMs = ctx.sw.elapsedMilliseconds;
      researchStage = cancelled
          ? ResearchStage.failed
          : (error == null ? ResearchStage.done : ResearchStage.failed);
      conv.generating = false;
      ctx.cancel = null;
      conv.status = '';
      notifyListeners();
    }
  }

  String exportResearchReport() =>
      researchReport.isEmpty ? '# 暂无研究报告\n\n请先在工具抽屉里发起一次深度研究。' : researchReport;

  // -------------------------------------------------------------- 语音

  /// 朗读引擎。id 失效（旧配置 / 手改 JSON）时回落到系统语音。
  TtsEngine get activeTtsEngine =>
      ttsEngineById(settings.ttsEngineId) ?? kTtsEngines.first;

  SttEngine get activeSttEngine =>
      sttEngineById(settings.sttEngineId) ?? kSttEngines.first;

  /// 「跟随连接」的引擎用当前 baseUrl；其余用自身地址，允许被自定义地址覆盖。
  String resolveTtsBaseUrl() {
    final e = activeTtsEngine;
    if (e.followsConnection) return settings.baseUrl;
    final custom = settings.ttsBaseUrl.trim();
    return custom.isEmpty ? e.baseUrl : custom;
  }

  String resolveTtsKey() {
    final e = activeTtsEngine;
    if (e.followsConnection) return settings.apiKey;
    return settings.voiceTtsKey;
  }

  String resolveSttBaseUrl() {
    final e = activeSttEngine;
    if (e.followsConnection) return settings.baseUrl;
    final custom = settings.sttBaseUrl.trim();
    return custom.isEmpty ? e.baseUrl : custom;
  }

  String resolveSttKey() {
    final e = activeSttEngine;
    if (e.followsConnection) return settings.apiKey;
    return settings.voiceSttKey;
  }

  /// 朗读一段文本。返回 null 表示已开始播放，否则是错误文案。
  /// 静音时不出声但给出明确提示；顶栏 / 长按菜单会在调用前自动解除静音。
  Future<String?> speak(String text) {
    if (settings.voiceMuted) {
      return Future<String?>.value('朗读已静音，点右上角音量键开启');
    }
    final e = activeTtsEngine;
    return VoiceService.instance.speak(
      text: text,
      engine: e,
      voice: settings.ttsVoice,
      rate: settings.ttsRate,
      lang: settings.voiceLang,
      baseUrl: resolveTtsBaseUrl(),
      apiKey: resolveTtsKey(),
      model: settings.ttsModel,
    );
  }

  Future<void> stopSpeaking() => VoiceService.instance.stop();

  /// 语音引擎密钥单独保存：和连接密钥共用加密仓，不进设置快照。
  Future<void> setVoiceKey({required bool tts, required String key}) async {
    final v = key.trim();
    if (tts) {
      settings.voiceTtsKey = v;
    } else {
      settings.voiceSttKey = v;
    }
    await persist();
    notifyListeners();
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import 'skin.dart';

/// v4 设计语言：Quiet Depth（静水深）。
///
/// 用「画布 / 纸面」两层材质建立深度：页面是微冷的浅灰，内容是纯白纸片，
/// 纸片靠 1px 极淡描边 + 大模糊低透明阴影浮起，而不是靠卡片色块或渐变。
/// 强调色严格限制在发送键、链接、选中态；不使用发光、彩色渐变、装饰图标。
class C {
  static Palette get _l => Skin.light;
  static Palette get _d => Skin.dark;

  /// 强调色：浅色 / 深色各取当前皮肤的一支。
  static Color get brand => _l.accent;
  static Color get brandSoft => _l.accent.withOpacity(0.10);
  static Color get brandDark => _d.accent;

  static Color get ink => _l.ink;
  static Color get ink2 => _l.ink2;
  static Color get ink3 => _l.ink3;

  /// 画布（页面底）与纸面（卡片 / 抽屉 / 弹层）。
  static Color get paper => _l.bg;
  static Color get surface => _l.surface;

  /// 内嵌次级表面：输入框、代码块、折叠块。
  static Color get sink => _l.sink;
  static Color get line => _l.line;
  static Color get hair => _l.hair;
  static Color get border => _l.border;

  /// 控件描边：比 [border] 深一档，专门给按钮 / 可点标签 / 下拉框用。
  static Color get borderStrong => _l.borderStrong;
  static Color get dBorderStrong => _d.borderStrong;
  static Color get bg => _l.bg;
  static Color get card => _l.surface;

  // 深色一侧沿用同一套语义名，避免每个调用点都写 dark ? a : b。
  static Color get dInk => _d.ink;
  static Color get dInk2 => _d.ink2;
  static Color get dInk3 => _d.ink3;
  static Color get dPaper => _d.bg;
  static Color get dSurface => _d.surface;
  static Color get dLine => _d.line;
  static Color get dHair => _d.hair;
  static Color get dBorder => _d.border;
  static Color get dBg => _d.bg;
  static Color get dCard => _d.surface;
  static Color get dSink => _d.sink;

  static Color get ok => _l.ok;
  static Color get warn => _l.warn;
  static Color get danger => _l.danger;

  /// 用户气泡：跟随强调色，保证整屏只有一支可点色。
  static Color get bubble => _l.bubble;
  static Color get dBubble => _d.bubble;
}

class D {
  static const double u = 8;

  /// 通用圆角：按钮、缩略图、输入框。随「圆角强度」缩放。
  static double get r => 11 * Skin.radius;

  /// 纸片圆角。
  static double get cardR => 16 * Skin.radius;

  /// 输入台圆角。
  static double get floatR => 20.0 * Skin.radius;
  static const Duration animFast = Duration(milliseconds: 140);
  static const Duration anim = Duration(milliseconds: 220);
  static const Duration animSlow = Duration(milliseconds: 300);
  static const Cubic curve = Curves.easeOutCubic;
  static const Cubic curveInOut = Curves.easeInOutCubic;
  static const double pagePad = 16;
  static const double flushInterval = 40;
}

/// 全应用统一页面转场。
///
/// 只有一条实现：新页整幅从右侧推入，旧页**完全静止**。手势返回时，
/// 手指的实时进度直接驱动这条位移，做到 1:1 跟手。
///
/// 为什么不直接用 Flutter 自带的 `PredictiveBackPageTransitionsBuilder`：
/// 它在转场里给整页套了一层 `Opacity`（Android 14 原生效果需要"变暗"），
/// 而全屏 `Opacity` 会强制 `saveLayer` —— 每一帧都要把整页离屏渲染一遍
/// 再合成。低端机上这就是几百毫秒的卡顿，正是「点进去返回卡一下」的
/// 直接来源。这里改用纯位移：只有一层 transform，光栅缓存可以整帧复用。
class SoftPageTransitionsBuilder extends PageTransitionsBuilder {
  const SoftPageTransitionsBuilder();

  @override
  Widget buildTransitions<T>(
    PageRoute<T> route,
    BuildContext context,
    Animation<double> animation,
    Animation<double> secondaryAnimation,
    Widget child,
  ) =>
      _SoftPageTransition(route: route, animation: animation, child: child);
}

/// 统一转场时长的路由。
///
/// `MaterialPageRoute` 默认 300ms。整页切换走 300ms 会显得"拖"：用户
/// 点一下，页面慢悠悠推半秒，手指早已移到别处。240ms 是 iOS 与
/// Material 动效规范的主流区间，返回再快一点（200ms），因为返回是
/// 用户已经确定要走，不该让他等。
///
/// 基类用 `PageRouteBuilder` 而不是 `MaterialPageRoute`：后者在构造函数
/// 里 `assert(opaque)`，而二级页面需要 `opaque = false`（见 [keepBelow]）。
class SoftPageRoute<T> extends PageRouteBuilder<T> {
  SoftPageRoute({
    required WidgetBuilder builder,
    super.settings,
    super.maintainState,
    super.fullscreenDialog,
    super.allowSnapshotting,
    // v4.25：默认改为 true。以前只有设置子页显式传了 keepBelow，其余页面
    // 仍是 opaque=true —— 预测性侧滑时框架会临时把下层保持 onstage，所以
    // 侧滑很顺；但点顶栏按钮走的是普通 pop，下层要从 offstage 恢复、在动画
    // 第一帧重新布局并光栅化整页，正好就是「点按钮返回卡一下」的来源。
    // 统一让下层常驻，按钮返回和侧滑就走同一条零重建路径。
    this.keepBelow = true,
  }) : super(
          pageBuilder: (context, animation, secondaryAnimation) =>
              builder(context),
          transitionDuration: const Duration(milliseconds: 240),
          reverseTransitionDuration: const Duration(milliseconds: 200),
          opaque: !keepBelow,
        );

  /// 是否让被压在下面的那一页**始终保持布局与光栅缓存**。
  ///
  /// v4.25 起默认 true（全站统一，按钮返回不再首帧重建下层）。
  /// 路由不透明时，`Overlay` 会把下层整个从渲染树上摘下来
  /// （`_Theater.skipCount`），不布局也不绘制——这是省 GPU 的正常做法。
  ///
  /// 但二级页面必须置 true，否则会出现「点进去再返回，先卡几百毫秒」：
  /// 返回动画开始的**第一帧**，下层要从 offstage 恢复，重新布局整页
  /// （十几个卡片、几十行中文）再光栅化一次。这一帧的耗时就是那段卡顿，
  /// 而且它正好落在动画起点，看起来像「点了一下没反应」。
  ///
  /// 置 true 后下层一直是 onstage：静止时它的光栅缓存命中，等于零成本；
  /// 只有滚动时多合成一层，实测不到 1ms。
  final bool keepBelow;

  @override
  Widget buildTransitions(
    BuildContext context,
    Animation<double> animation,
    Animation<double> secondaryAnimation,
    Widget child,
  ) =>
      const SoftPageTransitionsBuilder()
          .buildTransitions(this, context, animation, secondaryAnimation, child);
}

/// 页面转场本体：位移 + 手势进度接管。
///
/// 结构在整个生命周期里**从不改变**（永远是同一个 `SlideTransition`），
/// 只切换驱动它的动画对象。这一点很关键：如果手势开始时换一套 widget
/// 结构，手指松开的瞬间（手势结束、动画继续）画面会跳一下。
class _SoftPageTransition extends StatefulWidget {
  const _SoftPageTransition({
    required this.route,
    required this.animation,
    required this.child,
  });

  final PageRoute<dynamic> route;
  final Animation<double> animation;
  final Widget child;

  @override
  State<_SoftPageTransition> createState() => _SoftPageTransitionState();
}

class _SoftPageTransitionState extends State<_SoftPageTransition>
    with WidgetsBindingObserver {
  /// 当前是否还欠着一次 `Navigator.didStopUserGesture()`。
  ///
  /// 手势进行中导航器会进入 `userGestureInProgress`，这个状态下所有页面
  /// 都不接收点击。必须保证「开一次、关一次」，否则整个 App 会点不动。
  bool _gestureLocked = false;

  /// 两条位移动画在 State 里**只创建一次**。
  ///
  /// 以前的 build 里每帧 `new CurvedAnimation(...)` + `animation.drive(Tween)`：
  /// 一个 200ms 返回动画就要分配十几个动画对象，旧的还挂在 parent 上等 GC，
  /// `SlideTransition` 每帧都要 `didUpdateWidget` 重新挂监听。现在 build 里
  /// 只剩一次三元判断，零分配。
  _SoftPositions? _positions;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _positions = _SoftPositions(widget.animation);
  }

  @override
  void didUpdateWidget(_SoftPageTransition old) {
    super.didUpdateWidget(old);
    if (old.animation != widget.animation) {
      _positions = _SoftPositions(widget.animation);
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    // 手势没走完就被销毁（极罕见）：把锁还回去，别把整个导航器留在
    // 「不接受点击」的状态里。
    if (_gestureLocked) {
      widget.route.navigator?.didStopUserGesture();
      _gestureLocked = false;
    }
    super.dispose();
  }

  @override
  bool handleStartBackGesture(PredictiveBackEvent backEvent) {
    final route = widget.route;
    // 只有最上层、且允许返回的路由接管手势；下层直接放行。
    if (backEvent.isButtonEvent ||
        !route.isCurrent ||
        !route.popGestureEnabled) {
      return false;
    }
    route.handleStartBackGesture(progress: 1 - backEvent.progress);
    // 记住「全局指针锁」已经打开，等这次手势收尾时负责关掉。
    _gestureLocked = true;
    return true;
  }

  @override
  void handleUpdateBackGestureProgress(PredictiveBackEvent backEvent) {
    widget.route.handleUpdateBackGestureProgress(
      progress: 1 - backEvent.progress,
    );
  }

  @override
  void handleCancelBackGesture() {
    _gestureLocked = false;
    widget.route.handleCancelBackGesture();
  }

  @override
  void handleCommitBackGesture() {
    final route = widget.route;
    final nav = route.navigator;
    if (nav == null || !_gestureLocked) return;

    // 这里是「点一次没反应、要点第二次」的真凶。
    //
    // 框架默认的 `route.handleCommitBackGesture()` 会按手指位置把退场动画
    // 拉长到最多 800ms，并且把 `userGestureInProgress` 一直保持到动画结束：
    //
    //   didStopUserGesture() 是在动画的 status 变成 dismissed 时才调用的。
    //
    // 而 `_ModalScope` 拿这个标志当「本次事件一律不派发」的开关——
    // 只要它为 true，**每一个**页面都会被 `IgnorePointer(ignoring: true)`
    // 包住。配合 `Curves.fastLinearToSlowEaseIn` 那种极平的收尾曲线，
    // 页面在最后三四百毫秒里看起来已经完全静止，实际上所有点击都被吞掉，
    // 于是用户只能再点一次。
    //
    // 改成：手势一结束立刻解锁，退场走我们自己的 200ms 反向转场
    // （`Navigator.pop` 会用 `reverseTransitionDuration`，并且从控制器
    // 当前值继续，不会跳）。
    nav.didStopUserGesture();
    _gestureLocked = false;
    if (route.isCurrent) {
      nav.pop();
    }
  }

  @override
  Widget build(BuildContext context) {
    // 从右往左书写的语言里，页面应该从左边进来。
    final rtl = Directionality.of(context) == TextDirection.rtl;
    final p = _positions!;
    return SlideTransition(
      position: rtl ? p.rtl : p.ltr,
      child: RepaintBoundary(child: widget.child),
    );
  }
}

/// 页面位移：进入从右侧整屏滑入，退出整屏滑回右侧。
///
/// 这里曾经出过一个很难看出来的 bug：点按钮的路径用 0.35 屏位移，
/// 想「缩短两页同屏时间」。但 [PageRouteBuilder] 的 animation 对同一个
/// 路由在进入（0→1）和退出（1→0）是共用的，同一条 tween 于是变成
/// 「进场滑 35%，退场也滑 35%」。
///
/// 结果就是点返回键时，被关掉的页面在 200ms 里只挪了三分之一屏，
/// 剩下的三分之二一直焊在原地，等动画结束被整页摘掉——看起来
/// 就是「卡了几百毫秒，然后突然消失」。而侧滑是 1:1 整屏跟手，
/// 所以同一个页面侧滑很顺、点按钮必卡。
///
/// 现在两条路径统一整屏位移：手势是 1:1 跟手，按钮是 240ms 覆盖一屏，
/// 退出时干净利落地完全移出屏幕。
class _SoftPositions {
  _SoftPositions(Animation<double> a)
      : ltr = a.drive(Tween<Offset>(
            begin: const Offset(1, 0), end: Offset.zero)),
        rtl = a.drive(Tween<Offset>(
            begin: const Offset(-1, 0), end: Offset.zero));

  final Animation<Offset> ltr;
  final Animation<Offset> rtl;
}

// ---------------------------------------------------------------- 材质取色

Color lineOf(bool dark) => dark ? C.dLine : C.line;
Color hairOf(bool dark) => dark ? C.dHair : C.hair;
Color sinkOf(bool dark) => dark ? C.dSink : C.sink;
Color accentOf(bool dark) => dark ? C.brandDark : C.brand;
Color canvasOf(bool dark) => dark ? C.dPaper : C.paper;
Color surfaceOf(bool dark) => dark ? C.dSurface : C.surface;
Color fieldOf(bool dark) => dark ? C.dSink : C.sink;
Color borderOf(bool dark) => dark ? C.dBorder : C.border;
Color borderStrongOf(bool dark) => dark ? C.dBorderStrong : C.borderStrong;

/// 双层柔和阴影：一层负责「浮起」，一层负责「贴边」。
/// 透明度刻意压得很低——阴影一旦可被察觉，就会变成廉价的「贴纸感」。
List<BoxShadow> softShadow(bool dark, {double scale = 1}) => [
      BoxShadow(
        color: dark ? const Color(0x3D000000) : const Color(0x0D1B2C4D),
        blurRadius: 20 * scale,
        offset: Offset(0, 6 * scale),
      ),
      BoxShadow(
        color: dark ? const Color(0x24000000) : const Color(0x081B2C33),
        blurRadius: 4 * scale,
        offset: Offset(0, 1 * scale),
      ),
    ];

/// 白纸片：细描边 + 柔和阴影。所有内容卡片的统一入口。
BoxDecoration surfaceBox(
  bool dark, {
  double? radius,
  bool shadow = true,
  bool border = true,
  Color? fill,
  double shadowScale = 1,
}) {
  return BoxDecoration(
    color: fill ?? surfaceOf(dark),
    borderRadius: BorderRadius.circular(radius ?? D.cardR),
    border: border ? Border.all(color: borderOf(dark), width: 1) : null,
    boxShadow: shadow ? softShadow(dark, scale: shadowScale) : null,
  );
}

/// 内嵌块：无阴影，只有圆角与底色，用于思考摘要、引用区、代码块。
BoxDecoration insetBox(bool dark, {double? radius, Color? fill}) {
  return BoxDecoration(
    color: fill ?? fieldOf(dark),
    borderRadius: BorderRadius.circular(radius ?? D.r),
    border: Border.all(color: borderOf(dark), width: 1),
  );
}

/// 浮起的输入台 / 弹层顶面。
BoxDecoration raisedBox(bool dark, {double? radius}) =>
    surfaceBox(dark, radius: radius ?? D.floatR, shadowScale: 1.35);

/// 圆角输入框：浅灰填充 + 极淡描边，聚焦时描边转墨蓝。
InputDecoration fieldDecoration(
  bool dark, {
  String? hint,
  Widget? suffix,
  Widget? prefix,
  EdgeInsets? padding,
}) {
  OutlineInputBorder outline(Color c, double w) => OutlineInputBorder(
        borderRadius: BorderRadius.circular(D.r),
        borderSide: BorderSide(color: c, width: w),
      );
  return InputDecoration(
    filled: true,
    fillColor: fieldOf(dark),
    hintText: hint,
    hintStyle:
        TextStyle(color: dark ? C.dInk3 : C.ink3, fontSize: 12.5, height: 1.4),
    isDense: true,
    contentPadding:
        padding ?? const EdgeInsets.symmetric(horizontal: 13, vertical: 12),
    border: outline(borderOf(dark), 1),
    enabledBorder: outline(borderOf(dark), 1),
    focusedBorder: outline(accentOf(dark), 1.4),
    suffixIcon: suffix,
    suffixIconConstraints: const BoxConstraints(maxHeight: 34, maxWidth: 60),
    prefixIcon: prefix,
    prefixIconConstraints: prefix == null
        ? null
        : const BoxConstraints(maxHeight: 34, maxWidth: 44),
  );
}

/// 兼容旧调用点：返回圆角纸片，不再产生只有一条细线的「假卡片」。
BoxDecoration hairlineBox(bool dark, {bool top = false}) =>
    surfaceBox(dark, radius: D.r, shadow: false);

/// 兼容旧调用点：统一为纸片装饰。
BoxDecoration panelBox(bool dark, {Color? fill, bool border = true}) =>
    surfaceBox(dark, radius: D.r, shadow: false, border: border, fill: fill);

// ---------------------------------------------------------------- 排版

TextStyle ts(bool dark,
    {double size = 14,
    FontWeight weight = FontWeight.w400,
    Color? color,
    double? height,
    double spacing = 0}) {
  return TextStyle(
    fontSize: size,
    fontWeight: weight,
    color: color ?? (dark ? C.dInk : C.ink),
    height: height ?? 1.6,
    letterSpacing: spacing,
  );
}

TextStyle sub(bool dark, {double size = 13}) =>
    ts(dark, size: size, color: dark ? C.dInk2 : C.ink2);

/// 元信息：小字号 + 低对比，用于时间、模型、计数。
/// 中文不加字距——加了会显得松散做作，这也是「模板感」的来源之一。
TextStyle meta(bool dark, {double size = 12, Color? color, double? height}) =>
    ts(
      dark,
      size: size,
      color: color ?? (dark ? C.dInk2 : C.ink2),
      height: height,
    );

/// 数字专用：等宽数字（tabular figures），让耗时、token 数不会左右跳动。
TextStyle numStyle(
  bool dark, {
  double size = 10.5,
  Color? color,
  FontWeight weight = FontWeight.w400,
}) =>
    ts(dark,
            size: size,
            color: color ?? (dark ? C.dInk3 : C.ink3),
            weight: weight)
        .copyWith(fontFeatures: const [FontFeature.tabularFigures()]);

/// 分区标题：小标题，实色、不加宽字距。
///
/// 旧版是 10.5px + 1.5 字距 + 最浅灰，中文在手机上会被拉成一条虚线似的淡影子，
/// 标题读不出来、页面也显得灰。中文不需要靠字距「撑」出高级感，
/// 靠字号与字重区分层级就够了。
TextStyle sectionTitle(bool dark) => TextStyle(
      fontSize: 11.5,
      fontWeight: FontWeight.w600,
      height: 1.3,
      letterSpacing: 0.2,
      color: dark ? C.dInk2 : C.ink2,
    );

/// 大标题：负字距、重字重，形成编辑式版面。
TextStyle display(bool dark, {double size = 28}) => TextStyle(
      fontSize: size,
      fontWeight: FontWeight.w600,
      letterSpacing: -0.8,
      height: 1.28,
      color: dark ? C.dInk : C.ink,
    );

ThemeData buildAppTheme(Brightness brightness) {
  final dark = brightness == Brightness.dark;
  final scheme = ColorScheme.fromSeed(
    seedColor: C.brand,
    brightness: brightness,
  ).copyWith(
    primary: dark ? C.brandDark : C.brand,
    onPrimary: Colors.white,
    surface: surfaceOf(dark),
    outline: borderOf(dark),
  );
  final base = dark ? C.dInk : C.ink;
  return ThemeData(
    useMaterial3: true,
    colorScheme: scheme,
    brightness: brightness,
    scaffoldBackgroundColor: canvasOf(dark),
    canvasColor: canvasOf(dark),
    dividerColor: hairOf(dark),
    appBarTheme: AppBarTheme(
      backgroundColor: canvasOf(dark),
      foregroundColor: base,
      surfaceTintColor: Colors.transparent,
      elevation: 0,
      scrolledUnderElevation: 0,
      centerTitle: false,
      shape: Border(
        bottom: BorderSide(color: borderOf(dark), width: 1),
      ),
      titleTextStyle: TextStyle(
        color: base,
        fontSize: 16.5,
        fontWeight: FontWeight.w700,
        letterSpacing: -0.3,
      ),
      iconTheme: IconThemeData(color: dark ? C.dInk2 : C.ink2, size: 20),
    ),
    iconTheme: IconThemeData(color: dark ? C.dInk2 : C.ink2, size: 20),
    textTheme: (dark ? ThemeData.dark() : ThemeData.light()).textTheme.apply(
          bodyColor: base,
          displayColor: base,
        ),
    inputDecorationTheme: InputDecorationTheme(
      filled: true,
      fillColor: fieldOf(dark),
      hintStyle: TextStyle(
          color: dark ? C.dInk3 : C.ink3, fontSize: 12.5, height: 1.4),
      isDense: true,
      contentPadding: const EdgeInsets.symmetric(horizontal: 13, vertical: 12),
      border: OutlineInputBorder(
        borderRadius: BorderRadius.circular(D.r),
        borderSide: BorderSide(color: borderOf(dark)),
      ),
      enabledBorder: OutlineInputBorder(
        borderRadius: BorderRadius.circular(D.r),
        borderSide: BorderSide(color: borderOf(dark)),
      ),
      focusedBorder: OutlineInputBorder(
        borderRadius: BorderRadius.circular(D.r),
        borderSide: BorderSide(color: accentOf(dark), width: 1.4),
      ),
    ),
    dividerTheme: DividerThemeData(color: hairOf(dark), thickness: 1, space: 1),
    splashFactory: InkRipple.splashFactory,
    splashColor: (dark ? C.dInk2 : C.ink2).withOpacity(0.08),
    highlightColor: Colors.transparent,
    cardTheme: CardTheme(
      color: surfaceOf(dark),
      surfaceTintColor: Colors.transparent,
      elevation: 0,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(D.cardR),
        side: BorderSide(color: borderOf(dark)),
      ),
    ),
    dialogTheme: DialogTheme(
      backgroundColor: surfaceOf(dark),
      surfaceTintColor: Colors.transparent,
      shape:
          RoundedRectangleBorder(borderRadius: BorderRadius.circular(D.cardR)),
    ),
    bottomSheetTheme: BottomSheetThemeData(
      backgroundColor: surfaceOf(dark),
      surfaceTintColor: Colors.transparent,
      modalBackgroundColor: surfaceOf(dark),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(D.floatR)),
      ),
    ),
    pageTransitionsTheme: const PageTransitionsTheme(
      builders: <TargetPlatform, PageTransitionsBuilder>{
        TargetPlatform.android: SoftPageTransitionsBuilder(),
        TargetPlatform.iOS: SoftPageTransitionsBuilder(),
        TargetPlatform.linux: SoftPageTransitionsBuilder(),
        TargetPlatform.macOS: SoftPageTransitionsBuilder(),
        TargetPlatform.windows: SoftPageTransitionsBuilder(),
      },
    ),
    snackBarTheme: SnackBarThemeData(
      behavior: SnackBarBehavior.floating,
      backgroundColor: dark ? C.dSink : C.ink,
      contentTextStyle:
          TextStyle(fontSize: 12.5, color: dark ? C.dInk : Colors.white),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(D.r)),
    ),
  );
}

import 'package:flutter/material.dart';
