  }
}

/// 设置 → 设备智能体。
///
/// 信息密度按「先看边界、再看授权、最后才看细节」排布：默认只展开三块，
/// 工具全集与执行记录收在折叠区，避免又变成一屏塞满开关的后台感。
class AgentPanel extends StatefulWidget {
  final bool dark;
  const AgentPanel({super.key, required this.dark});

  @override
  State<AgentPanel> createState() => _AgentPanelState();
}

class _AgentPanelState extends State<AgentPanel> {
  List<WorkspaceEntry> _files = const [];
  List<WorkspaceEntry> _trash = const [];
  bool _loading = true;
  bool _showTools = false;
  bool _showTrash = false;
  bool _showLog = false;

  bool get dark => widget.dark;

  @override
  void initState() {
    super.initState();
    _reload();
  }

  Future<void> _reload() async {
    final ws = context.read<AppState>().agentWorkspace;
    if (ws == null) {
      if (mounted) setState(() => _loading = false);
      return;
    }
    try {
      final f = await ws.list();
      final t = await ws.trashList();
      if (mounted) {
        setState(() {
          _files = f;
          _trash = t;
          _loading = false;
        });
      }
    } catch (_) {
      if (mounted) setState(() => _loading = false);
    }
  }

  Future<void> _refreshAll() async {
    setState(() => _loading = true);
    await context.read<AppState>().refreshAgentData();
    await _reload();
  }

  @override
  Widget build(BuildContext context) {
    final st = context.watch<AppState>();
    final s = st.settings;
    final ws = st.agentWorkspace;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _section(t('设备智能体'), [
          Text(t('默认只回答问题。打开后，模型能读到这台设备的真实信息，并在你授权的范围内真正做事：读写独立工作区、打开应用与网页、新建日历日程、设置闹钟。'),
            style: sub(dark, size: 12.5),
          ),
          const SizedBox(height: 14),
          SwitchRow(
            title: t('启用本机操作'),
            subtitle: t('关闭时与纯聊天客户端完全一致，不注入任何工具'),
            value: s.agentEnabled,
            icon: Icons.touch_app_outlined,
            onChanged: (v) => st.patch((x) => x.agentEnabled = v),
          ),
          const SizedBox(height: 4),
          _note(
            '安全边界：所有文件操作只发生在应用专属目录里，'
            '绝对路径、.. 、隐藏文件与符号链接一律拒绝；'
            '覆盖写会自动备份旧版，删除只是移入回收站，不会真正丢失文件。'
            '系统命令从不执行。',
          ),
        ]),
        _section(t('这台设备'), [
          ...st.deviceInfo.rows.map((r) => _kv(r.label, r.value)),
          const SizedBox(height: 10),
          _link('重新读取设备信息', Icons.refresh_rounded, _refreshAll),
        ]),
        _permissionSection(s, st),
        _section(t('授权范围'), [
          Text(t('未授权的动作不会执行，模型会收到「需要授权」的结果并改用文字说明。'),
              style: meta(dark, size: 11.5, height: 1.5)),
          const SizedBox(height: 12),
          SwitchRow(
            title: t('文件与脚本'),
            subtitle: t('隔离工作区内读写、任务脚本（沙箱保护）'),
            value: s.agentAllowWorkspace,
            onChanged: (v) => st.patch((x) {
              x.agentAllowWorkspace = v;
              x.markCustomPermission();
            }),
          ),
          SwitchRow(
            title: t('应用与网页'),
            subtitle: t('打开已装应用、调起系统浏览器、分享、写剪贴板'),
            value: s.agentAllowExternal,
            onChanged: (v) => st.patch((x) {
              x.agentAllowExternal = v;
              x.markCustomPermission();
            }),
          ),
          SwitchRow(
            title: t('日历与闹钟'),
            subtitle: t('只打开系统确认页，需你亲手点保存才生效'),
            value: s.agentAllowSystem,
            onChanged: (v) => st.patch((x) {
              x.agentAllowSystem = v;
              x.markCustomPermission();
            }),
          ),
          SwitchRow(
            title: t('网页抓取'),
            subtitle: t('读取公开网页正文（禁止内网 / 元数据地址）'),
            value: s.agentAllowNetwork,
            onChanged: (v) => st.patch((x) {
              x.agentAllowNetwork = v;
              x.markCustomPermission();
            }),
          ),
          SwitchRow(
            title: t('设备清理与文件删除'),
            subtitle: t('清理本应用缓存、查找并删除可访问目录里的文件（完全权限才建议开）'),
            value: s.agentAllowDevice,
            onChanged: (v) => st.patch((x) {
              x.agentAllowDevice = v;
              x.markCustomPermission();
            }),
          ),
          SwitchRow(
            title: t('每次操作先问我'),
            subtitle: t('写文件、打开应用等动作在界面上等你点「允许」'),
            value: s.agentConfirmEach,
            onChanged: (v) => st.patch((x) => x.agentConfirmEach = v),
          ),
          const SizedBox(height: 6),
          Text(t('单次任务最多执行几步'), style: meta(dark, size: 11.5)),
          const SizedBox(height: 8),
          Row(
            children: [2, 4, 6, 8].map((n) {
              final on = s.agentMaxSteps == n;
              return Expanded(
                child: GestureDetector(
                  onTap: () => st.patch((x) => x.agentMaxSteps = n),
                  child: Container(
                    height: 32,
                    margin: EdgeInsets.only(right: n == 8 ? 0 : 6),
                    decoration: BoxDecoration(
                      color: on ? C.brand : fieldOf(dark),
                      borderRadius: BorderRadius.circular(D.r),
                      border: on ? null : Border.all(color: lineOf(dark)),
                    ),
                    child: Center(
                      child: Text('$n 步',
                          style: TextStyle(
                            fontSize: 11.5,
                            fontWeight: on ? FontWeight.w600 : FontWeight.w400,
                            color: on ? Colors.white : (dark ? C.dInk2 : C.ink2),
                          )),
                    ),
                  ),
                ),
              );
            }).toList(),
          ),
        ]),
        _section(t('独立工作区'), [
          Text(
            ws == null
                ? '工作区准备中…'
                : (ws.root),
            maxLines: 2,
            style: ts(dark, size: 13, height: 1.5),
          ),
          const SizedBox(height: 8),
          Row(
            children: [
              _link('复制路径', Icons.copy_all_outlined, () async {
                if (ws == null) return;
                await Clipboard.setData(ClipboardData(text: ws.root));
                _toast('工作区路径已复制');
              }),
              const SizedBox(width: 14),
              _link('刷新', Icons.refresh_rounded, _refreshAll),
            ],
          ),
          const SizedBox(height: 14),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text('文件 · ${_files.length}',
                  style: ts(dark, size: 13, weight: FontWeight.w600)),
              if (_loading)
                const SizedBox(
                    width: 12, height: 12, child: CircularProgressIndicator(strokeWidth: 2)),
            ],
          ),
          const SizedBox(height: 8),
          if (_files.isEmpty)
            Text(t('暂时是空的。让智能体「把结果保存到 notes/」就会出现在下面。'),
                style: meta(dark, size: 11.5, height: 1.5))
          else
            ..._files.take(10).map((e) => _fileRow(ws, e, restore: false)),
          const SizedBox(height: 12),
          InkWell(
            onTap: () => setState(() => _showTrash = !_showTrash),
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 6),
              child: Row(
                children: [
                  Icon(Icons.delete_outline_rounded,
                      size: 15, color: dark ? C.dInk2 : C.ink2),
                  const SizedBox(width: 8),
                  Text('回收站 · ${_trash.length} 个条目',
                      style: ts(dark, size: 13)),
                  const Spacer(),
                  Icon(_showTrash ? Icons.expand_less_rounded : Icons.expand_more_rounded,
                      size: 17, color: dark ? C.dInk3 : C.ink3),
                ],
              ),
            ),
          ),
          if (_showTrash) ...[
            const SizedBox(height: 6),
            if (_trash.isEmpty)
              Text(t('回收站是空的。'), style: meta(dark, size: 11.5))
            else ...[
              ..._trash.take(8).map((e) => _fileRow(ws, e, restore: true)),
              const SizedBox(height: 8),
              _link('永久清空回收站', Icons.delete_forever_outlined, _confirmClearTrash,
                  danger: true),
            ],
          ],
        ]),
        _section(t('可用工具 · ${kAgentTools.length}'), [
          Text(t('只读工具随时可用；其余按上面的授权分组生效。'),
              style: meta(dark, size: 11.5, height: 1.5)),
          const SizedBox(height: 10),
          ...(_showTools ? kAgentTools : kAgentTools.take(6))
              .map((t) => _toolRow(t, _grantAllows(s, t))),
          const SizedBox(height: 8),
          _link(_showTools ? '收起' : '查看全部 ${kAgentTools.length} 个工具',
              _showTools ? Icons.expand_less_rounded : Icons.expand_more_rounded,
              () => setState(() => _showTools = !_showTools)),
        ]),
        _section(t('执行记录 · ${st.agentLog.length}'), [
          if (st.agentLog.isEmpty)
            Text(t('还没有执行过本机操作。每一步都会留痕，可随时回溯。'),
                style: meta(dark, size: 11.5, height: 1.5))
          else ...[
            ...(_showLog ? st.agentLog.take(30) : st.agentLog.take(5))
                .map(_logRow),
            if (st.agentLog.length > 5) ...[
              const SizedBox(height: 8),
              _link(_showLog ? '只看最近 5 条' : '显示全部',
                  _showLog ? Icons.expand_less_rounded : Icons.expand_more_rounded,
                  () => setState(() => _showLog = !_showLog)),
            ],
          ],
        ]),
      ],
    );
  }

  bool _grantAllows(AppSettings s, AgentTool t) {
    // 与 AppState.agentGrant 保持一致，这里只用于面板上的灰显提示。
    return switch (t.grant) {
      '' => true,
      'workspace' => s.agentAllowWorkspace,
      'external' => s.agentAllowExternal,
      'system' => s.agentAllowSystem,
      'network' => s.agentAllowNetwork,
      _ => false,
    };
  }

  Widget _toolRow(AgentTool t, bool enabled) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(_toolIcon(t),
              size: 15,
              color: enabled
                  ? (dark ? C.dInk2 : C.ink2)
                  : (dark ? C.dInk3 : C.ink3)),
          const SizedBox(width: 9),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(t.name,
                    style: ts(dark,
                        size: 13,
                        weight: FontWeight.w500,
                        color: enabled ? null : (dark ? C.dInk3 : C.ink3))),
                const SizedBox(height: 2),
                Text(t.summary,
                    style: meta(dark,
                        size: 11.5,
                        height: 1.45,
                        color: dark ? C.dInk3 : C.ink3)),
              ],
            ),
          ),
          const SizedBox(width: 8),
          Text(enabled ? t.riskLabel : '未授权',
              style: meta(dark,
                  size: 11.5,
                  color: enabled ? null : C.warn)),
        ],
      ),
    );
  }

  IconData _toolIcon(AgentTool t) {
    if (t.id.startsWith('agent.device')) return Icons.phone_android_outlined;
    if (t.id.startsWith('agent.app')) return Icons.apps_outlined;
    if (t.id.startsWith('agent.workspace')) return Icons.folder_outlined;
    if (t.id.startsWith('agent.web')) return Icons.public_outlined;
    if (t.id == 'agent.calendar.add') return Icons.event_outlined;
    if (t.id == 'agent.alarm.set') return Icons.alarm_outlined;
    if (t.id == 'agent.share.text') return Icons.ios_share_outlined;
    if (t.id == 'agent.clipboard.set') return Icons.content_copy_outlined;
    return Icons.bolt_outlined;
  }

  Widget _fileRow(AgentWorkspace? ws, WorkspaceEntry e, {required bool restore}) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 5),
      child: Row(
        children: [
          Icon(e.isDir ? Icons.folder_outlined : Icons.insert_drive_file_outlined,
              size: 14, color: dark ? C.dInk3 : C.ink3),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(e.name,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: ts(dark, size: 13)),
                Text('${e.sizeLabel} · ${_time(e.modifiedMs)}',
                    style: meta(dark, size: 11.5)),
              ],
            ),
          ),
          if (restore && ws != null)
            InkWell(
              onTap: () async {
                try {
                  await ws.restore(e.name);
                  await _reload();
                  _toast('已恢复到工作区');
                } catch (err) {
                  _toast('恢复失败：$err');
                }
              },
              child: Padding(
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 3),
                child: Text(t('恢复'),
                    style: ts(dark, size: 13, color: accentOf(dark))),
              ),
            ),
        ],
      ),
    );
  }

  Widget _logRow(AgentLogEntry e) {
    final ok = e.ok;
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 5),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Container(
            width: 6,
            height: 6,
            margin: const EdgeInsets.only(top: 5, right: 9),
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: ok ? C.ok : C.warn,
            ),
          ),
          Expanded(
            child: Text('${e.tool} · ${e.detail}',
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
                style: meta(dark, size: 11.5, height: 1.45)),
          ),
          const SizedBox(width: 8),
          Text(_time(e.at), style: meta(dark, size: 11.5)),
        ],
      ),
    );
  }

  Future<void> _confirmClearTrash() async {
    final st = context.read<AppState>();
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(t('永久清空回收站？')),
        content: Text(t('回收站里的备份与被删文件将被真正删除，无法恢复。')),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: Text(t('取消'))),
          TextButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: Text(t('清空'))),
        ],
      ),
    );
    if (ok != true) return;
    final msg = await st.clearAgentTrash();
    await _reload();
    _toast(msg);
  }

  void _toast(String text) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(text), duration: const Duration(seconds: 2)),
    );
  }

  Widget _kv(String label, String value) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 5),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            SizedBox(
                width: 82,
                child: Text(label, style: meta(dark, size: 11.5))),
            Expanded(
                child: Text(value,
                    style: ts(dark, size: 13, height: 1.4))),
          ],
        ),
      );

  Widget _note(String text) => Container(
        padding: const EdgeInsets.fromLTRB(11, 10, 11, 10),
        decoration: BoxDecoration(
          color: fieldOf(dark),
          borderRadius: BorderRadius.circular(D.r),
        ),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Icon(Icons.shield_outlined,
                size: 15, color: dark ? C.dInk2 : C.ink2),
            const SizedBox(width: 9),
            Expanded(
                child: Text(text,
                    style: meta(dark, size: 11.5, height: 1.6))),
          ],
        ),
      );

  Widget _link(String text, IconData icon, VoidCallback onTap,
          {bool danger = false}) =>
      InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(D.r),
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 2),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(icon, size: 14, color: danger ? C.danger : accentOf(dark)),
              const SizedBox(width: 6),
              Text(text,
                  style: ts(dark,
                      size: 13,
                      color: danger ? C.danger : accentOf(dark))),
            ],
          ),
        ),
      );

  // ---------------------------------------------------------- 权限档位

  String _permLabel(int lv) => switch (lv) {
        AppSettings.kPermMinimal => t('少量权限'),
        AppSettings.kPermStandard => t('标准权限'),
        AppSettings.kPermFull => t('完全权限'),
        _ => t('自定义'),
      };

  String _permNote(int lv) => switch (lv) {
        AppSettings.kPermMinimal =>
          t('只读本机信息、已装应用与文件清单；不写任何数据，不调起其它应用。'),
        AppSettings.kPermStandard => t(
            '在少量权限基础上，允许隔离工作区读写与任务脚本、打开应用与网页、分享与剪贴板。'),
        AppSettings.kPermFull => t(
            '开放全部能力：日历与闹钟、网页抓取，以及设备缓存清理与可访问文件删除。'),
        _ => t('已手动调整单项授权，不对应任何预设档位。'),
      };

  Widget _permissionSection(AppSettings s, AppState st) {
    final cur = s.agentPermissionLevel;
    return _section(t('权限档位'), [
      Text(t('一键设定智能体在这台手机上能做什么。档位只改授权范围，危险动作仍会逐条弹确认。'),
          style: sub(dark, size: 12.5)),
      const SizedBox(height: 12),
      Row(
        children: [
          for (final lv in const [
            AppSettings.kPermMinimal,
            AppSettings.kPermStandard,
            AppSettings.kPermFull,
          ]) ...[
            Expanded(child: _permChip(lv, cur, st)),
            if (lv != AppSettings.kPermFull) const SizedBox(width: 8),
          ],
        ],
      ),
      const SizedBox(height: 12),
      _note(_permNote(cur)),
      const SizedBox(height: 8),
      Text('${t('当前')}：${_permLabel(cur)} · ${st.agentGrant.allows('device') ? t('设备清理已开') : t('设备清理未开')}',
          style: meta(dark, size: 11.5)),
    ]);
  }

  Widget _permChip(int lv, int cur, AppState st) {
    final on = lv == cur;
    return GestureDetector(
      onTap: () => st.patch((x) => x.applyPermissionLevel(lv)),
      child: Container(
        height: 38,
        alignment: Alignment.center,
        decoration: BoxDecoration(
          color: on ? C.brand : fieldOf(dark),
          borderRadius: BorderRadius.circular(D.r),
          border: Border.all(color: on ? C.brand : borderOf(dark), width: 0.8),
        ),
        child: Text(_permLabel(lv),
            style: ts(dark,
                size: 12.5,
                weight: FontWeight.w600,
                color: on ? Colors.white : (dark ? C.dInk2 : C.ink2))),
      ),
    );
  }

  Widget _section(String title, List<Widget> children) => Container(
        margin: const EdgeInsets.only(bottom: 16),
        padding: const EdgeInsets.fromLTRB(16, 18, 16, 16),
        decoration: surfaceBox(dark, shadowScale: 0.4),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(title,
                style: ts(dark,
                    size: 14.5, weight: FontWeight.w600, height: 1.3)),
            const SizedBox(height: 14),
            ...children,
          ],
        ),
      );

  String _time(int ms) {
    final d = DateTime.fromMillisecondsSinceEpoch(ms);
    String p(int v) => v.toString().padLeft(2, '0');
    return '${d.month}/${d.day} ${p(d.hour)}:${p(d.minute)}';
  }
}

import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

import '../i18n.dart';
import '../services/price_catalog.dart';
import '../state/app_state.dart';
import '../theme.dart';
import 'widgets.dart';

/// 设置 → 费用与价格：接上接口后按真实 token 算钱，并支持拉取实时公开报价。
class BillingPanel extends StatefulWidget {
  const BillingPanel({super.key, required this.dark});

  final bool dark;

  @override
  State<BillingPanel> createState() => _BillingPanelState();
}

class _BillingPanelState extends State<BillingPanel> {
  bool _busy = false;
  String _msg = '';

  bool get dark => widget.dark;

  Future<void> _refresh() async {
    setState(() {
      _busy = true;
      _msg = '';
    });
    final st = context.read<AppState>();
    String m;
    try {
      m = await st.refreshPrices();
    } catch (e) {
      m = '${t('拉取失败')}：$e';
    }
    if (mounted) {
      setState(() {
        _busy = false;
        _msg = m;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    final st = context.watch<AppState>();
    final s = st.settings;
    final stats = st.tokenStats;
    final total = st.totalCost;
    final today = st.todayCost;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _sec(t('花了多少钱'), [
          Row(
            crossAxisAlignment: CrossAxisAlignment.baseline,
            textBaseline: TextBaseline.alphabetic,
            children: [
              Text(total == null ? '—' : '¥ ${total.toStringAsFixed(4)}',
                  style: display(dark, size: 32)),
              const SizedBox(width: 8),
              Text(t('累计估算'), style: meta(dark, size: 11.5)),
            ],
          ),
          const SizedBox(height: 12),
          Row(
            children: [
              Expanded(
                  child: _stat(t('今日'),
                      today == null ? '—' : '¥ ${today.toStringAsFixed(4)}')),
              const SizedBox(width: 8),
              Expanded(child: _stat(t('请求次数'), '${stats.requests}')),
              const SizedBox(width: 8),
              Expanded(
                  child: _stat(t('缓存省下'),
                      st.cacheSaving > 0
                          ? '¥ ${st.cacheSaving.toStringAsFixed(3)}'
                          : '—')),
            ],
          ),
          const SizedBox(height: 10),
          Text(t('费用 = 网关返回的真实 token 数 × 单价。网关没返回 usage 时按字符估算，会略偏。这里只做本地自查，正式账单以服务商后台为准。'),
              style: meta(dark, size: 11.5, height: 1.55)),
        ]),

        _sec(t('实时价格'), [
          SwitchRow(
            title: t('自动获取实时价格'),
            subtitle: t('启动后在后台拉取公开费率表，按当前模型自动匹配单价；用量数据不会上传。'),
            value: s.priceAuto,
            icon: Icons.price_change_outlined,
            onChanged: (v) => st.patch((x) => x.priceAuto = v),
          ),
          const SizedBox(height: 12),
          GestureDetector(
            onTap: _busy ? null : _refresh,
            child: Container(
              height: 40,
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: _busy ? fieldOf(dark) : C.brand,
                borderRadius: BorderRadius.circular(D.r),
              ),
              child: _busy
                  ? const SizedBox(
                      width: 18,
                      height: 18,
                      child: CircularProgressIndicator(
                          strokeWidth: 2, color: Colors.white))
                  : Text(t('刷新实时价格'),
                      style: ts(dark,
                          size: 13,
                          weight: FontWeight.w600,
                          color: Colors.white)),
            ),
          ),
          if (_msg.isNotEmpty) ...[
            const SizedBox(height: 10),
            Text(_msg, style: sub(dark, size: 12)),
          ],
          const SizedBox(height: 12),
          _kv(t('价格来源'), s.priceSource.isEmpty ? t('尚未获取') : s.priceSource),
          _kv(t('匹配模型'),
              s.priceMatchedModel.isEmpty ? t('未匹配') : s.priceMatchedModel),
          _kv(t('更新时间'), s.priceUpdatedAt == 0 ? '—' : _time(s.priceUpdatedAt)),
          const SizedBox(height: 6),
          _note(t('OpenAI / Anthropic 等官方接口没有「按次返回单价」的公开端点，账单查询需要单独的 Admin Key，客户端不该持有。因此这里从 LiteLLM / OpenRouter 的公开费率表取价，再乘以本地已记录的真实 token 数。')),
        ]),

        _sec(t('单价与汇率'), [
          _row(t('输入单价'), '¥ ${s.priceInPerM.toStringAsFixed(2)} / ${t('百万')}',
              () => _edit(t('输入单价'), s.priceInPerM,
                  (v) => st.patch((x) => x.priceInPerM = v))),
          _row(t('输出单价'), '¥ ${s.priceOutPerM.toStringAsFixed(2)} / ${t('百万')}',
              () => _edit(t('输出单价'), s.priceOutPerM,
                  (v) => st.patch((x) => x.priceOutPerM = v))),
          _row(t('美元汇率'), '1 USD = ¥ ${s.usdToCny.toStringAsFixed(2)}',
              () => _edit(t('美元汇率'), s.usdToCny,
                  (v) => st.patch((x) => x.usdToCny = v.clamp(0.1, 100)))),
          const SizedBox(height: 6),
          Text(t('单价填 0 表示不计算费用；手填单价不会被实时价格覆盖，除非主动刷新。'),
              style: meta(dark, size: 11.5, height: 1.5)),
        ]),

        if (stats.byModel.isNotEmpty)
          _sec(t('按模型花费'), [
            ...stats.byModel.entries.map((e) {
              final p = st.priceFor(e.key);
              final c = PriceCatalog.costOf(
                prompt: e.value.prompt,
                completion: e.value.completion,
                inputPerM: p.input,
                outputPerM: p.output,
                cachedTokens: e.value.cached.toDouble(),
                cachedPerM: p.cached,
              );
              return Padding(
                padding: const EdgeInsets.symmetric(vertical: 7),
                child: Row(
                  children: [
                    Expanded(
                      child: Text(e.key.isEmpty ? t('未指定模型') : e.key,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: ts(dark, size: 12.5)),
                    ),
                    const SizedBox(width: 8),
                    Text('¥ ${c.toStringAsFixed(4)}',
                        style: ts(dark, size: 12.5, weight: FontWeight.w600)),
                  ],
                ),
              );
            }),
          ]),

        if (stats.days.isNotEmpty)
          _sec(t('按天花费'), [
            ...stats.days.reversed.take(7).map((k) {
              final d = stats.day(k);
              final c = PriceCatalog.costOf(
                prompt: d.prompt,
                completion: d.completion,
                inputPerM: s.priceInPerM,
                outputPerM: s.priceOutPerM,
                cachedTokens: d.cached.toDouble(),
                cachedPerM: s.priceInPerM * 0.5,
              );
              return Padding(
                padding: const EdgeInsets.symmetric(vertical: 6),
                child: Row(
                  children: [
                    Expanded(
                        child: Text(_day(k), style: ts(dark, size: 12.5))),
                    Text('${_compact(d.total)} tok',
                        style: meta(dark, size: 11)),
                    const SizedBox(width: 12),
                    Text('¥ ${c.toStringAsFixed(4)}',
                        style: ts(dark, size: 12.5, weight: FontWeight.w600)),
                  ],
                ),
              );
            }),
          ]),
      ],
    );
  }

  Future<void> _edit(String title, double current,
      void Function(double value) onSave) async {
    final ctrl = TextEditingController(
        text: current == 0 ? '' : current.toStringAsFixed(2));
    final v = await showDialog<double>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(title),
        content: TextField(
          controller: ctrl,
          autofocus: true,
          keyboardType: const TextInputType.numberWithOptions(decimal: true),
          decoration: InputDecoration(
            hintText: t('填 0 表示不计算'),
            isDense: true,
            border: const OutlineInputBorder(),
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx), child: Text(t('取消'))),
          TextButton(
            onPressed: () => Navigator.pop(
                ctx, double.tryParse(ctrl.text.trim()) ?? 0),
            child: Text(t('保存')),
          ),
        ],
      ),
    );
    ctrl.dispose();
    if (v != null) onSave(v < 0 ? 0 : v);
  }

  Widget _row(String label, String value, VoidCallback onTap) => GestureDetector(
        onTap: onTap,
        behavior: HitTestBehavior.opaque,
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 9),
          child: Row(
            children: [
              Expanded(child: Text(label, style: ts(dark, size: 13))),
              Text(value, style: sub(dark, size: 12)),
              const SizedBox(width: 6),
              Icon(Icons.chevron_right_rounded,
                  size: 16, color: dark ? C.dInk3 : C.ink3),
            ],
          ),
        ),
      );

  Widget _kv(String label, String value) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 3),
        child: Row(
          children: [
            SizedBox(width: 72, child: Text(label, style: meta(dark, size: 11.5))),
            Expanded(child: Text(value, style: ts(dark, size: 12))),
          ],
        ),
      );

  Widget _note(String text) => Container(
        padding: const EdgeInsets.all(11),
        decoration: BoxDecoration(
          color: sinkOf(dark),
          borderRadius: BorderRadius.circular(D.r),
        ),
        child: Text(text, style: meta(dark, size: 11.5, height: 1.55)),
      );

  String _time(int ms) {
    final d = DateTime.fromMillisecondsSinceEpoch(ms);
    String p(int v) => v.toString().padLeft(2, '0');
    return '${d.year}/${p(d.month)}/${p(d.day)} ${p(d.hour)}:${p(d.minute)}';
  }

  String _day(int k) {
    final s = k.toString();
    return s.length == 8
        ? '${s.substring(0, 4)}/${s.substring(4, 6)}/${s.substring(6, 8)}'
        : s;
  }

  static String _compact(int v) {
    if (v < 10000) return '$v';
    if (v < 1000000) return '${(v / 1000).toStringAsFixed(1)}k';
    return '${(v / 1000000).toStringAsFixed(2)}M';
  }

  Widget _stat(String label, String value) => Container(
        padding: const EdgeInsets.fromLTRB(10, 10, 10, 11),
        decoration: BoxDecoration(
          color: fieldOf(dark),
          borderRadius: BorderRadius.circular(D.r),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(label, style: meta(dark, size: 10.5)),
            const SizedBox(height: 4),
            Text(value,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: ts(dark, size: 14, weight: FontWeight.w600)),
          ],
        ),
      );

  Widget _sec(String title, List<Widget> children) => Container(
        margin: const EdgeInsets.only(bottom: 16),
        padding: const EdgeInsets.fromLTRB(16, 18, 16, 16),
        decoration: surfaceBox(dark, shadowScale: 0.4),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(title,
                style: ts(dark, size: 14.5, weight: FontWeight.w600)),
            const SizedBox(height: 14),
            ...children,
          ],
        ),
      );
}

import 'package:flutter/material.dart';

import '../services/model_brand.dart';
import '../theme.dart';

/// 模型列表里的官方品牌图标。
///
/// 一律用内置的 256px 彩色 PNG（见 `tool/build_brand_icons.py`），
/// 统一放在近白色圆角方块里：黑色系官方 logo 在深浅主题下都看得清，
/// 彩色 logo 也不会被背景吃掉，整列风格完全一致。
class BrandIcon extends StatelessWidget {
  final ModelBrand brand;
  final double size;
  final bool dark;

  const BrandIcon({
    super.key,
    required this.brand,
    required this.dark,
    this.size = 38,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        color: dark ? const Color(0xFFF1F2F5) : Colors.white,
        borderRadius: BorderRadius.circular(size * 0.27),
        border: Border.all(
          color: dark ? const Color(0xFF3A3A40) : C.line,
          width: 0.8,
        ),
      ),
      padding: EdgeInsets.all(size * 0.17),
      child: Image.asset(
        brand.asset,
        filterQuality: FilterQuality.high,
        errorBuilder: (_, __, ___) => Icon(
          Icons.smart_toy_outlined,
          size: size * 0.48,
          color: dark ? C.dInk2 : C.ink2,
        ),
      ),
    );
  }
}

/// 通用模型行：**官方图标 + 大字模型名 + 小字供应商**。
///
/// 弹层、设置页、搜索结果三处共用同一个组件，避免三种长得不一样的列表。
/// 只有选中态会多一个对勾，不再堆「视觉 / 推理 / 选用 / 切换连接」一串标签。
class BrandModelTile extends StatelessWidget {
  final String modelId;
  final String subtitle;
  final bool selected;
  final bool dark;
  final VoidCallback onTap;
  final double iconSize;

  /// 可选的能力后缀，会并在副标题末尾（如「· 视觉」），不另起标签。
  final String? capability;

  /// v4.13：单行紧凑版——只留「图标 + 模型名」，行更高、字号更大、
  /// 没有分隔线也没有选中底色，用在对「简洁」要求最高的换模型弹层里。
  final bool compact;

  const BrandModelTile({
    super.key,
    required this.modelId,
    required this.subtitle,
    required this.selected,
    required this.dark,
    required this.onTap,
    this.iconSize = 38,
    this.capability,
    this.compact = false,
  });

  @override
  Widget build(BuildContext context) {
    final accent = accentOf(dark);
    final brand = resolveModelBrand(modelId);
    if (compact) return _compactTile(accent, brand);
    final sub = capability == null || capability!.isEmpty
        ? subtitle
        : (subtitle.isEmpty ? capability! : '$subtitle · $capability');
    return InkWell(
      onTap: onTap,
      child: Container(
        constraints: const BoxConstraints(minHeight: 58),
        padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 8),
        decoration: BoxDecoration(
          color: selected ? accent.withOpacity(dark ? 0.12 : 0.06) : null,
          border: Border(bottom: BorderSide(color: hairOf(dark), width: 1)),
        ),
        child: Row(
          children: [
            BrandIcon(brand: brand, size: iconSize, dark: dark),
            const SizedBox(width: 12),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Text(
                    modelId,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: ts(dark,
                        size: 13.5,
                        weight: selected ? FontWeight.w700 : FontWeight.w600),
                  ),
                  const SizedBox(height: 3),
                  Text(
                    sub.isEmpty ? brand.label : sub,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: meta(dark, size: 11.5),
                  ),
                ],
              ),
            ),
            if (selected) ...[
              const SizedBox(width: 8),
              Icon(Icons.check_circle_rounded, size: 18, color: accent),
            ],
          ],
        ),
      ),
    );
  }

  /// 单行：图标 + 15px 模型名 + 选中对勾，四周留白，无分隔线。
  Widget _compactTile(Color accent, ModelBrand brand) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(12),
      child: Padding(
        padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 11),
        child: Row(
          children: [
            BrandIcon(brand: brand, size: iconSize, dark: dark),
            const SizedBox(width: 13),
            Expanded(
              child: Text(
                modelId,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: TextStyle(
                  fontSize: 15,
                  height: 1.25,
                  letterSpacing: -0.1,
                  fontWeight:
                      selected ? FontWeight.w600 : FontWeight.w500,
                  color: dark ? C.dInk : C.ink,
                ),
              ),
            ),
            if (selected) ...[
              const SizedBox(width: 10),
              Icon(Icons.check_rounded, size: 20, color: accent),
            ],
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:provider/provider.dart';

import '../i18n.dart';
import '../services/cache_store.dart';
import '../state/app_state.dart';
import '../theme.dart';
import 'widgets.dart';

/// 设置 → 缓存命中：既能看统计，也能改开关、清缓存。
///
/// 数据来自两个真实来源，不会凭空造数字：
/// - 服务端提示词缓存命中（网关 usage 里的 cached_tokens）；
/// - 本地响应复用（完全相同的非流式请求直接返回上次回答）。
class CachePanel extends StatelessWidget {
  const CachePanel({super.key, required this.dark});

  final bool dark;

  @override
  Widget build(BuildContext context) {
    final st = context.watch<AppState>();
    final l = st.cacheLedger;
    final saving = st.cacheSaving;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _sec(t('命中概览'), [
          Row(
            children: [
              Expanded(child: _stat(t('命中次数'), '${l.hits}')),
              const SizedBox(width: 8),
              Expanded(child: _stat(t('缓存 token'), _compact(l.tokens))),
            ],
          ),
          const SizedBox(height: 8),
          Row(
            children: [
              Expanded(
                  child: _stat(t('估算省下'),
                      saving > 0 ? '¥ ${saving.toStringAsFixed(3)}' : '—')),
              const SizedBox(width: 8),
              Expanded(child: _stat(t('缓存条目'), '${st.responseCache.size}')),
            ],
          ),
          const SizedBox(height: 12),
          Text(
            '${t('服务端缓存命中')} ${l.promptHits} ${t('次')} · '
            '${_compact(l.promptTokens)} tok　|　'
            '${t('本地复用')} ${l.responseHits} ${t('次')} · '
            '${_compact(l.responseTokens)} tok',
            style: meta(dark, size: 11.5, height: 1.5),
          ),
        ]),

        _sec(t('缓存设置'), [
          SwitchRow(
            title: t('复用相同请求的回答'),
            subtitle: t('圆桌会议、模拟人生、小游戏与深度研究里完全相同的请求，6 小时内直接复用上次结果，不再发起请求也不计费。主对话是流式的，永远拿新回答。'),
            value: st.settings.responseCacheEnabled,
            icon: Icons.cached_rounded,
            onChanged: (v) => st.patch((x) => x.responseCacheEnabled = v),
          ),
          const SizedBox(height: 8),
          _note(t('两种命中都会被记录：服务端返回的提示词缓存 token 只按折扣计价；本地复用则连请求都不发。省钱金额按你当前填写的输入单价估算，不是账单。')),
        ]),

        _sec(t('最近命中'), [
          if (l.records.isEmpty)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 10),
              child: Text(t('还没有命中记录。用一会儿圆桌会议或小游戏，这里就会有数据。'),
                  style: sub(dark, size: 12.5)),
            )
          else
            ...l.records.take(30).map((e) => _record(e)),
          if (l.records.length > 30)
            Padding(
              padding: const EdgeInsets.only(top: 10),
              child: Text('${t('仅显示最近 30 条')} · ${t('共')} ${l.records.length} ${t('条')}',
                  style: meta(dark, size: 11)),
            ),
        ]),

        _sec(t('管理'), [
          Row(
            children: [
              Expanded(
                child: _btn(t('清空命中记录'), () => _confirmClear(
                      context,
                      t('清空命中记录？'),
                      t('只清统计与列表，不影响已缓存的回答。'),
                      st.clearCacheRecords,
                    )),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: _btn(t('清空响应缓存'), () => _confirmClear(
                      context,
                      t('清空响应缓存？'),
                      t('之后相同的请求会重新发起，直到再次被缓存。'),
                      st.clearResponseCache,
                    ), danger: true),
              ),
            ],
          ),
        ]),
      ],
    );
  }

  Future<void> _confirmClear(BuildContext context, String title, String body,
      Future<void> Function() run) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(title),
        content: Text(body),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: Text(t('取消'))),
          TextButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: Text(t('清空'))),
        ],
      ),
    );
    if (ok == true) await run();
  }

  Widget _record(CacheHitEntry e) {
    final local = e.kind == CacheHitKind.response;
    final d = DateTime.fromMillisecondsSinceEpoch(e.at);
    String p(int v) => v.toString().padLeft(2, '0');
    final time = '${d.month}/${d.day} ${p(d.hour)}:${p(d.minute)}';
    return Container(
      padding: const EdgeInsets.symmetric(vertical: 9),
      decoration: BoxDecoration(
        border: Border(bottom: BorderSide(color: lineOf(dark), width: 0.6)),
      ),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
            decoration: BoxDecoration(
              color: (local ? C.ok : C.brand).withOpacity(0.12),
              borderRadius: BorderRadius.circular(5),
            ),
            child: Text(local ? t('本地复用') : t('服务端缓存'),
                style: ts(dark, size: 10, weight: FontWeight.w600,
                    color: local ? C.ok : accentOf(dark))),
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(e.summary.isEmpty ? e.model : e.summary,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: ts(dark, size: 12.5)),
                const SizedBox(height: 2),
                Text('$time · ${e.model} · ${_compact(e.tokens)} tok',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: meta(dark, size: 10.5)),
              ],
            ),
          ),
        ],
      ),
    );
  }

  static String _compact(int v) {
    if (v < 10000) return '$v';
    if (v < 1000000) return '${(v / 1000).toStringAsFixed(1)}k';
    return '${(v / 1000000).toStringAsFixed(2)}M';
  }

  Widget _stat(String label, String value) => Container(
        padding: const EdgeInsets.fromLTRB(12, 11, 12, 12),
        decoration: BoxDecoration(
          color: fieldOf(dark),
          borderRadius: BorderRadius.circular(D.r),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(label, style: meta(dark, size: 11)),
            const SizedBox(height: 4),
            Text(value,
                style: ts(dark, size: 18, weight: FontWeight.w600)),
          ],
        ),
      );

  Widget _note(String text) => Container(
        padding: const EdgeInsets.all(11),
        decoration: BoxDecoration(
          color: sinkOf(dark),
          borderRadius: BorderRadius.circular(D.r),
        ),
        child: Text(text, style: meta(dark, size: 11.5, height: 1.55)),
      );

  Widget _btn(String label, VoidCallback onTap, {bool danger = false}) =>
      GestureDetector(
        onTap: onTap,
        child: Container(
          height: 38,
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: fieldOf(dark),
            borderRadius: BorderRadius.circular(D.r),
            border: Border.all(color: borderOf(dark), width: 0.8),
          ),
          child: Text(label,
              style: ts(dark,
                  size: 12.5,
                  weight: FontWeight.w600,
                  color: danger ? C.warn : accentOf(dark))),
        ),
      );

  Widget _sec(String title, List<Widget> children) => Container(
        margin: const EdgeInsets.only(bottom: 16),
        padding: const EdgeInsets.fromLTRB(16, 18, 16, 16),
        decoration: surfaceBox(dark, shadowScale: 0.4),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(title,
                style: ts(dark, size: 14.5, weight: FontWeight.w600)),
            const SizedBox(height: 14),
            ...children,
          ],
        ),
      );
}

