/// 20 根柱子的音量波形：静音时是一条细线，说话时按音量起伏。
class MuseWaveform extends StatelessWidget {
  final double level;
  final Color color;
  final bool active;

  const MuseWaveform({
    super.key,
    required this.level,
    required this.color,
    this.active = true,
  });

  @override
  Widget build(BuildContext context) {
    return CustomPaint(
      painter: _WavePainter(level: level, color: color, active: active),
      size: Size.infinite,
    );
  }
}

class _WavePainter extends CustomPainter {
  final double level;
  final Color color;
  final bool active;

  _WavePainter(
      {required this.level, required this.color, required this.active});

  @override
  void paint(Canvas canvas, Size size) {
    const bars = 21;
    final gap = size.width / bars;
    final w = gap * 0.42;
    final mid = size.height / 2;
    final paint = Paint()
      ..color = color.withOpacity(active ? 0.9 : 0.4)
      ..strokeCap = StrokeCap.round
      ..strokeWidth = w;
    for (var i = 0; i < bars; i++) {
      // 中间高、两端低的包络，再叠加实时音量。
      final envelope = 1 - ((i - (bars - 1) / 2).abs() / ((bars - 1) / 2));
      const double floor = 3;
      final h = floor +
          (size.height - floor) *
              (0.16 + 0.72 * envelope) *
              (0.35 + 0.65 * level);
      final x = gap * (i + 0.5);
      canvas.drawLine(Offset(x, mid - h / 2), Offset(x, mid + h / 2), paint);
    }
  }

  @override
  bool shouldRepaint(covariant _WavePainter old) =>
      old.level != level || old.color != color || old.active != active;
}

