  @override
  Widget build(BuildContext context) {
    final dark = widget.dark;
    final g = widget.group;
    final models = filterModels(g.models, _q.text);
    return Scaffold(
      backgroundColor: canvasOf(dark),
      appBar: featureAppBar(context, dark, title: g.name),
      body: GestureDetector(
        onTap: () => FocusScope.of(context).unfocus(),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(14, 10, 14, 4),
                child: TextField(
                  controller: _q,
                  style: ts(dark, size: 13),
                  decoration: fieldDecoration(
                    dark,
                    hint: t('搜索模型 ID'),
                    prefix: Icon(Icons.search_rounded,
                        size: 17, color: dark ? C.dInk3 : C.ink3),
                  ),
                ),
              ),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
                child: Align(
                  alignment: Alignment.centerLeft,
                  child: Text(g.host, style: meta(dark, size: 11)),
                ),
              ),
              Expanded(
                child: models.isEmpty
                    ? featureEmpty(
                        dark,
                        Icons.search_off_rounded,
                        _q.text.trim().isEmpty
                            ? t('这个连接还没有缓存模型，可在下方手动输入。')
                            : t('没有匹配的模型'))
                    : ListView.builder(
                        padding: const EdgeInsets.fromLTRB(14, 4, 14, 12),
                        itemCount: models.length,
                        itemBuilder: (_, i) => BrandModelTile(
                          modelId: models[i],
                          subtitle: g.name,
                          selected: models[i] == widget.currentModel,
                          dark: dark,
                          iconSize: 32,
                          onTap: () => Navigator.of(context).pop(_choice(models[i])),
                        ),
                      ),
              ),
              Container(
                padding: const EdgeInsets.fromLTRB(14, 10, 14, 16),
                decoration: hairlineBox(dark, top: true),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(t('手动输入模型 ID'), style: sectionTitle(dark)),
                    const SizedBox(height: 7),
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: _manual,
                            style: ts(dark, size: 12.5),
                            decoration:
                                fieldDecoration(dark, hint: t('模型 ID')),
                            onSubmitted: (_) => _useManual(),
                          ),
                        ),
                        const SizedBox(width: 8),
                        FilledButton(
                          style: FilledButton.styleFrom(
                            backgroundColor: C.brand,
                            shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(D.r)),
                            elevation: 0,
                          ),
                          onPressed: _useManual,
                          child: Text(t('使用'),
                              style: const TextStyle(
                                  fontSize: 12.5, color: Colors.white)),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  void _useManual() {
    final m = _manual.text.trim();
    if (m.isEmpty) return;
    Navigator.of(context).pop(_choice(m));
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:url_launcher/url_launcher.dart';

import '../services/project_search.dart';
import '../services/relay_catalog.dart';
import '../i18n.dart';
import '../theme.dart';

/// 设置 → 网页版反代。
///
/// 四件事：扫一台主机上正在跑的兼容服务；从内置项目里挑一个接入；
/// 一键测公共实例；用 GitHub 搜目录里没有的项目。
class RelayPanel extends StatefulWidget {
  final bool dark;
  final String currentBaseUrl;
  final Future<void> Function(
    RelayPreset preset,
    String baseUrl,
    String key,
    String model,
  ) onAdd;

  const RelayPanel({
    super.key,
    required this.dark,
    required this.currentBaseUrl,
    required this.onAdd,
  });

  @override
  State<RelayPanel> createState() => _RelayPanelState();
}

class _RelayPanelState extends State<RelayPanel> {
  late final TextEditingController _host;
  late final TextEditingController _query;
  bool _scanning = false;
  double _progress = 0;
  List<RelayHit>? _hits;
  String _filter = '全部';

  // 公共实例的一键测试结果，key 是 preset.id。
  Map<String, RelayHit?> _pubHits = {};
  bool _pubTesting = false;

  // 全网搜索。
  bool _searching = false;
  List<RepoResult>? _repos;
  String _repoQuery = '';
  String _repoError = '';

  @override
  void initState() {
    super.initState();
    _host = TextEditingController(
        text: RelayProbe.guessHost(widget.currentBaseUrl));
    _query = TextEditingController();
  }

  @override
  void dispose() {
    _host.dispose();
    _query.dispose();
    super.dispose();
  }

  bool get _dark => widget.dark;

  void _snack(String s) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(s), duration: const Duration(seconds: 2)),
    );
  }

  Future<void> _scan() async {
    if (_scanning) return;
    final raw = _host.text.trim();
    if (raw.isEmpty) {
      _snack(t('先填主机地址'));
      return;
    }
    FocusScope.of(context).unfocus();
    setState(() {
      _scanning = true;
      _progress = 0;
      _hits = null;
    });
    final hits = await RelayProbe.scan(
      host: raw,
      onProgress: (v) {
        if (mounted) setState(() => _progress = v);
      },
    );
    if (!mounted) return;
    setState(() {
      _scanning = false;
      _progress = 1;
      _hits = hits;
    });
    if (hits.isEmpty) _snack(t('没有发现服务，检查反代是否已启动'));
  }

  /// 一键测试所有公共实例：只测写死的地址，不扫端口。
  Future<void> _testPublic() async {
    if (_pubTesting) return;
    final list = kRelayPresets.where((p) => p.isPublicInstance).toList();
    setState(() {
      _pubTesting = true;
      _pubHits = {};
    });
    final hits = await RelayProbe.probeAll(list);
    if (!mounted) return;
    setState(() {
      _pubTesting = false;
      _pubHits = hits;
    });
    final alive = hits.values.where((h) => h != null).length;
    _snack(alive == 0 ? '没有一个连得上，公共站换域名很常见' : '$alive / ${list.length} 个在线');
  }

  /// 全网搜索：直接查 GitHub，不限内置目录。
  Future<void> _searchWeb(String query) async {
    final q = query.trim();
    if (q.isEmpty || _searching) return;
    FocusScope.of(context).unfocus();
    setState(() {
      _searching = true;
      _repoError = '';
      _repoQuery = q;
      _repos = null;
    });
    try {
      final list = await ProjectSearch.search(q);
      if (!mounted) return;
      setState(() {
        _searching = false;
        _repos = list;
        if (list.isEmpty) _repoError = '没搜到，换个词试试';
      });
    } on ProjectSearchException catch (e) {
      if (!mounted) return;
      setState(() {
        _searching = false;
        _repoError = e.message;
      });
    }
  }

  Future<void> _openUrl(String url) async {
    if (url.isEmpty) return;
    final ok =
        await launchUrl(Uri.parse(url), mode: LaunchMode.externalApplication);
    if (!ok) {
      Clipboard.setData(ClipboardData(text: url));
      _snack(t('打不开浏览器，链接已复制'));
    }
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _scanCard(),
        const SizedBox(height: 18),
        _presetCard(),
      ],
    );
  }

  // ------------------------------------------------------------ 扫描

  Widget _scanCard() {
    final dark = _dark;
    final hits = _hits;
    return Container(
      padding: const EdgeInsets.fromLTRB(16, 17, 16, 16),
      decoration: surfaceBox(dark, shadowScale: 0.6),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Container(
                width: 3,
                height: 11,
                decoration: BoxDecoration(
                  color: accentOf(dark),
                  borderRadius: BorderRadius.circular(2),
                ),
              ),
              const SizedBox(width: 8),
              Text(t('扫描已运行的服务'), style: sectionTitle(dark)),
              const Spacer(),
              if (hits != null)
                Text('${hits.length} 个', style: meta(dark, size: 11.5)),
            ],
          ),
          const SizedBox(height: 12),
          Text(t('反代一般跑在电脑或路由器上。手机和它连同一个 Wi-Fi，填电脑的内网 IP（如 192.168.1.5），点扫描会自动试常见端口。'),
            style: meta(dark, size: 11.5, color: dark ? C.dInk2 : C.ink2),
          ),
          const SizedBox(height: 12),
          Row(
            children: [
              Expanded(
                child: TextField(
                  controller: _host,
                  maxLines: 1,
                  style: ts(dark, size: 13.5),
                  textInputAction: TextInputAction.search,
                  onSubmitted: (_) => _scan(),
                  decoration:
                      fieldDecoration(dark, hint: t('127.0.0.1 或 192.168.1.5')),
                ),
              ),
              const SizedBox(width: 10),
              _primary('扫描', busy: _scanning, onTap: _scan),
            ],
          ),
          if (_scanning) ...[
            const SizedBox(height: 14),
            ClipRRect(
              borderRadius: BorderRadius.circular(2),
              child: LinearProgressIndicator(
                value: _progress == 0 ? null : _progress,
                minHeight: 2.5,
                backgroundColor: fieldOf(dark),
                valueColor: AlwaysStoppedAnimation(accentOf(dark)),
              ),
            ),
            const SizedBox(height: 8),
            Text('已试 ${(_progress * 100).round()}% · 端口多的机器要几秒',
                style: meta(dark, size: 11.5)),
          ],
          if (hits != null) ...[
            const SizedBox(height: 14),
            if (hits.isEmpty)
              _emptyScan()
            else
              for (var i = 0; i < hits.length; i++) ...[
                if (i > 0) Divider(height: 1, color: hairOf(dark)),
                _hitRow(hits[i]),
              ],
          ],
        ],
      ),
    );
  }

  Widget _emptyScan() {
    final dark = _dark;
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.fromLTRB(13, 12, 13, 12),
      decoration: insetBox(dark),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(t('这台主机上没有发现兼容端点。'), style: ts(dark, size: 13)),
          const SizedBox(height: 5),
          Text(t('依次确认：服务已启动、端口对得上、防火墙放行该端口、手机没有连到访客网络。'),
            style: meta(dark, size: 11.5, height: 1.6),
          ),
        ],
      ),
    );
  }

  Widget _hitRow(RelayHit h) {
    final dark = _dark;
    final tint = h.ok ? C.ok : C.warn;
    return InkWell(
      onTap: () => _useHit(h),
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 11),
        child: Row(
          children: [
            Container(
              width: 6,
              height: 6,
              decoration: BoxDecoration(color: tint, shape: BoxShape.circle),
            ),
            const SizedBox(width: 10),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(h.title, style: ts(dark, size: 13)),
                  const SizedBox(height: 3),
                  Text(
                    '${h.host}:${h.port} · ${h.latencyMs}ms'
                    '${h.models.isEmpty ? '' : ' · ${h.models.length} 个模型'}'
                    '${h.needsKey ? ' · 需要密钥' : ''}',
                    style: meta(dark, size: 11.5),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                  ),
                ],
              ),
            ),
            const SizedBox(width: 8),
            Text(t('接入'),
                style: ts(dark,
                    size: 13,
                    weight: FontWeight.w600,
                    color: accentOf(dark))),
          ],
        ),
      ),
    );
  }

  Future<void> _useHit(RelayHit h) async {
    final preset = h.preset ??
        RelayPreset(
          id: 'scan_${h.port}',
          name: h.models.isNotEmpty ? h.models.first : '本机服务',
          owner: '${h.host}:${h.port}',
          summary: '扫描发现的服务',
          deploy: '',
          port: h.port,
          path: '/v1',
          auth: RelayAuth.optional,
          models: h.models.take(6).toList(),
        );
    await _openSheet(preset, presetBase: h.baseUrl, presetModels: h.models);
  }

