                }),
            ],
          ),
          if (list.isEmpty)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 18),
              child:
                  Text(t('没有匹配的项目，换个关键词或点「全部」。'), style: meta(dark, size: 11.5)),
