/// 20261108 → 11-08；跨年的历史带上年份，避免同一天两个「11-08」。
String _dayLabel(int key) {
  final y = key ~/ 10000;
  final m = (key ~/ 100) % 100;
  final d = key % 100;
  final mm = m.toString().padLeft(2, '0');
  final dd = d.toString().padLeft(2, '0');
  return y == DateTime.now().year ? '$mm-$dd' : '${y % 100}-$mm-$dd';
}

