              itemBuilder: (_, i) {
                if (i == s.personas.length) {
                  return GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTap: () {
                      st.addPersona('新形象');
                      _setState(() {});
                      _toast('已创建，可在下方编辑');
                    },
                    child: SizedBox(
                      width: 58,
                      child: Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          Container(
                            width: 46,
                            height: 46,
                            decoration: BoxDecoration(
                              shape: BoxShape.circle,
                              border: Border.all(color: borderOf(dark)),
                            ),
                            child: Icon(Icons.add_rounded,
                                size: 20, color: accentOf(dark)),
                          ),
                          const SizedBox(height: 6),
                          Text(t('新建'),
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: meta(dark, size: 11.5)),
                        ],
                      ),
                    ),
                  );
                }
                final p = s.personas[i];
                final on = p.id == s.activePersonaId;
                return GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: () {
                    st.setActivePersona(p.id);
                    _setState(() {});
                  },
                  child: SizedBox(
                    width: 58,
                    child: Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        Container(
                          padding: const EdgeInsets.all(2),
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            border: on
                                ? Border.all(color: accentOf(dark), width: 1.6)
                                : null,
                          ),
                          child: PersonaAvatar(
                              persona: p, size: 42, dark: dark, ring: false),
                        ),
                        const SizedBox(height: 6),
                        Text(
                          p.name,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: meta(dark,
                              size: 11.5, color: on ? accentOf(dark) : null),
                        ),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
          const SizedBox(height: 12),
          Row(
            children: [
              Expanded(
                child:
                    Text('当前默认：${current.name}', style: meta(dark, size: 11.5)),
              ),
              if (!current.builtin)
                GestureDetector(
                  behavior: HitTestBehavior.opaque,
                  onTap: () async {
                    final ok = await showDialog<bool>(
                      context: context,
                      builder: (ctx) => AlertDialog(
                        title: Text(t('删除形象')),
                        content: Text('将删除「${current.name}」，引用它的工作台会回落到全局默认。'),
                        actions: [
                          TextButton(
                              onPressed: () => Navigator.pop(ctx, false),
