              st.apply((x) => x.ttsVoice = v);
            }),
          ],
          const SizedBox(height: 16),
          _label(dark, '语速'),
          Row(
            children: [
              Expanded(
                child: SliderTheme(
                  data: SliderTheme.of(context).copyWith(
