          ],
          const SizedBox(height: 10),
          Text(tts.note, style: meta(dark, size: 11.5, height: 1.7)),
        ]),
        _card(dark, t('语音输入'), t('说完静音自动停止，识别出的句子放进输入框；确认没识别错，再点发送。'), [
          _switch(
            dark,
