                  Icon(Icons.chevron_right_rounded,
                      size: 18, color: dark ? C.dInk3 : C.ink3),
                ],
              ),
            ),
          ),
          const SizedBox(height: 14),
          _label(dark, '说完多久收尾'),
          _chips(
              dark,
              const ['更跟手', '标准', '说长句'],
              s.sttSilenceMs <= 500
                  ? '更跟手'
                  : (s.sttSilenceMs >= 1200 ? '说长句' : '标准'), (v) {
