/// 开关行：独立圆角卡片，轮廓与「开 / 关」状态一眼可辨。
/// 文字区与 Switch 区 hit test 物理隔离，各自只有一个回调，
/// 彻底避免「打开后关不掉」的双重触发。
class SwitchRow extends StatelessWidget {
  final String title;
  final String subtitle;
  final bool value;
  final ValueChanged<bool> onChanged;
  final IconData? icon;
  const SwitchRow({
    super.key,
    required this.title,
    this.subtitle = '',
    required this.value,
    required this.onChanged,
    this.icon,
  });

  @override
  Widget build(BuildContext context) {
    final dark = Theme.of(context).brightness == Brightness.dark;
    final on = value;
    final accent = accentOf(dark);
    return Padding(
      padding: const EdgeInsets.only(bottom: 9),
      child: AnimatedContainer(
        duration: D.animFast,
        curve: D.curve,
        decoration: BoxDecoration(
          color: on ? accent.withOpacity(dark ? 0.12 : 0.055) : surfaceOf(dark),
          borderRadius: BorderRadius.circular(D.r),
          border: Border.all(
            color: on ? accent.withOpacity(0.55) : borderOf(dark),
            width: on ? 1.3 : 1,
          ),
        ),
        child: Row(
          children: [
            if (icon != null)
              Padding(
                padding: const EdgeInsets.only(left: 13),
                child: Icon(icon,
                    size: 17, color: on ? accent : (dark ? C.dInk3 : C.ink3)),
              ),
            Expanded(
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: () => onChanged(!on),
                child: Padding(
                  padding:
                      EdgeInsets.fromLTRB(icon != null ? 10 : 14, 12, 6, 12),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        title,
                        style: ts(
                          dark,
                          size: 13.5,
                          weight: on ? FontWeight.w600 : FontWeight.w500,
                          color: on
                              ? (dark ? C.dInk : C.ink)
                              : (dark ? C.dInk2 : C.ink2),
                        ),
                      ),
                      if (subtitle.isNotEmpty)
                        Padding(
                          padding: const EdgeInsets.only(top: 3),
                          child: Text(subtitle, style: meta(dark, size: 11.5)),
                        ),
                    ],
                  ),
                ),
              ),
            ),
            Text(
              on ? '开' : '关',
              style: meta(dark, size: 11.5, color: on ? accent : null),
            ),
            Padding(
              padding: const EdgeInsets.only(left: 6, right: 9),
              child: Switch(
                value: on,
                onChanged: onChanged,
                activeColor: accent,
                activeTrackColor: accent.withOpacity(0.3),
                materialTapTargetSize: MaterialTapTargetSize.shrinkWrap,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

