    final acts = <Widget>[
      GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTap: () => st.patch((x) => x.visionHintDismissed = true),
        child: Padding(
          padding: const EdgeInsets.only(left: 8, top: 1),
          child: Text(t('忽略'), style: meta(dark, size: 11.5, color: accentOf(dark))),
        ),
