                          if (next && st.settings.activeSources.isEmpty) {
                            _snack(t('还没有启用的搜索源，去 设置 → 搜索 里勾选'));
                          }
                        },
                      ),
                      const Spacer(),
                      _primaryKey(st, dark),
                    ],
                  );
                }),
              ],
            ),
          ),
        ],
      ),
    );
