  /// 输入台里的模型快捷条。左边是当前模型（点开就是完整列表），
  /// 右边是直达搜索；两处开的是同一个弹层，不必记住两个入口。
  Widget _modelStrip(AppState st, bool dark) {
    final narrow = MediaQuery.sizeOf(context).width < 360;
    final sub = MuseC.sub(dark);
    final accent = MuseC.accent(dark);
    // 全新安装时 model 是空的（不再预设任何 GPT 模型名）。此时不要挂一个
    // 点开却是空列表的假模型：直接把入口写成「添加连接」，点了就去设置。
    final hasModel = st.settings.model.trim().isNotEmpty;
    final configured = st.settings.apiKey.trim().isNotEmpty ||
        !st.settings.baseUrl.startsWith('https://api.openai.com');
    final model = hasModel
        ? st.settings.model.trim()
        : (configured ? t('选择模型') : t('添加连接'));
    return Row(
      children: [
        Expanded(
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () => _openModelPicker(st),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                BrandIcon(brand: resolveModelBrand(model), size: 18, dark: dark),
                const SizedBox(width: 6),
                Flexible(
                  child: Text(
                    model,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                        fontSize: 12,
                        height: 1.2,
                        fontWeight: FontWeight.w600,
                        color: MuseC.text(dark)),
                  ),
                ),
                const SizedBox(width: 2),
                Icon(Icons.expand_more_rounded, size: 14, color: sub),
              ],
            ),
          ),
        ),
        const SizedBox(width: 8),
        GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTap: () => _openModelPicker(st),
          child: Container(
            padding: EdgeInsets.symmetric(
                horizontal: narrow ? 7 : 9, vertical: 4),
            decoration: BoxDecoration(
              color: MuseC.chip(dark).withOpacity(dark ? 0.9 : 0.7),
              borderRadius: BorderRadius.circular(12),
              border: Border.all(
                color: dark
                    ? Colors.white.withOpacity(0.12)
                    : Colors.black.withOpacity(0.08),
              ),
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Icon(Icons.search_rounded, size: 13, color: accent),
                if (!narrow) ...[
                  const SizedBox(width: 4),
                  Text(t('搜索模型'),
                      style: TextStyle(
                          fontSize: 11.5,
                          height: 1.2,
                          fontWeight: FontWeight.w600,
                          color: accent)),
                ],
              ],
            ),
          ),
        ),
      ],
    );
  }

  void _openModelPicker(AppState st) {
    _focus.unfocus();
    // 一个模型都没有、连接也没配好时，弹层里只会是一片空白，用户点进来
    // 还得再找一次设置入口。这里直接把人送到连接页，少一次无效跳转。
    final noModel = st.settings.model.trim().isEmpty;
    final noConnection = st.settings.apiKey.trim().isEmpty &&
        st.settings.baseUrl.startsWith('https://api.openai.com');
    if (noModel && noConnection && widget.onOpenSettings != null) {
      widget.onOpenSettings!.call();
      return;
    }
    unawaited(showModelPickerSheet(
      context,
      dark: widget.dark,
      st: st,
      onOpenSettings: widget.onOpenSettings,
    ));
  }

