/**
 * 语音功能的原生实现：录音、系统朗读、URL/文件播放、系统语音识别。
 *
 * 为什么不用第三方插件：flutter_tts / speech_to_text / record 这几个包各自
 * 在 build.gradle 里锁定了 AGP 8.12+ 或 8.13 的 classpath，与本工程的
 * Gradle 8.3 不兼容，只要装进来 release 构建就直接失败。这些能力本身都是
 * Android 系统 API（TextToSpeech / MediaPlayer / SpeechRecognizer /
 * MediaRecorder），自己接一遍约 300 行，换来的是构建链彻底可控。
 */
class MainActivity : FlutterActivity() {
    private val methodChannelName = "aigent/voice"
    private val eventChannelName = "aigent/voice_events"
    private val deviceChannelName = "aigent/device"

    private var events: EventChannel.EventSink? = null

    // 录音
    private var recorder: MediaRecorder? = null
    private var recordPath: String? = null

    // 系统朗读
    private var tts: TextToSpeech? = null
    private var ttsReady = false
    private var ttsUtteranceId = "aigent"

    // 播放（云端合成的音频）
    private var player: MediaPlayer? = null

    // 系统识别
    private var recognizer: SpeechRecognizer? = null
    private var sttOffline = false

    // 端侧离线识别（Vosk）：模型按需加载，识别在独立线程跑，不阻塞 UI。
    private var voskModel: Model? = null
    private var voskModelPath: String = ""
    private var voskRecord: AudioRecord? = null
    private var voskThread: Thread? = null
    @Volatile private var voskRunning = false

    // 录音/识别音量（驱动 Dart 侧波形）
    private val uiHandler = Handler(Looper.getMainLooper())
    private var amplitudeTask: Runnable? = null

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        val messenger = flutterEngine.dartExecutor.binaryMessenger

        EventChannel(messenger, eventChannelName).setStreamHandler(
            object : EventChannel.StreamHandler {
                override fun onListen(arguments: Any?, sink: EventChannel.EventSink?) {
                    events = sink
                }

                override fun onCancel(arguments: Any?) {
                    events = null
                }
            },
        )

        MethodChannel(messenger, methodChannelName).setMethodCallHandler { call, result ->
            when (call.method) {
                // ---------------- 录音
                "rec.hasPermission" -> result.success(hasMicPermission())
                "rec.requestPermission" -> {
                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M &&
                        !hasMicPermission()
                    ) {
                        requestPermissions(arrayOf(Manifest.permission.RECORD_AUDIO), 7701)
                    }
                    result.success(true)
                }
                "rec.start" -> {
                    val path = call.argument<String>("path")
                    if (path.isNullOrEmpty()) {
                        result.error("bad_path", "缺少输出路径", null)
                    } else {
                        try {
                            startRecording(path)
                            result.success(path)
                        } catch (e: Exception) {
                            releaseRecorder()
                            result.error("start_failed", e.message, null)
                        }
                    }
                }
                "rec.stop" -> {
                    val path = try {
                        stopRecording()
                    } catch (e: Exception) {
                        releaseRecorder()
                        null
                    }
                    result.success(path)
                }
                "rec.cancel" -> {
                    releaseRecorder()
                    deleteQuietly(recordPath)
                    recordPath = null
                    result.success(true)
                }

                // ---------------- 系统朗读
                "tts.speak" -> {
                    val text = call.argument<String>("text") ?: ""
                    val lang = call.argument<String>("lang") ?: "zh-CN"
                    val rate = (call.argument<Double>("rate") ?: 1.0).toFloat()
                    if (text.isBlank()) {
                        result.success(false)
                    } else {
                        speak(text, lang, rate)
                        result.success(true)
                    }
                }
                "tts.stop" -> {
                    try {
                        tts?.stop()
                    } catch (_: Exception) {
                    }
                    emit(mapOf("type" to "tts_done"))
                    result.success(true)
                }
                "tts.available" -> result.success(ttsReady || tts != null)

                // ---------------- 播放合成的音频
                "player.url" -> {
                    val url = call.argument<String>("url") ?: ""
                    val ok = playSource(url, isFile = false)
                    result.success(ok)
                }
                "player.file" -> {
                    val path = call.argument<String>("path") ?: ""
                    val ok = playSource(path, isFile = true)
                    result.success(ok)
                }
                "player.stop" -> {
                    try {
                        player?.stop()
                    } catch (_: Exception) {
                    }
                    try {
                        player?.release()
                    } catch (_: Exception) {
                    }
                    player = null
                    result.success(true)
                }

                // ---------------- 系统语音识别
                "stt.available" -> result.success(SpeechRecognizer.isRecognitionAvailable(this))
                // v4.4：把「有没有端侧离线引擎」告诉 Dart，用于标注引擎与自动回落。
                "stt.capabilities" -> result.success(sttCapabilities())
                "stt.start" -> {
                    val lang = call.argument<String>("lang") ?: "zh-CN"
                    val preferOffline = call.argument<Boolean>("preferOffline") ?: true
                    val silenceMs = call.argument<Int>("silenceMs") ?: 700
                    result.success(startListening(lang, preferOffline, silenceMs))
                }
                "stt.stop" -> {
                    try {
                        recognizer?.stopListening()
                    } catch (_: Exception) {
                    }
                    result.success(true)
                }
                "stt.cancel" -> {
                    destroyRecognizer()
                    result.success(true)
                }

                // ---------------- 端侧离线识别（Vosk）
                "vosk.status" -> result.success(
                    mapOf(
                        "loaded" to (voskModel != null),
                        "path" to voskModelPath,
                    ),
                )
                "vosk.prepare" -> {
                    val path = call.argument<String>("path") ?: ""
                    prepareVosk(path, result)
                }
                "vosk.start" -> {
                    val silenceMs = call.argument<Int>("silenceMs") ?: 700
                    result.success(startVosk(silenceMs))
                }
                "vosk.stop" -> {
                    voskRunning = false
                    result.success(true)
                }
                "vosk.cancel" -> {
                    voskRunning = false
                    voskThread?.interrupt()
                    result.success(true)
                }

                else -> result.notImplemented()
            }
        }

        // 设备智能体：只读设备信息 + 系统级动作（打开 App / 浏览器 / 日历 / 闹钟）。
        // 所有会跳出本应用的动作都走系统 Intent 的确认界面，不暗改任何数据。
        MethodChannel(messenger, deviceChannelName).setMethodCallHandler { call, result ->
            handleDeviceCall(call, result)
        }

        // 提前把 TTS 引擎准备好，首次点击朗读就不用等初始化。
        initTts()
    }

    // ------------------------------------------------------------ 设备智能体
    //
    // 设计边界：日历 / 闹钟 / 分享都会打开对应系统 App 的确认页，用户不点
    // 保存就不会产生任何变更。v4.25 起增加设备清理与文件查找，但写入范围
    // 严格限制在本应用 cache / code_cache / 隔离工作区内，且删除前校验路径；
    // 其它应用的数据一律不碰，需要用户操作的就调起系统设置页。

    private fun handleDeviceCall(call: MethodCall, result: MethodChannel.Result) {
        try {
            when (call.method) {
                "device.info" -> result.success(deviceInfo())
                "device.apps" -> result.success(installedApps())
                "app.open" -> result.success(openApp(call.argument<String>("package")))
                "web.open" -> result.success(openUrl(call.argument<String>("url")))
                "calendar.add" -> result.success(addCalendarEvent(call))
                "alarm.set" -> result.success(setAlarm(call))
                "share.text" -> result.success(
                    shareText(call.argument<String>("text"), call.argument<String>("title"))
                )
                "clipboard.set" -> result.success(setClipboard(call.argument<String>("text")))
                "toast" -> {
                    val msg = call.argument<String>("text") ?: ""
                    runOnUiThread { Toast.makeText(this, msg, Toast.LENGTH_SHORT).show() }
                    result.success(true)
                }
                "workspace.root" -> result.success(workspaceRoot())
                "storage.summary" -> result.success(storageSummary())
                "storage.clean" -> result.success(cleanCache())
                "files.search" -> result.success(
                    searchFiles(
                        call.argument<String>("query") ?: "",
                        call.argument<Number>("limit")?.toInt() ?: 60
                    )
                )
                "files.delete" -> result.success(deleteAccessibleFile(call.argument<String>("path")))
                "storage.openSettings" -> result.success(openStorageSettings())
                else -> result.notImplemented()
            }
        } catch (e: Exception) {
            result.error("device_error", e.message ?: "设备能力调用失败", null)
        }
    }

    @SuppressLint("HardwareIds")
    private fun deviceInfo(): Map<String, Any?> {
        val am = getSystemService(ACTIVITY_SERVICE) as? ActivityManager
        val mem = ActivityManager.MemoryInfo()
        try {
            am?.getMemoryInfo(mem)
        } catch (_: Exception) {
        }
        val dm = resources.displayMetrics
        val battery = try {
            (getSystemService(BATTERY_SERVICE) as? BatteryManager)
                ?.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY) ?: -1
        } catch (_: Exception) {
            -1
        }
        val stat = try {
            StatFs(filesDir.absolutePath)
        } catch (_: Exception) {
            null
        }
        val version = try {
            packageManager.getPackageInfo(packageName, 0).versionName ?: "?"
        } catch (_: Exception) {
            "?"
        }
        return mapOf(
            "manufacturer" to Build.MANUFACTURER,
            "brand" to Build.BRAND,
            "model" to Build.MODEL,
            "product" to Build.PRODUCT,
            "device" to Build.DEVICE,
            "board" to Build.BOARD,
            "hardware" to Build.HARDWARE,
            "android" to Build.VERSION.RELEASE,
            "sdk" to Build.VERSION.SDK_INT,
            "buildId" to Build.DISPLAY,
            "abis" to Build.SUPPORTED_ABIS.toList(),
            "cpuCores" to Runtime.getRuntime().availableProcessors(),
            "totalMemMb" to mem.totalMem / 1048576L,
            "availMemMb" to mem.availMem / 1048576L,
            "width" to dm.widthPixels,
            "height" to dm.heightPixels,
            "density" to dm.densityDpi,
            "battery" to battery,
            "storageTotalMb" to (stat?.totalBytes ?: -1L) / 1048576L,
            "storageFreeMb" to (stat?.availableBytes ?: -1L) / 1048576L,
            "locale" to Locale.getDefault().toString(),
            "timezone" to TimeZone.getDefault().id,
            "appVersion" to version,
            "packageName" to packageName,
        )
    }

    /** 只列「可从桌面启动」的应用，避免把系统服务组件也暴露给模型。 */
    private fun installedApps(): List<Map<String, Any?>> {
        val pm = packageManager
        val main = Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER)
        val list = try {
            pm.queryIntentActivities(main, 0)
        } catch (_: Exception) {
            emptyList()
        }
        return list.map { ri ->
            val info = ri.activityInfo
            mapOf(
                "package" to info.packageName,
                "label" to try {
                    ri.loadLabel(pm).toString()
                } catch (_: Exception) {
                    info.packageName
                },
                "system" to ((info.applicationInfo.flags and ApplicationInfo.FLAG_SYSTEM) != 0),
            )
        }.sortedBy { it["label"].toString().lowercase(Locale.ROOT) }
    }

    private fun openApp(pkg: String?): Boolean {
        if (pkg.isNullOrBlank()) return false
        // 只接受纯包名，杜绝把别的东西塞进 Intent。
        if (!Regex("^[A-Za-z0-9_.]+$").matches(pkg)) return false
        val intent = packageManager.getLaunchIntentForPackage(pkg) ?: return false
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        return try {
            startActivity(intent)
            true
        } catch (_: Exception) {
            false
        }
    }

    private fun openUrl(raw: String?): Boolean {
        if (raw.isNullOrBlank()) return false
        var url = raw.trim()
        if (!url.contains("://")) url = "https://$url"
        // 只放行 http/https，避免模型拼出 file://、content:// 之类的私有 URI。
        if (!url.startsWith("http://") && !url.startsWith("https://")) return false
        val intent = Intent(Intent.ACTION_VIEW, Uri.parse(url))
            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        return try {
            startActivity(intent)
            true
        } catch (_: Exception) {
            false
        }
    }

    /** 调起系统日历「新建事件」界面，由用户确认后保存；本应用不持有日历权限。 */
    private fun addCalendarEvent(call: MethodCall): Boolean {
        val title = call.argument<String>("title")?.trim()
        if (title.isNullOrEmpty()) return false
        val start = call.argument<Number>("start")?.toLong()
            ?: (System.currentTimeMillis() + 3600000L)
        val end = call.argument<Number>("end")?.toLong() ?: (start + 3600000L)
        val intent = Intent(Intent.ACTION_INSERT)
            .setData(CalendarContract.Events.CONTENT_URI)
            .putExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME, start)
            .putExtra(CalendarContract.EXTRA_EVENT_END_TIME, end)
            .putExtra(Intent.EXTRA_TITLE, title)
            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        call.argument<String>("description")?.let {
            intent.putExtra(CalendarContract.Events.DESCRIPTION, it)
        }
        call.argument<String>("location")?.let {
            intent.putExtra(CalendarContract.Events.EVENT_LOCATION, it)
        }
        return try {
            startActivity(intent)
            true
        } catch (_: Exception) {
            false
        }
    }

    /** 调起系统时钟「设置闹钟」界面，不跳过确认页。 */
    private fun setAlarm(call: MethodCall): Boolean {
        val hour = call.argument<Number>("hour")?.toInt() ?: return false
        val minute = call.argument<Number>("minute")?.toInt() ?: 0
        if (hour !in 0..23 || minute !in 0..59) return false
        val intent = Intent(AlarmClock.ACTION_SET_ALARM)
            .putExtra(AlarmClock.EXTRA_HOUR, hour)
            .putExtra(AlarmClock.EXTRA_MINUTES, minute)
            .putExtra(AlarmClock.EXTRA_MESSAGE, call.argument<String>("label") ?: "Aigent")
            .putExtra(AlarmClock.EXTRA_SKIP_UI, false)
            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        return try {
            startActivity(intent)
            true
        } catch (_: Exception) {
            false
        }
    }

    private fun shareText(text: String?, title: String?): Boolean {
        if (text.isNullOrEmpty()) return false
        val send = Intent(Intent.ACTION_SEND)
            .setType("text/plain")
            .putExtra(Intent.EXTRA_TEXT, text)
        val chooser = Intent.createChooser(send, title ?: "分享")
            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
        return try {
            startActivity(chooser)
            true
        } catch (_: Exception) {
            false
        }
    }

    private fun setClipboard(text: String?): Boolean {
        if (text.isNullOrEmpty()) return false
        val cm = getSystemService(CLIPBOARD_SERVICE) as? ClipboardManager ?: return false
        cm.setPrimaryClip(ClipData.newPlainText("Aigent", text))
        return true
    }

    /** 智能体的独立工作目录：应用专属外部目录，卸载即清理，不碰用户文件。 */
    private fun workspaceRoot(): String {
        val base = getExternalFilesDir(null) ?: filesDir
        return File(base, "aigent_workspace").absolutePath
    }

    // ------------------------------------------------ v4.25 设备清理 / 找文件
    //
    // 边界：Android 7 起第三方应用已无法清理别的应用缓存，也读不到别的应用
    // 私有目录。这里只处理本应用自己的 cache / code_cache / 临时文件与隔离
    // 工作区，并在可访问的公共目录里按文件名查找。删除前校验路径必须落在
    // 可删除根目录内，越界一律拒绝；其它 App 的缓存交给系统设置页由用户处理。

    /** 扫描用的根目录：应用专属目录 + 公共下载目录（能列到多少算多少）。 */
    private fun accessibleRoots(): List<File> {
        val out = LinkedHashMap<String, File>()
        fun add(f: File?) {
            if (f == null) return
            try {
                out[f.canonicalPath] = f
            } catch (_: Exception) {
            }
        }
        add(filesDir)
        add(cacheDir)
        add(codeCacheDir)
        for (d in externalCacheDirs) add(d)
        for (d in getExternalFilesDirs(null)) add(d)
        try {
            @Suppress("DEPRECATION")
            add(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS))
        } catch (_: Exception) {
        }
        return out.values.filter { it.exists() }
    }

    /** 允许删除的根：只含缓存与隔离工作区，绝不碰应用数据与其它目录。 */
    private fun deletableRoots(): List<File> {
        val out = ArrayList<File>()
        out.add(cacheDir)
        out.add(codeCacheDir)
        for (d in externalCacheDirs) out.add(d)
        out.add(File(workspaceRoot()))
        return out
    }

    /** 返回 (总字节, 文件数)，限制递归深度，避免异常目录把主线程拖住。 */
    private fun dirSize(f: File, depth: Int = 0): Pair<Long, Int> {
        if (depth > 12) return Pair(0L, 0)
        return try {
            if (f.isFile) {
                Pair(f.length(), 1)
            } else {
                var bytes = 0L
                var count = 0
                for (c in f.listFiles() ?: emptyArray()) {
                    val r = dirSize(c, depth + 1)
                    bytes += r.first
                    count += r.second
                }
                Pair(bytes, count)
            }
        } catch (_: Exception) {
            Pair(0L, 0)
        }
    }

    private fun storageSummary(): Map<String, Any?> {
        val cache = dirSize(cacheDir)
        val codeCache = dirSize(codeCacheDir)
        var tempBytes = 0L
        var tempFiles = 0
        for (f in cacheDir.listFiles() ?: emptyArray()) {
            if (!f.isDirectory && (f.name.endsWith(".tmp") || f.name.startsWith("temp"))) {
                tempBytes += f.length()
                tempFiles++
            }
        }
        val ws = dirSize(File(workspaceRoot()))
        val stat = try {
            StatFs(filesDir.absolutePath)
        } catch (_: Exception) {
            null
        }
        return mapOf(
            "cacheBytes" to cache.first + codeCache.first,
            "tempBytes" to tempBytes,
            "workspaceBytes" to ws.first,
            "cacheFiles" to cache.second + codeCache.second + tempFiles,
            "freeBytes" to (stat?.availableBytes ?: 0L),
            "totalBytes" to (stat?.totalBytes ?: 0L)
        )
    }

    private fun deleteRecursively(f: File): Boolean = try {
        if (f.isDirectory) {
            for (c in f.listFiles() ?: emptyArray()) deleteRecursively(c)
        }
        f.delete()
    } catch (_: Exception) {
        false
    }

    private fun cleanCache(): Map<String, Any?> {
        var freed = 0L
        var removed = 0
        for (root in deletableRoots()) {
            // 工作区是用户数据，只清其中的临时子目录，不整体删掉。
            val children = try {
                if (root.name == "aigent_workspace") {
                    root.listFiles()?.filter { it.name == "tmp" || it.name == "cache" }
                        ?.toTypedArray() ?: emptyArray()
                } else {
                    root.listFiles() ?: emptyArray()
                }
            } catch (_: Exception) {
                emptyArray()
            }
            for (c in children) {
                val size = dirSize(c)
                if (deleteRecursively(c)) {
                    freed += size.first
                    removed += size.second
                }
            }
        }
        return mapOf("freed" to freed, "files" to removed)
    }

    private fun searchFiles(query: String, limit: Int): List<Map<String, Any?>> {
        val q = query.trim().toLowerCase(Locale.ROOT)
        val safeLimit = limit.coerceIn(1, 200)
        val out = ArrayList<Map<String, Any?>>()
        val seen = HashSet<String>()
        for (root in accessibleRoots()) {
            walkFiles(root, 0, q, safeLimit, out, seen)
            if (out.size >= safeLimit) break
        }
        // 最近修改的排前面，方便「帮我找刚下载的那个文件」。
        val sorted = out.sortedByDescending { (it["modified"] as? Number)?.toLong() ?: 0L }
        return sorted.take(safeLimit)
    }

    private fun walkFiles(
        dir: File,
        depth: Int,
        q: String,
        limit: Int,
        out: MutableList<Map<String, Any?>>,
        seen: MutableSet<String>
    ) {
        if (depth > 8 || out.size >= limit) return
        val children = try {
            dir.listFiles()
        } catch (_: Exception) {
            null
        } ?: return
        for (f in children) {
            if (out.size >= limit) return
            try {
                if (!seen.add(f.canonicalPath)) continue
                val name = f.name
                if (q.isEmpty() || name.toLowerCase(Locale.ROOT).contains(q)) {
                    out.add(
                        mapOf(
                            "path" to f.absolutePath,
                            "name" to name,
                            "size" to (if (f.isFile) f.length() else 0L),
                            "modified" to f.lastModified(),
                            "isDir" to f.isDirectory
                        )
                    )
                }
                if (f.isDirectory) walkFiles(f, depth + 1, q, limit, out, seen)
            } catch (_: Exception) {
            }
        }
    }

    // 不能叫 deleteFile：Context 已有同名的 public 方法，会报「削弱访问权限」。
    private fun deleteAccessibleFile(path: String?): Boolean {
        if (path.isNullOrEmpty()) return false
        return try {
            val target = File(path).canonicalFile
            if (target.isDirectory) return false
            val allowed = deletableRoots().any { root ->
                try {
                    val r = root.canonicalFile
                    target.path.startsWith(r.path + File.separator)
                } catch (_: Exception) {
                    false
                }
            }
            if (!allowed) return false
            target.delete()
        } catch (_: Exception) {
            false
        }
    }

    private fun openStorageSettings(): Boolean {
        val candidates = listOf(
            Intent(android.provider.Settings.ACTION_INTERNAL_STORAGE_SETTINGS),
            Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS)
                .setData(Uri.parse("package:$packageName"))
        )
        for (i in candidates) {
            try {
                i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                startActivity(i)
                return true
            } catch (_: Exception) {
            }
        }
        return false
    }

    private fun emit(data: Map<String, Any?>) {
        runOnUiThread { events?.success(data) }
    }

    private fun hasMicPermission(): Boolean {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.M) return true
        return checkSelfPermission(Manifest.permission.RECORD_AUDIO) ==
            PackageManager.PERMISSION_GRANTED
    }

    // ------------------------------------------------------------ 录音

    private fun startRecording(path: String) {
        if (!hasMicPermission()) throw IllegalStateException("没有麦克风权限")
        releaseRecorder()

        val r = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            MediaRecorder(this)
        } else {
            @Suppress("DEPRECATION")
            MediaRecorder()
        }
        r.setAudioSource(MediaRecorder.AudioSource.MIC)
        // MPEG_4 + AAC，16k 单声道：体积小，转写接口都认。
        r.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4)
        r.setAudioEncoder(MediaRecorder.AudioEncoder.AAC)
        r.setAudioEncodingBitRate(64000)
        r.setAudioSamplingRate(16000)
        r.setAudioChannels(1)
        r.setOutputFile(path)
        r.prepare()
        r.start()

        recorder = r
        recordPath = path
        startAmplitudePolling()
    }

    /** 每 90ms 读一次峰值，归一化成 0~1 回传给输入栏的波形。 */
    private fun startAmplitudePolling() {
        stopAmplitudePolling()
        val task = object : Runnable {
            override fun run() {
                val r = recorder ?: return
                val level = try {
                    (r.maxAmplitude / 12000f).coerceIn(0f, 1f)
                } catch (_: Exception) {
                    0f
                }
                emit(mapOf("type" to "rec_rms", "level" to level))
                uiHandler.postDelayed(this, 90)
            }
        }
        amplitudeTask = task
        uiHandler.postDelayed(task, 120)
    }

    private fun stopAmplitudePolling() {
        amplitudeTask?.let { uiHandler.removeCallbacks(it) }
        amplitudeTask = null
    }

    /** 停止并返回路径；录得太短（< 1KB）视为无效，返回 null 让 Dart 侧提示重录。 */
    private fun stopRecording(): String? {
        stopAmplitudePolling()
        val r = recorder ?: return null
        var ok = true
        try {
            r.stop()
        } catch (e: Exception) {
            ok = false
        }
        try {
            r.release()
        } catch (_: Exception) {
        }
        recorder = null

        val path = recordPath
        recordPath = null
        if (!ok || path == null) {
            deleteQuietly(path)
            return null
        }
        val f = File(path)
        if (!f.exists() || f.length() < 1024) {
            deleteQuietly(path)
            return null
        }
        return path
    }

    private fun releaseRecorder() {
        stopAmplitudePolling()
        try {
            recorder?.release()
        } catch (_: Exception) {
        }
        recorder = null
    }

    // ------------------------------------------------------------ 系统朗读

    private fun initTts() {
        if (tts != null) return
        tts = TextToSpeech(this) { status ->
            ttsReady = status == TextToSpeech.SUCCESS
            if (ttsReady) {
                tts?.setOnUtteranceProgressListener(
                    object : UtteranceProgressListener() {
                        override fun onStart(utteranceId: String?) {}
                        override fun onDone(utteranceId: String?) {
                            emit(mapOf("type" to "tts_done"))
                        }

                        @Deprecated("Deprecated in Java")
                        override fun onError(utteranceId: String?) {
                            emit(mapOf("type" to "tts_error", "message" to "朗读失败"))
                        }
                    },
                )
            }
        }
    }

    private fun speak(text: String, lang: String, rate: Float) {
        initTts()
        val engine = tts ?: run {
            emit(mapOf("type" to "tts_error", "message" to "系统没有可用的语音引擎"))
            return
        }
        // 初始化是异步的：引擎还没就绪时，直接在 onInit 里补一次。
        if (!ttsReady) {
            engine.setOnUtteranceProgressListener(
                object : UtteranceProgressListener() {
                    override fun onStart(utteranceId: String?) {}
                    override fun onDone(utteranceId: String?) {
                        emit(mapOf("type" to "tts_done"))
                    }

                    @Deprecated("Deprecated in Java")
                    override fun onError(utteranceId: String?) {
                        emit(mapOf("type" to "tts_error", "message" to "朗读失败"))
                    }
                },
            )
        }
        try {
            val locale = Locale.forLanguageTag(lang)
            if (engine.isLanguageAvailable(locale) >= TextToSpeech.LANG_AVAILABLE) {
                engine.language = locale
            }
            // TextToSpeech 的 1.0 是常速；调用方给的是倍率，直接对齐。
            engine.setSpeechRate(rate.coerceIn(0.3f, 2.0f))
            engine.speak(text, TextToSpeech.QUEUE_FLUSH, null, ttsUtteranceId)
            emit(mapOf("type" to "tts_start"))
        } catch (e: Exception) {
            emit(mapOf("type" to "tts_error", "message" to (e.message ?: "朗读失败")))
        }
    }

    // ------------------------------------------------------------ 播放合成音频

    private fun playSource(source: String, isFile: Boolean): Boolean {
        if (source.isBlank()) return false
        try {
            player?.release()
        } catch (_: Exception) {
        }
        val p = MediaPlayer()
        p.setAudioAttributes(
            AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_MEDIA)
                .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
                .build(),
        )
        return try {
            if (isFile) p.setDataSource(source) else p.setDataSource(source)
            p.setOnPreparedListener {
                it.start()
                emit(mapOf("type" to "player_start"))
            }
            p.setOnCompletionListener {
                emit(mapOf("type" to "player_done"))
                try {
                    it.release()
                } catch (_: Exception) {
                }
            }
            p.setOnErrorListener { mp, _, _ ->
                emit(mapOf("type" to "player_error", "message" to "音频无法播放"))
                try {
                    mp.release()
                } catch (_: Exception) {
                }
                true
            }
            p.prepareAsync()
            player = p
            true
        } catch (e: Exception) {
            emit(mapOf("type" to "player_error", "message" to (e.message ?: "播放失败")))
            try {
                p.release()
            } catch (_: Exception) {
            }
            false
        }
    }

    // ------------------------------------------------------------ 系统识别

    /** 端侧离线能力探测：设置页据此标注「本地可用 / 需下载语音包」。 */
    @SuppressLint("NewApi")
    private fun sttCapabilities(): Map<String, Any?> {
        val available = try {
            SpeechRecognizer.isRecognitionAvailable(this)
        } catch (_: Exception) {
            false
        }
        val onDevice = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            try {
                SpeechRecognizer.isOnDeviceRecognitionAvailable(this)
            } catch (_: Exception) {
                false
            }
        } else {
            false
        }
        return mapOf(
            "available" to available,
            "onDevice" to onDevice,
            "preferOffline" to (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M),
            "sdk" to Build.VERSION.SDK_INT,
        )
    }

    @SuppressLint("NewApi")
    @Suppress("DEPRECATION")
    private fun startListening(lang: String, preferOffline: Boolean, silenceMs: Int): Boolean {
        if (!SpeechRecognizer.isRecognitionAvailable(this)) {
            emit(mapOf("type" to "stt_error", "message" to "系统没有语音识别服务", "code" to -1))
            return false
        }
        destroyRecognizer()

        // Android 12+ 且系统装了离线语音包时，直接用端侧识别器：
        // 不联网、首字延迟最低。其余情况退回普通识别器 + EXTRA_PREFER_OFFLINE。
        val useOnDevice = preferOffline &&
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.S &&
            try {
                SpeechRecognizer.isOnDeviceRecognitionAvailable(this)
            } catch (_: Exception) {
                false
            }
        sttOffline = useOnDevice
        val r = if (useOnDevice) {
            SpeechRecognizer.createOnDeviceSpeechRecognizer(this)
        } else {
            SpeechRecognizer.createSpeechRecognizer(this)
        }
        recognizer = r
        r.setRecognitionListener(object : RecognitionListener {
            override fun onReadyForSpeech(params: Bundle?) {
                emit(mapOf("type" to "stt_start", "offline" to sttOffline))
            }

            override fun onBeginningOfSpeech() {
                emit(mapOf("type" to "stt_speech_begin"))
            }

            override fun onRmsChanged(rmsdB: Float) {
                // 系统回传的是 dB，常见范围 -2~10；映射到 0~1 给波形用。
                emit(
                    mapOf(
                        "type" to "stt_rms",
                        "level" to ((rmsdB + 2f) / 12f).coerceIn(0f, 1f),
                    ),
                )
            }

            override fun onBufferReceived(buffer: ByteArray?) {}
            override fun onEndOfSpeech() {
                emit(mapOf("type" to "stt_speech_end"))
            }

            override fun onError(error: Int) {
                // 6/7 是「没听到声音」「没识别出结果」，属于正常结束，不算错误。
                if (error == SpeechRecognizer.ERROR_NO_MATCH ||
                    error == SpeechRecognizer.ERROR_SPEECH_TIMEOUT
                ) {
                    emit(mapOf("type" to "stt_no_result", "offline" to sttOffline))
                } else {
                    emit(
                        mapOf(
                            "type" to "stt_error",
                            "message" to sttErrorText(error),
                            "code" to error,
                            "offline" to sttOffline,
                        ),
                    )
                }
            }

            override fun onResults(results: Bundle?) {
                val text = results
                    ?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)
                    ?.firstOrNull()
                    ?: ""
                emit(mapOf("type" to "stt_final", "text" to text, "offline" to sttOffline))
            }

            override fun onPartialResults(partialResults: Bundle?) {
                val text = partialResults
                    ?.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION)
                    ?.firstOrNull()
                    ?: ""
                if (text.isNotEmpty()) {
                    emit(mapOf("type" to "stt_partial", "text" to text))
                }
            }

            override fun onEvent(eventType: Int, params: Bundle?) {}
        })

        val intent = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
            putExtra(
                RecognizerIntent.EXTRA_LANGUAGE_MODEL,
                RecognizerIntent.LANGUAGE_MODEL_FREE_FORM,
            )
            putExtra(RecognizerIntent.EXTRA_LANGUAGE, lang)
            putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS, true)
            putExtra(RecognizerIntent.EXTRA_MAX_RESULTS, 1)
            putExtra(RecognizerIntent.EXTRA_CALLING_PACKAGE, packageName)
            // 端侧识别器不认这个 extra；普通识别器用它优先走离线语音包。
            if (!useOnDevice && preferOffline) {
                putExtra(RecognizerIntent.EXTRA_PREFER_OFFLINE, true)
            }
            // 说完立即收尾，别让用户等系统默认的 2 秒静音判断。
            putExtra(
                RecognizerIntent.EXTRA_SPEECH_INPUT_COMPLETE_SILENCE_LENGTH_MILLIS,
                silenceMs,
            )
            putExtra(
                RecognizerIntent.EXTRA_SPEECH_INPUT_POSSIBLY_COMPLETE_SILENCE_LENGTH_MILLIS,
                (silenceMs * 0.7).toInt(),
            )
            putExtra(RecognizerIntent.EXTRA_SPEECH_INPUT_MINIMUM_LENGTH_MILLIS, 800)
        }
        return try {
            r.startListening(intent)
            true
        } catch (e: Exception) {
            emit(
                mapOf(
                    "type" to "stt_error",
                    "message" to (e.message ?: "无法启动识别"),
                    "code" to -2,
                    "offline" to sttOffline,
                ),
            )
            destroyRecognizer()
            false
        }
    }

    private fun sttErrorText(code: Int): String = when (code) {
        SpeechRecognizer.ERROR_AUDIO -> "录音出错"
        SpeechRecognizer.ERROR_CLIENT -> "识别客户端错误"
        SpeechRecognizer.ERROR_INSUFFICIENT_PERMISSIONS -> "没有麦克风权限"
        SpeechRecognizer.ERROR_NETWORK -> "识别需要网络，当前不可用"
        SpeechRecognizer.ERROR_NETWORK_TIMEOUT -> "识别网络超时"
        SpeechRecognizer.ERROR_SERVER -> "识别服务异常"
        SpeechRecognizer.ERROR_SPEECH_TIMEOUT -> "没有听到声音"
        SpeechRecognizer.ERROR_NO_MATCH -> "没识别出内容"
        SpeechRecognizer.ERROR_RECOGNIZER_BUSY -> "识别器忙，稍后再试"
        // 9 = ERROR_LANGUAGE_UNAVAILABLE：端侧离线包没下载，交给 Dart 侧回落在线识别。
        9 -> "没有这个语言的离线语音包"
        else -> "识别失败（$code）"
    }

    private fun destroyRecognizer() {
        try {
            recognizer?.cancel()
        } catch (_: Exception) {
        }
        try {
            recognizer?.destroy()
        } catch (_: Exception) {
        }
        recognizer = null
    }

    private fun deleteQuietly(path: String?) {
        if (path.isNullOrEmpty()) return
        try {
            val f = File(path)
            if (f.exists()) f.delete()
        } catch (_: Exception) {
        }
    }

    // ------------------------------------------------------------ 端侧离线识别

    /// 加载模型可能花 1~3 秒，放到后台线程，加载完再回主线程 resolve。
    private fun prepareVosk(path: String, result: MethodChannel.Result) {
        if (path.isEmpty() || !File(path).exists()) {
            result.success(false)
            return
        }
        if (voskModel != null && voskModelPath == path) {
            result.success(true)
            return
        }
        Thread {
            var ok = false
            var message = ""
            try {
                voskModel?.close()
                voskModel = Model(path)
                voskModelPath = path
                ok = true
            } catch (e: Throwable) {
                message = e.message ?: "模型加载失败"
                voskModel = null
                voskModelPath = ""
            }
            runOnUiThread {
                if (!ok) {
                    result.error("vosk_model", message.ifEmpty { "模型加载失败" }, null)
                } else {
                    result.success(true)
                }
            }
        }.start()
    }

    private fun startVosk(silenceMs: Int): Boolean {
        val model = voskModel
        if (model == null) {
            emitAsync(
                mapOf(
                    "type" to "stt_error",
                    "message" to "离线语音包还未加载",
                    "code" to -11,
                    "offline" to true,
                ),
            )
            return false
        }
        if (!hasMicPermission()) {
            emitAsync(
                mapOf(
                    "type" to "stt_error",
                    "message" to "没有麦克风权限",
                    "code" to -3,
                    "offline" to true,
                ),
            )
            return false
        }
        voskRunning = false
        voskThread?.interrupt()
        voskThread = null
        try {
            voskRecord?.release()
        } catch (_: Exception) {
        }

        val minBuf = AudioRecord.getMinBufferSize(
            16000,
            AudioFormat.CHANNEL_IN_MONO,
            AudioFormat.ENCODING_PCM_16BIT,
        )
        val bufSize = max(minBuf, 4096) * 2
        val record = try {
            AudioRecord(
                MediaRecorder.AudioSource.MIC,
                16000,
                AudioFormat.CHANNEL_IN_MONO,
                AudioFormat.ENCODING_PCM_16BIT,
                bufSize,
            )
        } catch (e: Exception) {
            emitAsync(
                mapOf(
                    "type" to "stt_error",
                    "message" to (e.message ?: "无法打开麦克风"),
                    "code" to -4,
                    "offline" to true,
                ),
            )
            return false
        }
        if (record.state != AudioRecord.STATE_INITIALIZED) {
            try {
                record.release()
            } catch (_: Exception) {
            }
            emitAsync(
                mapOf(
                    "type" to "stt_error",
                    "message" to "麦克风被其他应用占用",
                    "code" to -4,
                    "offline" to true,
                ),
            )
            return false
        }
        voskRecord = record
        voskRunning = true

        Thread {
            var rec: Recognizer? = null
            var heard = false
            val startedAt = System.currentTimeMillis()
            val quietLimit = silenceMs.coerceIn(300, 3000)
            var lastVoiceAt = startedAt
            try {
                rec = Recognizer(model, 16000.0f)
                rec.setWords(false)
                record.startRecording()
                emitAsync(
                    mapOf("type" to "stt_start", "offline" to true, "engine" to "vosk"),
                )
                val buffer = ByteArray(4096)
                while (voskRunning) {
                    val n = record.read(buffer, 0, buffer.size)
                    if (n <= 0) {
                        if (n == AudioRecord.ERROR_INVALID_OPERATION ||
                            n == AudioRecord.ERROR_BAD_VALUE
                        ) break
                        continue
                    }
                    // RMS 驱动波形；顺带做「说完就停」的判断，比等系统超时快。
                    var sum = 0.0
                    var i = 0
                    while (i + 1 < n) {
                        val s = ((buffer[i + 1].toInt() shl 8) or (buffer[i].toInt() and 0xFF)).toShort()
                        sum += (s.toDouble() / 32768.0) * (s.toDouble() / 32768.0)
                        i += 2
                    }
                    val rms = sqrt(sum / max(1, n / 2).toDouble()).coerceIn(0.0, 1.0)
                    emitAsync(mapOf("type" to "stt_rms", "level" to rms))
                    val now = System.currentTimeMillis()
                    if (rms > 0.035) {
                        heard = true
                        lastVoiceAt = now
                    }

                    val complete = rec.acceptWaveForm(buffer, n)
                    if (complete) {
                        val text = JSONObject(rec.result).optString("text", "").trim()
                        if (text.isNotEmpty()) {
                            emitAsync(
                                mapOf(
                                    "type" to "stt_final",
                                    "text" to text,
                                    "offline" to true,
                                    "engine" to "vosk",
                                ),
                            )
                            heard = true
                            break
                        }
                    } else {
                        val partial =
                            JSONObject(rec.partialResult).optString("partial", "").trim()
                        if (partial.isNotEmpty()) {
                            emitAsync(mapOf("type" to "stt_partial", "text" to partial))
                        }
                    }

                    // 一直没听到声音：8 秒收尾，别让面板无限转。
                    if (!heard && now - startedAt > 8000) break
                    // 说过话之后长时间静音：直接结束，省得用户再点一次。
                    if (heard && now - lastVoiceAt > quietLimit + 300) break
                }
                if (voskRunning) {
                    val text = JSONObject(rec.finalResult).optString("text", "").trim()
                    if (text.isNotEmpty()) {
                        emitAsync(
                            mapOf(
                                "type" to "stt_final",
                                "text" to text,
                                "offline" to true,
                                "engine" to "vosk",
                            ),
                        )
                    } else {
                        emitAsync(
                            mapOf("type" to "stt_no_result", "offline" to true),
                        )
                    }
                }
            } catch (e: Throwable) {
                emitAsync(
                    mapOf(
                        "type" to "stt_error",
                        "message" to (e.message ?: "离线识别失败"),
                        "code" to -12,
                        "offline" to true,
                    ),
                )
            } finally {
                try {
                    record.stop()
                } catch (_: Exception) {
                }
                try {
                    record.release()
                } catch (_: Exception) {
                }
                if (voskRecord === record) voskRecord = null
                try {
                    rec?.close()
                } catch (_: Exception) {
                }
                voskRunning = false
            }
        }.start()
        return true
    }

    private fun emitAsync(data: Map<String, Any?>) {
        runOnUiThread {
            try {
                emit(data)
            } catch (_: Exception) {
            }
        }
    }

    override fun onDestroy() {
        stopAmplitudePolling()
        voskRunning = false
        voskThread?.interrupt()
        try {
            voskRecord?.release()
        } catch (_: Exception) {
        }
        try {
            voskModel?.close()
        } catch (_: Exception) {
        }
        releaseRecorder()
        destroyRecognizer()
        try {
            player?.release()
        } catch (_: Exception) {
        }
        try {
            tts?.stop()
            tts?.shutdown()
        } catch (_: Exception) {
        }
        super.onDestroy()
    }
}

#!/usr/bin/env python3
"""检查界面文案与词表的完整性。

CI 与本地都用同一条命令：

    python3 tool/check_i18n.py

检查项：
1. 代码里所有 `t('中文')` 都能在 en.dart 找到英文（带 `$` 插值的除外）；
2. 每种语言的 tsv 都覆盖同一批 key；
3. 没有 key 里有未转义的制表符 / 换行。
"""
import glob
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def collect_keys():
    keys, skipped = set(), set()
    for p in glob.glob(os.path.join(ROOT, 'lib', 'ui', '*.dart')):
        s = open(p, encoding='utf-8').read()
        for m in re.finditer(r"(?:L10n\.)?t\('((?:[^'\\]|\\.)*)'\)", s):
            k = m.group(1).replace("\\'", "'").replace('\\n', '\n')
            if not re.search(r'[\u4e00-\u9fa5]', k):
                continue
            if '$' in k:
                skipped.add(k)
            else:
                keys.add(k)
    # 游戏内容词条：天赋的「名称 / 描述 / 倾向」在 kTalents 里是数据，
    # 运行时用 t(name) 查表，参数是变量，上面的正则扫不到。这里补一遍，
    # 保证 40 种语言的词表都覆盖它们（否则英文界面会露出中文）。
    p2 = os.path.join(ROOT, 'lib', 'services', 'life_sim.dart')
    if os.path.exists(p2):
        s2 = open(p2, encoding='utf-8').read()
        pat = re.compile(
            r"LifeTalent\(\s*'[^']*',\s*'([^']*)',\s*'([^']*)',\s*'([^']*)'\)")
        for m in pat.finditer(s2):
            for g in m.groups():
                if re.search(r'[\u4e00-\u9fa5]', g) and '$' not in g:
                    keys.add(g)
    return keys, skipped


def read_en():
    src = open(os.path.join(ROOT, 'lib', 'i18n', 'en.dart'), encoding='utf-8').read()
    pat = re.compile(r"^  '((?:[^'\\]|\\.)*)':\s*\n?\s*'((?:[^'\\]|\\.)*)',", re.M)
    def unesc(x):
        return (x.replace("\\'", "'").replace('\\n', '\n')
                .replace('\\\\', '\\'))

    return {unesc(k): unesc(v) for k, v in pat.findall(src)}


def read_tsv(path):
    out = {}
    for line in open(path, encoding='utf-8').read().split('\n'):
        if not line.strip() or '\t' not in line:
            continue
        k, v = line.split('\t', 1)
        out[k.replace(r'\n', '\n')] = v
    return out


def main():
    keys, skipped = collect_keys()
    en = read_en()
    missing_en = sorted(keys - set(en))
    ok = True
    print(f'代码词条 {len(keys)}（另有 {len(skipped)} 条含插值，跳过）')
    if missing_en:
        ok = False
        print(f'✗ en.dart 缺 {len(missing_en)} 条：')
        for k in missing_en[:12]:
            print('   ', k)

    files = sorted(glob.glob(os.path.join(ROOT, 'assets', 'i18n', '*.tsv')))
    print(f'语言词表 {len(files)} 份')
    for p in files:
        code = os.path.basename(p)[:-4]
        t = read_tsv(p)
        lack = keys - set(t)
        if lack:
            ok = False
            print(f'✗ {code} 缺 {len(lack)} 条，例如：{list(lack)[:3]}')
        if len(t) < len(keys):
            ok = False

    print('✓ 全部通过' if ok else '✗ 存在缺失')
    return 0 if ok else 1


if __name__ == '__main__':
    sys.exit(main())

#!/usr/bin/env python3
"""把英文界面词表机翻成目标语言，生成 lib/i18n/<code>.dart。

为什么要自己写生成器：
- 界面文案以中文原文为 key（`t('复制')`），英文词表是人工翻的，
  质量比机翻中文好；所以链路是 中文 → 英文（人工）→ 目标语言（Argos）。
- Argos 默认挂 Stanza 分句器，首次使用会联网下载模型，沙箱里直接卡死；
  界面文案几乎都是单句，用换行分句足够，于是替换成 FakeSent。
- 译文落到磁盘缓存，中断后可以续跑，不重复翻 300 条。
"""
import json
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CACHE = '/tmp/i18n_cache'
os.makedirs(CACHE, exist_ok=True)

# ---------------------------------------------------------------- 词表解析


def read_map(path):
    src = open(path, encoding='utf-8').read()
    pat = re.compile(r"^  '((?:[^'\\]|\\.)*)':\s*\n?\s*'((?:[^'\\]|\\.)*)',", re.M)
    pairs = dict(pat.findall(src))

    def unesc(s):
        return (s.replace("\\'", "'").replace('\\"', '"')
                .replace('\\n', '\n').replace('\\\\', '\\'))

    return {unesc(k): unesc(v) for k, v in pairs.items()}


def read_dart_maps(path):
    """按 `const Map<String, String> kXxxUi = {` 切块，返回 {变量名: 词表}。"""
    src = open(path, encoding='utf-8').read()
    out = {}
    for m in re.finditer(r'const Map<String, String> (k\w+Ui) = \{(.*?)\n\};', src, re.S):
        body = m.group(2)
        pat = re.compile(r"^  '((?:[^'\\]|\\.)*)':\s*'((?:[^'\\]|\\.)*)',", re.M)
        pairs = dict(pat.findall(body))

        def unesc(x):
            return (x.replace("\\'", "'").replace('\\n', '\n')
                    .replace('\\\\', '\\'))

        out[m.group(1)] = {unesc(k): unesc(v) for k, v in pairs.items()}
    return out


def collect_keys():
    keys = set()
    ui = os.path.join(ROOT, 'lib', 'ui')
    for name in os.listdir(ui):
        if not name.endswith('.dart'):
            continue
        s = open(os.path.join(ui, name), encoding='utf-8').read()
        for m in re.finditer(r"(?:L10n\.)?t\('((?:[^'\\]|\\.)*)'\)", s):
            k = m.group(1).replace("\\'", "'").replace('\\n', '\n')
            if re.search(r'[\u4e00-\u9fa5]', k) and '$' not in k:
                keys.add(k)
    # 与 check_i18n 保持一致：天赋文案也要进词表。
    p2 = os.path.join(ROOT, 'lib', 'services', 'life_sim.dart')
    if os.path.exists(p2):
        s2 = open(p2, encoding='utf-8').read()
        pat = re.compile(
            r"LifeTalent\(\s*'[^']*',\s*'([^']*)',\s*'([^']*)',\s*'([^']*)'\)")
        for m in pat.finditer(s2):
            for g in m.groups():
                if re.search(r'[\u4e00-\u9fa5]', g) and '$' not in g:
                    keys.add(g)
    return keys


# ---------------------------------------------------------------- Dart 转义


def dart_str(s):
    out = (s.replace('\\', '\\\\').replace("'", "\\'")
           .replace('$', '\\$').replace('\n', '\\n'))
    return out


# ---------------------------------------------------------------- 译文润色

LATIN = re.compile(r'^[A-Za-zÀ-ÿА-Яа-яΑ-ω]')
SENT_END = re.compile(r'[.!?。！？]$')


def polish(src, dst):
    dst = dst.strip()
    if not dst:
        return dst
    # Argos 常给单句补一个句号；原文没有就删掉，短标签不该像句子。
    if dst.endswith('.') and not src.rstrip().endswith('.'):
        dst = dst[:-1].rstrip()
    # 原文首字母大写时，译文也跟着大写（德语名词本来大写，不受影响）。
    if src[:1].isupper() and LATIN.match(dst) and dst[:1].islower():
        dst = dst[0].upper() + dst[1:]
    return dst


# ---------------------------------------------------------------- 翻译


class FakeSent:
    """单行即一句。界面文案里极少出现需要二次切分的段。"""

    def split_sentences(self, text):
        parts = [p for p in text.split('\n') if p.strip()]
        return parts or [text]


def translate_all(code, pairs, manual):
    # 繁体中文没有 en→zh-TW 的 Argos 模型。把英文机翻回中文既慢又不准，
    # 正确做法是对中文原文做简繁转换；已有译文一律保留，只补新增词条。
    if code == 'zh-TW':
        try:
            import zhconv

            def conv(s):
                return zhconv.convert(s, 'zh-tw')
        except ImportError:
            # 没装 zhconv 时退回简体原文：功能不受影响，check_i18n 仍能通过。
            def conv(s):
                return s

        path = os.path.join(ROOT, 'assets', 'i18n', 'zh-TW.tsv')
        existing = {}
        if os.path.exists(path):
            for line in open(path, encoding='utf-8').read().split('\n'):
                if '\t' in line:
                    k, v = line.split('\t', 1)
                    existing[k.replace(r'\n', '\n')] = v.replace(r'\n', '\n')
        out = {k: existing.get(k) or conv(k) for k in pairs}
        out.update(manual)
        return out

    import argostranslate.translate as T

    path = os.path.join(CACHE, f'{code}.json')
    done = json.load(open(path, encoding='utf-8')) if os.path.exists(path) else {}
    # 空串也算没翻出来：Argos 偶尔对个别长句返回空，若不重翻，
    # write_tsv 会跳过这一行，check_i18n 就会报缺词条。
    todo = [k for k in pairs if not done.get(k)]
    if todo:
        tr = T.get_translation_from_codes('en', code)
        tr.underlying.sentencizer = FakeSent()
        for i, k in enumerate(todo):
            try:
                done[k] = polish(pairs[k], tr.translate(pairs[k]))
            except Exception as e:  # noqa: BLE001
                print(f'  ! {code} {pairs[k][:40]!r} {e}', flush=True)
                done[k] = pairs[k]
            if i % 40 == 0:
                json.dump(done, open(path, 'w', encoding='utf-8'),
                          ensure_ascii=False, indent=0)
                print(f'  {code} {i}/{len(todo)}', flush=True)
        json.dump(done, open(path, 'w', encoding='utf-8'),
                  ensure_ascii=False, indent=0)
    out = dict(done)
    out.update(manual)  # 人工短语优先，机翻不覆盖
    # 机翻仍是空串时回退英文原文，绝不让词表缺行。
    for k in list(out):
        if not out[k]:
            out[k] = pairs.get(k, k)
    return out


def write_tsv(code, table, keys):
    """输出 `assets/i18n/<code>.tsv`：中文原文 \t 译文。

    选 TSV 不选 JSON / Dart：体积小一半，diff 一行一条，改一条译文
    不会在 PR 里炸出满屏括号。
    """
    out = os.path.join(ROOT, 'assets', 'i18n')
    os.makedirs(out, exist_ok=True)
    lines = []
    for k in sorted(keys, key=lambda x: (len(x), x)):
        v = table.get(k)
        if not v:
            continue
        # 换行在 TSV 里会断行，转成字面 \n，运行时还原。
        lines.append(k.replace('\n', r'\n') + '\t' + v.replace('\n', r'\n'))
    path = os.path.join(out, f'{code}.tsv')
    open(path, 'w', encoding='utf-8').write('\n'.join(lines) + '\n')
    return path


def main():
    targets = sys.argv[2:] if len(sys.argv) > 2 else []
    mode = sys.argv[1] if len(sys.argv) > 1 else 'gen'

    en = read_map(os.path.join(ROOT, 'lib', 'i18n', 'en.dart'))
    core = os.path.join(ROOT, 'lib', 'i18n', 'core.dart')
    core_maps = read_dart_maps(core) if os.path.exists(core) else {}
    keys = collect_keys()
    pairs = {k: en[k] for k in keys if k in en}
    print(f'keys {len(keys)} 有英文 {len(pairs)} 核心块 {list(core_maps)}', flush=True)

    if mode == 'check':
        return

    for code in targets:
        print(f'== {code}', flush=True)
        var = 'k' + code.replace('-', '_').title().replace('_', '') + 'Ui'
        table = translate_all(code, pairs, core_maps.get(var, {}))
        path = write_tsv(code, table, keys)
        print(f'   -> {path} {len(table)} 条', flush=True)


if __name__ == '__main__':
    main()

import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:ai_agent_app/models/models.dart';
import 'package:ai_agent_app/services/agent_script.dart';
import 'package:ai_agent_app/services/agent_tools.dart';
import 'package:ai_agent_app/services/agent_workspace.dart';
import 'package:ai_agent_app/services/device_bridge.dart';
import 'package:ai_agent_app/services/speech_model.dart';
import 'package:ai_agent_app/state/app_state.dart';
import 'package:ai_agent_app/ui/source_browser.dart';

late Directory _tmp;
late AgentWorkspace _ws;

Future<void> _fresh() async {
  _tmp = await Directory.systemTemp.createTemp('aigent_ws_test_');
  _ws = AgentWorkspace(_tmp.path);
  await _ws.ensure();
}

void main() {
  setUp(_fresh);
  tearDown(() async {
    if (_tmp.existsSync()) await _tmp.delete(recursive: true);
  });

  group('隔离工作区：路径逃逸必须被拒绝', () {
    test('绝对路径 / 盘符 / .. / 隐藏文件 / 系统保留目录全部拒绝', () async {
      for (final bad in [
        '/etc/passwd',
        'C:/Windows/win.ini',
        '../outside.txt',
        'notes/../../outside.txt',
        '.hidden',
        '.trash/abc',
        'agent_log.jsonl',
        'notes/.secret',
      ]) {
        expect(
          () => _ws.read(bad),
          throwsA(isA<WorkspaceException>()),
          reason: '路径 $bad 不该被放行',
        );
      }
    });

    test('写 / 读 / 追加 / 列目录', () async {
      final a = await _ws.write('notes/a.txt', '第一行');
      expect(a, contains('已写入'));
      expect(await _ws.read('notes/a.txt'), '第一行');
      await _ws.append('notes/a.txt', '，第二行');
      expect(await _ws.read('notes/a.txt'), '第一行，第二行');
      final entries = await _ws.list('notes');
      expect(entries.length, 1);
      expect(entries.first.rel, 'notes/a.txt');
      expect(entries.first.isDir, isFalse);
    });

    test('符号链接指向工作区之外时拒绝读取', () async {
      final outside = File('${_tmp.path}_outside.txt');
      await outside.writeAsString('secret');
      addTearDown(() async {
        if (outside.existsSync()) await outside.delete();
      });
      Link('${_tmp.path}/link.txt').createSync(outside.path);
      expect(
        () => _ws.read('link.txt'),
        throwsA(isA<WorkspaceException>()),
      );
    });
  });

  group('隔离工作区：文件永不丢失', () {
    test('覆盖写自动备份旧版，删除进回收站且可恢复回原子目录', () async {
      await _ws.write('notes/a.txt', 'v1');
      await _ws.write('notes/a.txt', 'v2');
      expect(await _ws.read('notes/a.txt'), 'v2');

      var trash = await _ws.trashList();
      expect(trash.length, 1, reason: '覆盖前必须先备份 v1');
      expect(trash.first.name, contains('notes__a.txt'));

      final msg = await _ws.delete('notes/a.txt');
      expect(msg, contains('未真正删除'));
      expect(File('${_tmp.path}/notes/a.txt').existsSync(), isFalse);
      trash = await _ws.trashList();
      expect(trash.length, 2);

      // 恢复最近一次删除，应该回到 notes/ 而不是根目录。
      final restored = await _ws.restore(trash.first.name);
      expect(restored, contains('notes'));
      expect(await _ws.read('notes/a.txt'), 'v2');
      expect(File('${_tmp.path}/a.txt').existsSync(), isFalse);
    });

    test('回收站可永久清空，清空后列表为空', () async {
      await _ws.write('a.txt', 'x');
      await _ws.delete('a.txt');
      expect((await _ws.trashList()).length, 1);
      final msg = await _ws.clearTrash();
      expect(msg, contains('已永久清空'));
      expect(await _ws.trashList(), isEmpty);
    });

    test('单文件超过 2 MB 拒绝写入', () async {
      final big = 'x' * (AgentWorkspace.maxFileBytes + 1);
      expect(
        () => _ws.write('big.txt', big),
        throwsA(isA<WorkspaceException>()),
      );
      expect(File('${_tmp.path}/big.txt').existsSync(), isFalse);
    });

    test('用量统计不含回收站与日志文件', () async {
      await _ws.write('a.txt', 'hello');
      await _ws.write('b.txt', 'world');
      await _ws.delete('b.txt');
      final u = await _ws.usage();
      expect(u.files, 1);
      expect(u.bytes, 5);
      expect(u.trashFiles, 1);
    });
  });

  group('审计日志', () {
    test('每次动作写入 jsonl 并能读回', () async {
      for (var i = 0; i < 3; i++) {
        await _ws.log(AgentLogEntry(
          at: 1700000000000 + i,
          tool: 'agent.workspace.write',
          detail: '第 $i 次写入',
          ok: i != 1,
        ));
      }
      final log = await _ws.readLog();
      expect(log.length, 3);
      expect(log.first.detail, '第 2 次写入', reason: '最新一条排最前');
      expect(log.last.ok, isTrue);
      expect(log[1].ok, isFalse);
    });
  });

  group('受限任务脚本', () {
    test('能写多行文档、追加、读取、列目录并插值变量', () async {
      final r = await AgentScriptRunner(_ws).run('''
# 整理今天的笔记
print 开始整理 \${model}
write notes/plan.md <<<
# 计划
设备 \${model}
>>>
append notes/plan.md 追加一行
read notes/plan.md
list notes
''', deviceModel: 'Pixel 8');
      expect(r.ok, isTrue, reason: r.error ?? r.output);
      expect(r.output, contains('开始整理 Pixel 8'));
      expect(r.output, contains('已写入'));
      expect(await _ws.read('notes/plan.md'), contains('# 计划'));
      expect(await _ws.read('notes/plan.md'), contains('追加一行'));
    });

    test('未知指令与超长脚本都拒绝执行', () async {
      final bad = await AgentScriptRunner(_ws).run('rm -rf /\nprint hi');
      expect(bad.ok, isFalse);
      expect(bad.error, contains('未知指令'));

      final long = await AgentScriptRunner(_ws)
          .run(List.filled(220, 'print x').join('\n'));
      expect(long.ok, isFalse);
      expect(long.error, contains('行上限'));
    });

    test('脚本里的越界路径同样被工作区拦截', () async {
      final r = await AgentScriptRunner(_ws).run('write ../evil.txt hi');
      expect(r.ok, isFalse);
      expect(r.output, anyOf(contains('..'), contains('越出')));
      expect(File('${_tmp.path}_evil.txt').existsSync(), isFalse);
    });
  });

  group('本机工具解析与授权', () {
    test('识别 fenced / 内联 / 裸短名，不误吞插件工具', () {
      final a = parseAgentToolCall(
          '```tool\n{"tool":"agent.app.open","arguments":{"name":"微信"}}\n```');
      expect(a?['tool'], 'agent.app.open');
      expect((a?['arguments'] as Map)['name'], '微信');

      final b = parseAgentToolCall(
          '好的，我来打开\n{"tool":"device.info","arguments":{}}');
      expect(b?['tool'], 'agent.device.info');

      expect(parseAgentToolCall(
          '{"tool":"getWeather","arguments":{"city":"北京"}}'), isNull);
      expect(parseAgentToolCall('只是一段普通回答'), isNull);
    });

    test('工具全集 id 唯一，只读工具无需确认', () {
      final ids = kAgentTools.map((t) => t.id).toSet();
      expect(ids.length, kAgentTools.length);
      expect(kAgentTools.length, greaterThanOrEqualTo(20));
      for (final t in kAgentTools) {
        if (t.risk == AgentRisk.read) {
          expect(t.needsConfirmation, isFalse, reason: t.id);
          expect(t.grant, isEmpty, reason: t.id);
        } else {
          expect(t.needsConfirmation, isTrue, reason: t.id);
          expect(t.grant, isNotEmpty, reason: t.id);
        }
      }
    });

    test('授权快照按组生效，标签可读', () {
      const g = AgentGrant(workspace: true);
      expect(g.allows(''), isTrue);
      expect(g.allows('workspace'), isTrue);
      expect(g.allows('external'), isFalse);
      expect(g.allows('system'), isFalse);
      expect(g.allows('network'), isFalse);
      expect(AgentGrant.labelOf('system'), '日历与闹钟');
    });

    test('未授权动作不执行，返回需要哪一组授权', () async {
      final rt = AgentRuntime(
        workspace: _ws,
        grant: const AgentGrant(),
        deviceInfo: DeviceInfo.fallback(),
        confirmEach: false,
      );
      final e = await rt.execute(
          'agent.workspace.write', {'path': 'a.txt', 'content': 'x'});
      expect(e.ok, isFalse);
      expect(e.missingGrant, 'workspace');
      expect(File('${_tmp.path}/a.txt').existsSync(), isFalse);
      expect(await _ws.readLog(), isNotEmpty, reason: '拒绝也要留痕');
    });

    test('拒绝确认后按「用户拒绝」回灌，不产生副作用', () async {
      final rt = AgentRuntime(
        workspace: _ws,
        grant: const AgentGrant(workspace: true),
        deviceInfo: DeviceInfo.fallback(),
        confirmEach: true,
        confirm: (_) async => false,
      );
      final e = await rt.execute(
          'agent.workspace.write', {'path': 'a.txt', 'content': 'x'});
      expect(e.ok, isFalse);
      expect(e.declined, isTrue);
      expect(e.asToolResult, contains('用户拒绝'));
      expect(File('${_tmp.path}/a.txt').existsSync(), isFalse);
    });

    test('授权 + 允许后真的把文件写进工作区', () async {
      final rt = AgentRuntime(
        workspace: _ws,
        grant: const AgentGrant(workspace: true),
        deviceInfo: DeviceInfo.fallback(),
        confirmEach: true,
        confirm: (_) async => true,
      );
      final e = await rt.execute(
          'agent.workspace.write', {'path': 'result.md', 'content': '# 结果'});
      expect(e.ok, isTrue);
      expect(await _ws.read('result.md'), '# 结果');
      expect(e.asToolResult, contains('[工具 写文件 执行结果]'));
    });

    test('设备信息只读工具始终可用', () async {
      final rt = AgentRuntime(
        workspace: _ws,
        grant: const AgentGrant(),
        deviceInfo: DeviceInfo.fallback(),
        confirmEach: true,
        confirm: (_) async => false,
      );
      final e = await rt.execute('agent.device.info', {});
      expect(e.ok, isTrue);
      expect(e.message, contains('设备'));
    });

    test('内网 / 回环 / 元数据主机被拦，公网域名放行', () {
      for (final h in [
        '127.0.0.1',
        '10.0.0.5',
        '192.168.1.1',
        '172.16.3.4',
        '169.254.169.254',
        'localhost',
        'metadata.google.internal',
        'nas.local',
      ]) {
        expect(AgentRuntime.isBlockedHost(h), isTrue, reason: h);
      }
      for (final h in ['example.com', 'api.openai.com', '93.184.216.34']) {
        expect(AgentRuntime.isBlockedHost(h), isFalse, reason: h);
      }
    });
  });

  group('设备信息兜底与源码包', () {
    test('没有原生通道时仍给出完整设备摘要', () {
      final info = DeviceInfo.fallback();
      expect(info.fromDevice, isFalse);
      expect(info.rows.length, greaterThanOrEqualTo(10));
      expect(info.promptSummary, contains('设备'));
      expect(info.promptSummary, contains('系统'));
    });

    test('源码包解析保留路径、行数与内容', () {
      final bundle = SourceBundle.parse(jsonEncode({
        'version': '4.7.0',
        'generated': '2026-11-07',
        'fileCount': 2,
        'totalLines': 3,
        'files': [
          {'path': 'lib/main.dart', 'lines': 2, 'size': 10, 'content': 'void main() {}\n'},
          {'path': 'pubspec.yaml', 'lines': 1, 'size': 5, 'content': 'name: x'},
        ],
      }));
      expect(bundle.version, '4.7.0');
      expect(bundle.files.length, 2);
      expect(bundle.files.first.content, contains('void main'));
      expect(bundle.totalLines, 3);
    });
  });

  group('设置与形象默认值', () {
    test('智能体设置完整往返，步数被夹在合理区间', () {
      final s = AppSettings()
        ..agentEnabled = true
        ..agentConfirmEach = false
        ..agentAllowWorkspace = false
        ..agentAllowExternal = true
        ..agentAllowSystem = true
        ..agentAllowNetwork = true
        ..agentRiskAck = true
        ..agentMaxSteps = 99;
      final back = AppSettings()
        ..load(jsonDecode(s.encode()) as Map<String, dynamic>);
      expect(back.agentEnabled, isTrue);
      expect(back.agentConfirmEach, isFalse);
      expect(back.agentAllowWorkspace, isFalse);
      expect(back.agentAllowExternal, isTrue);
      expect(back.agentAllowSystem, isTrue);
      expect(back.agentAllowNetwork, isTrue);
      expect(back.agentRiskAck, isTrue);
      expect(back.agentMaxSteps, 8);
    });

    test('旧配置升级后智能体默认关闭，不额外获得任何权限', () {
      final s = AppSettings()..load(<String, dynamic>{});
      expect(s.agentEnabled, isFalse);
      expect(s.agentConfirmEach, isTrue);
      expect(s.agentAllowWorkspace, isTrue, reason: '沙箱内文件默认放开');
      expect(s.agentAllowExternal, isFalse);
      expect(s.agentAllowSystem, isFalse);
      expect(s.agentAllowNetwork, isFalse);
      expect(s.agentMaxSteps, 4);
    });

    test('默认不预置任何形象，没设置就是空列表', () {
      final list = defaultPersonas();
      expect(list, isEmpty);
      // 内部占位只为让取值不空指针，不进列表、不带文案。
      expect(nonePersona().name, isEmpty);
      expect(nonePersona().builtin, isTrue);
      expect(nonePersona().glyph, isEmpty, reason: '空 glyph 才会显示 App 图标');
    });

    test('旧配置里的内置人设会被清掉，自建形象保留', () {
      final s = AppSettings()
        ..load(<String, dynamic>{
          'personas': [
            {
              'id': 'persona_default',
              'name': 'Aigent',
              'glyph': 'A',
              'builtin': true,
            },
            {'id': 'persona_yan', 'name': '砚', 'glyph': '砚', 'builtin': true},
            {'id': 'persona_muse', 'name': 'Muse', 'glyph': 'M', 'builtin': true},
            {
              'id': 'persona_atlas',
              'name': 'Atlas',
              'glyph': 'A',
              'builtin': true
            },
            {'id': 'persona_mine', 'name': '牛來', 'glyph': '牛'},
          ],
          'activePersonaId': 'persona_yan',
        });
      expect(s.personas.length, 1);
      expect(s.personas.single.name, '牛來');
      // 原来选中的是被删掉的「砚」，回落到唯一保留的自建形象。
      expect(s.activePersonaId, 'persona_mine');
    });

    test('关闭智能体时 System Prompt 不含任何工具信息', () {
      final st = AppState()..settings = AppSettings();
      st.settings.ensurePresets();
      st.conversations = [Conversation(id: 'c1', title: 'A')];
      st.activeId = 'c1';
      final p = Persona(id: 'p', name: '测试', tagline: '', roleHint: '');
      final off = st.buildSystemPrompt(query: '你好', persona: p);
      expect(off.contains('[本机能力]'), isFalse);
      expect(off.contains('agent.device.info'), isFalse);

      st.settings.agentEnabled = true;
      final on = st.buildSystemPrompt(query: '你好', persona: p);
      expect(on, contains('[本机能力]'));
      expect(on, contains('agent.device.info'));
      expect(on, contains('隔离工作区'));
      expect(on, contains('硬边界'));
      expect(on, contains('设备信息'));
    });
  });

  group('v4.8 端侧离线语音包', () {
    test('未安装时状态安全回落，不抛异常', () async {
      final st = await SpeechModel.status();
      expect(st.ready, isFalse);
      expect(st.sizeLabel, '未下载');
    });

    test('体积文案按 MB 展示，空模型不显示 0.0 MB', () {
      expect(const SpeechModelStatus(ready: true).sizeLabel, '未下载');
      expect(
        const SpeechModelStatus(ready: true, bytes: 90 * 1024 * 1024).sizeLabel,
        '90.0 MB',
      );
    });

    test('模型目录名与引擎 id 稳定，避免升级后找不到已下载的包', () {
      expect(SpeechModel.dirName, 'vosk-model-small-cn-0.22');
      expect(SpeechModel.engineId, 'vosk-cn');
      expect(SpeechModel.downloadUrl, endsWith('.zip'));
    });
  });
}

import 'dart:async';
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:provider/provider.dart';
import 'package:ai_agent_app/models/models.dart';
import 'package:ai_agent_app/services/model_brand.dart';
import 'package:ai_agent_app/services/model_probe.dart';
import 'package:ai_agent_app/state/app_state.dart';
import 'package:ai_agent_app/ui/model_picker_sheet.dart';

void main() {
  group('模型品牌识别', () {
    test('常见模型 ID 都落到对应官方品牌', () {
      const cases = <String, String>{
        'gpt-4o': 'openai',
        'openai/gpt-4o-mini': 'openai',
        'o1-preview': 'openai',
        'claude-3-5-sonnet-20241022': 'anthropic',
        'anthropic/claude-3-opus': 'anthropic',
        'gemini-2.0-flash': 'google',
        'google/gemini-1.5-pro': 'google',
        'gemma-2-9b': 'google',
        'deepseek-chat': 'deepseek',
        'deepseek-ai/DeepSeek-V3': 'deepseek',
        'Qwen/Qwen2.5-72B-Instruct': 'qwen',
        'qwq-32b': 'qwen',
        'glm-4-plus': 'zhipu',
        'chatglm3-6b': 'zhipu',
        'doubao-1.5-pro': 'doubao',
        'kimi-k2': 'kimi',
        'moonshot-v1-8k': 'kimi',
        'mistral-large': 'mistral',
        'meta-llama/Llama-3.3-70B': 'meta',
        'grok-2': 'grok',
        'hunyuan-turbo': 'hunyuan',
        'ernie-4.0': 'baidu',
        'command-r-plus': 'cohere',
        'phi-3-medium': 'microsoft',
        'sonar-reasoning': 'perplexity',
        'openrouter/auto': 'openrouter',
        'siliconflow/my-model': 'siliconflow',
        'my-private-model': 'generic',
      };
      for (final e in cases.entries) {
        expect(resolveModelBrand(e.key).key, e.value,
            reason: '${e.key} 应识别为 ${e.value}');
      }
    });

    test('模型本身的品牌优先于承载它的网关', () {
      // groq 上跑的是 Meta 的 Llama，图标应该用 Meta 官方标记。
      expect(resolveModelBrand('groq/llama-3.3-70b').key, 'meta');
      expect(resolveModelBrand('openrouter/openai/gpt-4o').key, 'openai');
      expect(resolveModelBrand('siliconflow/Qwen/Qwen2.5-72B').key, 'qwen');
    });

    test('认不出来时统一落 generic，不留下空图标或黑白图标', () {
      final b = resolveModelBrand('some-random-id-2026');
      expect(b.key, 'generic');
      expect(b.label.isNotEmpty, isTrue);
      expect(b.asset, 'assets/brand_models/generic.png');
      expect(resolveModelBrand('').key, 'generic');
    });

    test('每个品牌都真的有 256px 高清 PNG 资源', () {
      const pngHeader = [137, 80, 78, 71, 13, 10, 26, 10];
      for (final key in kBrandKeys) {
        final f = File('assets/brand_models/$key.png');
        expect(f.existsSync(), isTrue, reason: '缺少 $key.png');
        final bytes = f.readAsBytesSync();
        expect(bytes.length, greaterThan(200), reason: '$key.png 太小');
        expect(bytes.sublist(0, 8), pngHeader, reason: '$key.png 不是 PNG');
      }
    });

    test('规则表不会返回没有资源的品牌 key', () {
      for (final id in [
        'gpt-4o',
        'claude-3-5-sonnet',
        'gemini-2.0-flash',
        'deepseek-chat',
        'Qwen2.5-72B',
        'llama-3.3',
        'my-model',
      ]) {
        expect(kBrandKeys.contains(resolveModelBrand(id).key), isTrue);
      }
    });
  });

  group('模型可用性检测', () {
    test('结果标题与耗时可读', () {
      const ok = ModelProbe(ok: true, ms: 812, detail: '响应正常');
      expect(ok.headline, '当前模型可用');
      expect(ok.timing, '812ms');
      const bad = ModelProbe(ok: false, ms: 0, detail: '还没有选择模型');
      expect(bad.headline, '当前模型不可用');
    });

    test('常见网关错误翻成中文原因', () {
      expect(describeProbeError(TimeoutException('x')), contains('超时'));
      expect(describeProbeError(StateError('401 Unauthorized')),
          contains('鉴权失败'));
      expect(describeProbeError(StateError('429 Too Many Requests')),
          contains('限流'));
      expect(describeProbeError(StateError('404 Not Found')), contains('404'));
      expect(describeProbeError(StateError('SocketException: failed')),
          contains('连不上服务器'));
    });

    test('回复摘要截断且不留换行', () {
      expect(probeReplyPreview('  好\n'), '好');
      expect(
          probeReplyPreview(
              '这是一段明显超过二十四字的很长很长很长很长很长很长很长的回复内容'),
          endsWith('…'));
      expect(probeReplyPreview('   '), isEmpty);
    });
  });

  group('v4.12 简洁图标列表', () {
    testWidgets('模型弹层只剩单行图标列表，管理动作不在主页', (tester) async {
      final st = AppState()..settings = AppSettings();
      st.settings.cachedModels = [
        'gpt-4o',
        'claude-3-5-sonnet',
        'deepseek-chat',
      ];
      await tester.pumpWidget(ChangeNotifierProvider<AppState>.value(
        value: st,
        child: MaterialApp(
          home: Scaffold(
            body: ModelPickerSheet(dark: false, st: st),
          ),
        ),
      ));
      await tester.pumpAndSettle();

      expect(find.text('选择模型'), findsOneWidget);
      // 三行各一个官方图标（BrandIcon 内部是 Image.asset）。
      expect(find.byType(Image), findsNWidgets(3));
      // 简洁化后不再有 chips / 系列速查 / 供应商小字 / 底部操作栏。
      expect(find.text('按系列速查'), findsNothing);
      expect(find.text('常用模型'), findsNothing);
      expect(find.text('Anthropic Claude'), findsNothing);
      expect(find.text('检测当前模型'), findsNothing);
      expect(find.text('刷新列表'), findsNothing);
      expect(find.text('接口设置'), findsNothing);
    });
  });
}

import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:provider/provider.dart';
import 'package:shared_preferences/shared_preferences.dart';

import 'package:ai_agent_app/i18n.dart';
import 'package:ai_agent_app/models/models.dart';
import 'package:ai_agent_app/services/feature_store.dart';
import 'package:ai_agent_app/services/life_sim.dart';
import 'package:ai_agent_app/services/roundtable.dart';
import 'package:ai_agent_app/state/app_state.dart';
import 'package:ai_agent_app/ui/life_screen.dart';
import 'package:ai_agent_app/ui/roundtable_screen.dart';

void main() {
  group('新功能本地存档', () {
    test('会议与人生存档可往返，且不含明文密钥', () async {
      final mem = <String, String>{};
      final store = FeatureStore(memory: mem);
      final m = Meeting(
        id: 'm1',
        topic: '议题',
        seats: [
          Seat(
              id: 's',
              name: '甲',
              baseUrl: 'https://x/v1',
              apiKey: 'sk-super-secret',
              model: 'model-a')
        ],
      );
      m.turns.add(MeetingTurn(
          seatId: 's', seatName: '甲', model: 'model-a', round: 1, content: '观点'));
      var all = await store.upsertMeeting(m);
      expect(all.length, 1);
      expect(mem.values.join(), isNot(contains('sk-super-secret')));
      final loaded = (await store.loadMeetings()).single;
      expect(loaded.topic, '议题');
      expect(loaded.turns.single.content, '观点');
      expect(loaded.seats.single.apiKey, isEmpty); // 密钥不落盘

      final c = LifeCharacter(id: 'l1', name: '林知远');
      c.events.add(parseEventJson('{"title":"一件事","story":"叙述"}', 16, 2026));
      final lives = await store.upsertLife(c);
      expect(lives.length, 1);
      expect((await store.loadLives()).single.events.single.title, '一件事');

      await store.deleteMeeting('m1');
      await store.deleteLife('l1');
      expect(await store.loadMeetings(), isEmpty);
      expect(await store.loadLives(), isEmpty);
    });

    test('同 id 覆盖、按最近插入排前', () async {
      final store = FeatureStore(memory: <String, String>{});
      await store.upsertMeeting(Meeting(id: 'a', topic: '旧'));
      await store.upsertMeeting(Meeting(id: 'b', topic: '新'));
      await store.upsertMeeting(Meeting(id: 'a', topic: '改过'));
      final all = await store.loadMeetings();
      expect(all.length, 2);
      expect(all.first.topic, '改过');
    });
  });

  group('多语言词条', () {
    tearDown(() => L10n.useTable('zh', const {}));

    test('英文界面里新功能文案不含中文', () {
      L10n.lang = 'en';
      for (final k in ['AI 圆桌会议', '模拟人生', '开始会议', '会议结论', '开始这一生']) {
        expect(t(k), isNot(contains(RegExp(r'[\u4e00-\u9fa5]'))), reason: k);
      }
      expect(t('AI 圆桌会议'), 'AI Roundtable');
      expect(t('模拟人生'), 'Life Simulator');
    });

    test('38 份词表都覆盖新功能词条', () {
      const keys = ['AI 圆桌会议', '模拟人生', '开始会议', '会议结论', '开始这一生'];
      final files = Directory('assets/i18n')
          .listSync()
          .whereType<File>()
          .where((f) => f.path.endsWith('.tsv'))
          .toList();
      expect(files.length, 38);
      for (final f in files) {
        final table = L10n.parseTsv(f.readAsStringSync());
        for (final k in keys) {
          expect(table.containsKey(k), isTrue,
              reason: '${f.path} 缺少 $k');
          expect(table[k], isNot(equals(k)));
        }
        // 每份词表都必须是干净的一行一条
        for (final line in f.readAsStringSync().split('\n')) {
          if (line.trim().isNotEmpty) {
            expect(line.contains('\t'), isTrue, reason: '${f.path} 有坏行');
          }
        }
      }
    });
  });

  group('页面冒烟', () {
    testWidgets('圆桌会议页能打开并展示议题与席位', (tester) async {
      SharedPreferences.setMockInitialValues({});
      final st = AppState()..settings = AppSettings();
      await tester.pumpWidget(ChangeNotifierProvider<AppState>.value(
        value: st,
        child: const MaterialApp(home: RoundtableScreen()),
      ));
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 50));
      expect(find.text('AI 圆桌会议'), findsOneWidget);
      expect(find.text('会议议题'), findsOneWidget);
      expect(find.text('开始会议'), findsOneWidget);
      expect(tester.takeException(), isNull);
    });

    testWidgets('模拟人生页能打开并展示创建表单', (tester) async {
      SharedPreferences.setMockInitialValues({});
      final st = AppState()..settings = AppSettings();
      await tester.pumpWidget(ChangeNotifierProvider<AppState>.value(
        value: st,
        child: const MaterialApp(home: LifeScreen()),
      ));
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 50));
      expect(find.text('模拟人生'), findsOneWidget);
      expect(find.text('创建角色'), findsOneWidget);
      expect(find.text('开始这一生'), findsOneWidget);
      expect(tester.takeException(), isNull);
    });

    testWidgets('模拟人生可以两级下钻选出生地，并抽一次天赋', (tester) async {
      SharedPreferences.setMockInitialValues({});
      final st = AppState()..settings = AppSettings();
      await tester.pumpWidget(ChangeNotifierProvider<AppState>.value(
        value: st,
        child: const MaterialApp(home: LifeScreen()),
      ));
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 60));

      // 出生地：先选省，点进去再选市，逐层返回。
      await tester.tap(find.text('选择出生地'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('河北'));
      await tester.pumpAndSettle();
      expect(find.text('河北 · 选择城市'), findsOneWidget);
      expect(find.text('石家庄'), findsOneWidget);
      await tester.tap(find.text('石家庄'));
      await tester.pumpAndSettle();
      expect(find.text('河北 · 石家庄'), findsOneWidget);

      // 天赋抽签：抽完换成结果卡，按钮不再出现（一局只有一次）。
      expect(find.text('抽取天赋'), findsOneWidget);
      await tester.ensureVisible(find.text('抽取天赋'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('抽取天赋'));
      await tester.pumpAndSettle();
      expect(find.text('抽取天赋'), findsNothing);
      expect(find.text('天赋抽签'), findsOneWidget);
      expect(tester.takeException(), isNull);
    });
  });
}

