  s.model = 'model-a';
  s.cachedModels = ['model-a', 'model-a2'];
  s.syncActive();
  s.profiles.add(ApiProfile(
    id: 'b',
    name: 'B 服务',
    baseUrl: 'https://b.example/v1',
    model: 'model-b',
    cachedModels: ['model-b', 'model-b2'],
