import 'package:dio/dio.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:ai_agent_app/services/life_sim.dart';
import 'package:ai_agent_app/services/llm_client.dart';
import 'package:ai_agent_app/services/roundtable.dart' show CompleteFn;

const _eventJson = '{"title":"高考那年","story":"教室里的风扇转得很慢，'
    '你盯着志愿表，第一次觉得未来真的要自己选。",'
    '"choices":[{"text":"去大城市读书","hint":"机会多"},'
    '{"text":"留在家乡","hint":"安稳"},{"text":"复读一年","hint":"不甘心"}],'
    '"years":3}';

const _resolveJson = '{"outcome":"你去了大城市，起初很难，后来站住了脚。",'
    '"deltas":{"mind":8,"wealth":-4,"joy":3},"years":4}';

SeatLike _conn() => const SeatLike(
    baseUrl: 'https://example.com/v1', apiKey: 'k', model: 'model-x');

LifeCharacter _char() => LifeCharacter(
      id: 'l1',
      name: '林知远',
      gender: '女',
      era: kEraOptions.first,
      goal: kGoalOptions.first,
      birthYear: 2010,
      age: 16,
    );

void main() {
  group('属性结算', () {
    test('增减后夹在 0–100', () {
      final s = LifeStats(health: 5, wealth: 98);
      final out = applyDeltas(s, {'health': -20, 'wealth': 30, 'mind': 7});
      expect(out.health, 0);
      expect(out.wealth, 100);
      expect(out.mind, 62);
      // 原对象不被改动
      expect(s.health, 5);
    });

    test('未知属性被忽略', () {
      final out = applyDeltas(LifeStats(), {'nonexistent': 999});
      expect(out.toMap(), LifeStats().toMap());
    });
  });

  group('模型 JSON 解析容错', () {
    test('抠出代码块里的 JSON', () {
      final j = extractJsonObject('好的，结果如下：\n```json\n$_eventJson\n```\n希望有用');
      expect(j['title'], '高考那年');
    });

    test('前后有废话也能解析', () {
      final j = extractJsonObject('前言\n{"a":1,"b":"x"}\n后记');
      expect(j['a'], 1);
      expect(j['b'], 'x');
    });

    test('完全没有 JSON 时返回空表', () {
      expect(extractJsonObject('模型拒绝回答'), isEmpty);
      expect(extractJsonObject('{ 坏的 json'), isEmpty);
    });

    test('事件解析：正常结构', () {
      final e = parseEventJson(_eventJson, 18, 2028);
      expect(e.title, '高考那年');
      expect(e.choices.length, 3);
      expect(e.choices.first.hint, '机会多');
      expect(e.years, 3);
      expect(e.resolved, isFalse);
    });

    test('事件解析：脏输入给可继续玩的兜底', () {
      final e = parseEventJson('抱歉我无法生成', 20, 2030);
      expect(e.choices.length, 2);
      expect(e.story.isNotEmpty, isTrue);
      // 兜底也给一个正常的章节跨度，不会退化成「一年一章」的流水账。
      expect(e.years, 5);
      expect(e.age, 25);
    });

    test('选项最多 3 个，章节跨度夹在 3–9 年', () {
      const raw = '{"choices":["A","B","C","D"],"years":99}';
      final e = parseEventJson(raw, 20, 2030);
      expect(e.choices.length, 3);
      expect(e.years, 9);
      expect(e.startAge, 20);
      expect(e.age, 29);
      expect(e.spanLabel, '20 → 29');
    });

    test('跨度太小会被抬到 3 年，接近寿命上限时收窄', () {
      expect(parseEventJson('{"years":1}', 20, 2030).years, 3);
      final late = parseEventJson('{"years":9}', 78, 2088);
      expect(late.age, kMaxAge);
      expect(late.years, kMaxAge - 78);
    });

    test('结果解析：只接受已知属性且单项受限', () {
      final r = parseResolveJson(_resolveJson);
      expect(r.outcome, contains('大城市'));
      expect(r.deltas['mind'], 8);
      expect(r.deltas['wealth'], -4);
      expect(r.years, 4);
      final wild = parseResolveJson('{"deltas":{"health":999,"unknown":50}}');
      expect(wild.deltas['health'], 30);
      expect(wild.deltas.containsKey('unknown'), isFalse);
    });

    test('传记解析：末行数字是评分', () {
      final r = parseFinale('平凡却认真的一生。\n他没成为谁，却没丢了自己。\n\n78');
      expect(r.score, 78);
      expect(r.text, contains('平凡'));
      expect(r.text, isNot(contains('78')));
      final bad = parseFinale('只有一行文字');
      expect(bad.score, 60);
      expect(bad.text, '只有一行文字');
    });
  });

  group('角色与存档', () {
    test('JSON 往返保留事件、属性与结局', () {
      final c = _char();
      final e = parseEventJson(_eventJson, 18, 2028);
      e.chosenIndex = 0;
      e.outcome = '去了大城市';
      e.deltas = {'mind': 8};
      c.events.add(e);
      c.age = 22;
      c.stats = applyDeltas(c.stats, {'mind': 8});
      c.epitaph = '一段评语';
      c.score = 81;
      c.ended = true;
      final back = LifeCharacter.fromJson(c.toJson());
      expect(back.name, '林知远');
      expect(back.age, 22);
      expect(back.events.single.title, '高考那年');
      expect(back.events.single.chosenIndex, 0);
      expect(back.stats.mind, 63);
      expect(back.score, 81);
      expect(back.ended, isTrue);
    });

    test('履历导出含结局与评分', () {
      final c = _char()..ended = true..score = 88..epitaph = '一生清澈。';
      c.events.add(parseEventJson(_eventJson, 18, 2028));
      final md = c.toMarkdown();
      expect(md, contains('# 林知远的一生'));
      expect(md, contains('高考那年'));
      expect(md, contains('盖棺定论'));
      expect(md, contains('88'));
    });

    test('到寿 / 健康归零 / 事件封顶都判定结束', () {
      final a = _char()..age = kMaxAge;
      expect(a.over, isTrue);
      final b = _char()..stats = LifeStats(health: 0);
      expect(b.over, isTrue);
      final d = _char()..ended = true;
      expect(d.over, isTrue);
      expect(_char().over, isFalse);
    });
  });

  group('人生引擎', () {
    CompleteFn responder() => (LlmRequest req, {CancelToken? cancel}) async {
          final user = '${req.messages.last['content']}';
          if (user.contains('请写下一章')) return _eventJson;
          if (user.contains('请判定这个选择的后果')) return _resolveJson;
          return '这是他平凡又认真的一生，没成为谁，却没丢了自己。\n76';
        };

    test('事件 → 抉择 → 属性与年龄推进', () async {
      final c = _char();
      var changes = 0;
      final engine = LifeEngine(complete: responder(), onChanged: () => changes++);
      final e = await engine.nextEvent(c, _conn());
      expect(e.choices.length, 3);
      expect(c.pending, isNotNull);
      // 未抉择时再次请求不会重复生成
      final again = await engine.nextEvent(c, _conn());
      expect(identical(again, e), isTrue);
      expect(c.events.length, 1);

      // 章节生成时年龄就推进了（16 + 本章 3 年），结算不再重复加。
      expect(c.age, 19);
      await engine.choose(c, 0, _conn());
      expect(c.pending, isNull);
      expect(c.age, 19);
      expect(c.stats.mind, 63);
      expect(c.stats.wealth, 36);
      expect(e.outcome, contains('大城市'));
      expect(changes, greaterThan(0));
    });

    test('非法选项直接拒绝', () async {
      final c = _char();
      final engine = LifeEngine(complete: responder());
      await engine.nextEvent(c, _conn());
      await expectLater(engine.choose(c, 9, _conn()), throwsA(isA<StateError>()));
    });

    test('收尾生成传记与评分', () async {
      final c = _char();
      final engine = LifeEngine(complete: responder());
      await engine.finalize(c, _conn());
      expect(c.ended, isTrue);
      expect(c.score, 76);
      expect(c.epitaph, contains('平凡'));
    });

    test('结束后不再生成新事件', () async {
      final c = _char()..ended = true;
      final engine = LifeEngine(complete: responder());
      await expectLater(engine.nextEvent(c, _conn()), throwsA(isA<StateError>()));
    });
  });
}

import 'package:flutter_test/flutter_test.dart';

import 'package:ai_agent_app/services/mini_games.dart';

void main() {
  group('抉择轮盘', () {
    test('中英文逗号、分号、换行都能分隔，去空去重', () {
      expect(parseWheelOptions('A,B，C; D\nE；F'),
          ['A', 'B', 'C', 'D', 'E', 'F']);
      expect(parseWheelOptions('A,A, A ,,'), ['A']);
      expect(parseWheelOptions('  '), isEmpty);
    });

    test('少于两个选项转不起来，结果必在选项内', () {
      expect(spinWheel(['A']), isNull);
      expect(spinWheel([]), isNull);
      final opts = ['A', 'B', 'C'];
      for (var seed = 0; seed < 30; seed++) {
        expect(opts, contains(spinWheel(opts, seed: seed)));
      }
    });
  });

  group('猜数字', () {
    test('判定三种结果', () {
      expect(judgeGuess(50, 30), -1);
      expect(judgeGuess(50, 50), 0);
      expect(judgeGuess(50, 70), 1);
    });

    test('注入目标可确定性验证，越界不接受，猜中后锁定', () {
      final g = GuessNumberGame(target: 42);
      expect(g.guess(20), -1);
      expect(g.guess(60), 1);
      expect(g.guess(42), 0);
      expect(g.done, isTrue);
      expect(g.tries, 3);
      expect(g.guess(1), 0); // 结束后不再计数
      expect(g.tries, 3);
    });

    test('越界输入不消耗次数', () {
      final g = GuessNumberGame(target: 42);
      expect(g.guess(0), isNull);
      expect(g.guess(101), isNull);
      expect(g.tries, 0);
    });
  });

  group('石头剪刀布', () {
    test('三态循环胜负', () {
      expect(rpsJudge(RpsMove.rock, RpsMove.scissors), 1);
      expect(rpsJudge(RpsMove.scissors, RpsMove.paper), 1);
      expect(rpsJudge(RpsMove.paper, RpsMove.rock), 1);
      expect(rpsJudge(RpsMove.rock, RpsMove.paper), -1);
      expect(rpsJudge(RpsMove.rock, RpsMove.rock), 0);
    });

    test('随机出拳始终合法', () {
      for (var s = 0; s < 20; s++) {
        expect(RpsMove.values, contains(randomRps(seed: s)));
      }
    });
  });

  group('每日一签与八球', () {
    test('同一天同一支签，跨天变化，下标不越界', () {
      final d1 = DateTime(2026, 11, 9);
      final d2 = DateTime(2026, 11, 10);
      expect(fortuneIndex(d1, 7), fortuneIndex(d1, 7));
      expect(fortuneIndex(d1, 7), isIn(List.generate(7, (i) => i)));
      expect(fortuneIndex(d2, 7), isIn(List.generate(7, (i) => i)));
      expect(fortuneIndex(DateTime(2026, 11, 9, 23, 59), 7),
          fortuneIndex(d1, 7));
      expect(fortuneIndex(d1, 0), 0);
    });

    test('八球下标不越界', () {
      for (var s = 0; s < 20; s++) {
        expect(eightBallIndex(8, seed: s), isIn(List.generate(8, (i) => i)));
      }
      expect(eightBallIndex(0), 0);
    });
  });

  group('AI 玩法提示词', () {
    test('二十问系统词藏住答案且限定回答', () {
      final sys = twentyQuestionsSystem('月亮');
      expect(sys, contains('月亮'));
      expect(sys, contains('只回答'));
      expect(twentyQuestionsOpening(), contains('20'));
    });

    test('故事接龙按主题开篇', () {
      expect(storyChainSystem(), contains('60'));
      expect(storyChainOpening('太空电梯'), contains('太空电梯'));
    });

    test('回答归一化覆盖四种判定', () {
      expect(normalizeTwentyAnswer('是'), 'yes');
      expect(normalizeTwentyAnswer('不是'), 'no');
      expect(normalizeTwentyAnswer('不确定'), 'unclear');
      expect(normalizeTwentyAnswer('猜对了！'), 'correct');
      expect(normalizeTwentyAnswer('Yes'), 'yes');
      expect(normalizeTwentyAnswer('No'), 'no');
      expect(normalizeTwentyAnswer('很长的解释'), 'unclear');
    });

    test('玩法标记：只有两个需要 AI', () {
      expect(miniGameNeedsAi(MiniGameKind.wheel), isFalse);
      expect(miniGameNeedsAi(MiniGameKind.guess), isFalse);
      expect(miniGameNeedsAi(MiniGameKind.rps), isFalse);
      expect(miniGameNeedsAi(MiniGameKind.fortune), isFalse);
      expect(miniGameNeedsAi(MiniGameKind.eightBall), isFalse);
      expect(miniGameNeedsAi(MiniGameKind.twentyQuestions), isTrue);
      expect(miniGameNeedsAi(MiniGameKind.storyChain), isTrue);
    });
  });
}

import 'package:flutter_test/flutter_test.dart';

import 'package:ai_agent_app/models/models.dart';
import 'package:ai_agent_app/services/feature_store.dart';
import 'package:ai_agent_app/services/model_source.dart';
import 'package:ai_agent_app/services/roundtable.dart';

AppSettings _settings() {
  final s = AppSettings();
  s.load({});
  s.apiKey = 'sk-a';
  s.model = 'model-a';
  s.cachedModels = ['model-a', 'model-a2'];
  s.syncActive();

  s.profiles.add(ApiProfile(
    id: 'b',
    name: 'B 服务',
    baseUrl: 'https://b.example/v1',
    model: 'model-b',
    cachedModels: ['model-b', 'model-b2'],
  ));
  s.applyProfileKeys({s.activeProfileId: 'sk-a', 'b': 'sk-b'});
  return s;
}

void main() {
  group('两级模型选择：按运营商分组', () {
    test('每个连接只列自己的模型，不串台', () {
      final s = _settings();
      final groups = buildProviderGroups(s, activeModels: ['model-a3']);
      expect(groups.length, 2);

      final a = groups.firstWhere((g) => g.active);
      expect(a.name, isNotEmpty);
      expect(a.models, containsAll(['model-a', 'model-a2', 'model-a3']));
      expect(a.models, isNot(contains('model-b')));
      expect(a.models, isNot(contains('model-b2')));

      final b = groups.firstWhere((g) => !g.active);
      expect(b.name, 'B 服务');
      expect(b.baseUrl, 'https://b.example/v1');
      expect(b.apiKey, 'sk-b');
      // 非活动连接不叠加活动连接刚刚刷新的模型
      expect(b.models, isNot(contains('model-a3')));
      expect(b.models, contains('model-b2'));
    });

    test('模型去重且当前模型排第一', () {
      final s = _settings();
      final groups = buildProviderGroups(s, activeModels: ['model-a']);
      final a = groups.firstWhere((g) => g.active);
      expect(a.models.first, 'model-a');
      expect(a.models.toSet().length, a.models.length);
    });

    test('空模型不进列表', () {
      final s = _settings();
      s.profiles.add(ApiProfile(
        id: 'c',
        name: 'C',
        baseUrl: 'https://c/v1',
        model: '',
        cachedModels: ['  ', '', 'model-c'],
      ));
      final c = buildProviderGroups(s).firstWhere((g) => g.id == 'c');
      expect(c.models, ['model-c']);
    });

    test('过滤大小写不敏感，空查询返回全部', () {
      const models = ['GPT-4o', 'gpt-4o-mini', 'deepseek-chat'];
      expect(filterModels(models, ''), models);
      expect(filterModels(models, 'GPT'), hasLength(2));
      expect(filterModels(models, 'deep'), ['deepseek-chat']);
      expect(filterModels(models, 'zzz'), isEmpty);
    });
  });

  group('游戏模型偏好恢复', () {
    test('没记住时退回当前对话模型', () {
      final s = _settings();
      final c = resolveModelChoice(s);
      expect(c.baseUrl, s.baseUrl);
      expect(c.apiKey, 'sk-a');
      expect(c.model, 'model-a');
      expect(c.providerName, s.activeProfile.name);
    });

    test('记住 B 连接时按地址补回 B 的密钥', () {
      final s = _settings();
      final c = resolveModelChoice(
        s,
        baseUrl: 'https://b.example/v1',
        model: 'model-b2',
        providerName: 'B 服务',
      );
      expect(c.apiKey, 'sk-b');
      expect(c.model, 'model-b2');
      expect(c.providerName, 'B 服务');
    });

    test('地址或模型为空时安全退回默认', () {
      final s = _settings();
      expect(resolveModelChoice(s, baseUrl: '', model: 'x').model, 'model-a');
      expect(
          resolveModelChoice(s, baseUrl: 'https://b.example/v1', model: '')
              .model,
          'model-a');
    });

    test('未知地址也能按 host 生成可读名字', () {
      final s = _settings();
      final c = resolveModelChoice(
        s,
        baseUrl: 'https://unknown.example/v1',
        model: 'whatever',
      );
      expect(c.providerName, 'unknown.example');
      expect(c.apiKey, isEmpty);
    });

    test('偏好序列化不含密钥字段', () {
      final p = GameModelPref.fromJson(const GameModelPref(
        baseUrl: 'https://b/v1',
        model: 'm',
        providerName: 'B',
      ).toJson());
      expect(p.baseUrl, 'https://b/v1');
      expect(p.model, 'm');
      expect(p.toJson().toString(), isNot(contains('sk-')));
    });

    test('存档往返不落密钥', () async {
      final mem = <String, String>{};
      final store = FeatureStore(memory: mem);
      await store.saveGameModel(const GameModelPref(
        baseUrl: 'https://b/v1',
        model: 'model-b',
        providerName: 'B',
      ));
      final loaded = await store.loadGameModel();
      expect(loaded!.model, 'model-b');
      expect(mem.values.join(), isNot(contains('sk-')));
    });
  });

  group('席位带运营商名', () {
    test('providerName 随存档往返，旧存档兼容', () {
      final seat = Seat(
        id: 's',
        name: '甲',
        baseUrl: 'https://b/v1',
        apiKey: 'sk-secret',
        model: 'model-b',
        providerName: 'B 服务',
      );
      final json = seat.toJson();
      expect(json.toString(), isNot(contains('sk-secret')));
      final restored = Seat.fromJson(json);
      expect(restored.providerName, 'B 服务');
      expect(restored.apiKey, isEmpty);

      final old = Seat.fromJson({
        'id': 's2',
        'model': 'm',
        'baseUrl': 'https://b/v1',
      });
      expect(old.providerName, isEmpty);

      expect(seat.copy().providerName, 'B 服务');
    });

    test('按地址补运营商名', () {
      final s = _settings();
      expect(providerNameFor(s, 'https://b.example/v1'), 'B 服务');
      expect(providerNameFor(s, 'https://x.example/v1'), 'x.example');
    });
  });
}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:provider/provider.dart';

import 'package:ai_agent_app/main.dart';
import 'package:ai_agent_app/models/models.dart';
import 'package:ai_agent_app/theme.dart';
import 'package:ai_agent_app/state/app_state.dart';
import 'package:ai_agent_app/ui/settings_screen.dart';

/// v4.17 回归：
/// 1) 设置子页的系统返回（侧边手势 / 返回键）必须逐层退出，
///    不能一滑就把整个设置页 pop 掉；
/// 2) 默认字号要在人眼舒适的区间（ChatGPT / Gemini 量级），
///    而不是老版的 15.5 偏小正文。
void main() {
  group('字号基准', () {
    test('默认档位放大到 1.10，正文落在 17 左右', () {
      // 1.0 档 × 1.10 基准 = 1.10 → 正文 15.5 * 1.1 ≈ 17.05
      expect(effectiveTextScale(1.0, 1.0), closeTo(1.10, 0.001));
      expect(15.5 * effectiveTextScale(1.0, 1.0), greaterThanOrEqualTo(16.5));
    });

    test('四档都保持单调而且不会失真', () {
      final scales = [0.9, 1.0, 1.12, 1.25]
          .map((v) => effectiveTextScale(v, 1.0))
          .toList();
      for (var i = 1; i < scales.length; i++) {
        expect(scales[i], greaterThan(scales[i - 1]));
      }
      // 最小档也不能小到回到「看不清」的老问题
      expect(scales.first, greaterThanOrEqualTo(0.9));
      expect(scales.last, lessThanOrEqualTo(1.6));
    });

    test('吸收系统字体缩放，但 1.25 以上不再叠乘', () {
      final normal = effectiveTextScale(1.0, 1.0);
      final big = effectiveTextScale(1.0, 1.25);
      expect(big, greaterThan(normal));
      // 系统 1.6 被夹到 1.25，否则卡片标题会被挤出容器
      expect(effectiveTextScale(1.0, 1.6), closeTo(big, 0.001));
      // 系统字体缩小同样被尊重
      expect(effectiveTextScale(1.0, 0.85), lessThan(normal));
    });

    test('非法输入不崩，回落到 1.0', () {
      expect(effectiveTextScale(1.0, 0), closeTo(1.10, 0.001));
      expect(effectiveTextScale(1.0, double.nan), closeTo(1.10, 0.001));
      expect(effectiveTextScale(1.0, double.infinity), closeTo(1.10, 0.001));
    });
  });

  group('页面转场', () {
    test('路由时长统一：240ms 进入 / 200ms 退出', () {
      final route = SoftPageRoute<void>(builder: (_) => const SizedBox());
      expect(route.transitionDuration, const Duration(milliseconds: 240));
      expect(route.reverseTransitionDuration, const Duration(milliseconds: 200));
      // v4.25：全站默认保留下层 onstage。以前只有设置子页这么做，
      // 点按钮返回时下层要从 offstage 恢复、首帧重建整页，正是卡顿来源。
      expect(route.keepBelow, isTrue);
      expect(route.opaque, isFalse);
    });

    test('显式关掉 keepBelow 才恢复不透明', () {
      final route = SoftPageRoute<void>(
        keepBelow: false,
        builder: (_) => const SizedBox(),
      );
      expect(route.keepBelow, isFalse);
      expect(route.opaque, isTrue);
    });

    // v4.26 回归：点顶栏返回按钮一直「卡一下」的真凶，是进出共用同一条
    // 0.35 屏的 tween——退出的页面只滑出三分之一就被摘掉，看起来像
    // 卡了几百毫秒然后突然消失。侧滑走的是整屏跟手，所以只有按钮卡。
    testWidgets('按钮进出都走整屏位移，不会滑到一半就消失', (tester) async {
      await tester.pumpWidget(MaterialApp(
        home: Builder(
          builder: (c) => Scaffold(
            body: Center(
              child: TextButton(
                onPressed: () => Navigator.of(c).push(
                  SoftPageRoute<void>(
                    builder: (_) => const Scaffold(
                      body: Center(child: Text('DETAIL_MARK')),
                    ),
                  ),
                ),
                child: const Text('OPEN_MARK'),
              ),
            ),
          ),
        ),
      ));
      await tester.tap(find.text('OPEN_MARK'));
      await tester.pump();
      // 进入半程（120 / 240ms）：整屏 tween 应已移动约半屏。
      await tester.pump(const Duration(milliseconds: 120));
      final enterDx = tester
          .widgetList<SlideTransition>(find.byType(SlideTransition))
          .map((s) => s.position.value.dx)
          .reduce((a, b) => a > b ? a : b);
      expect(enterDx, greaterThan(0.3), reason: '进入应走整屏位移');
      await tester.pumpAndSettle();

      Navigator.of(tester.element(find.text('DETAIL_MARK'))).pop();
      await tester.pump();
      // 退出半程（100 / 200ms）：同样要离开原位足够远。
      await tester.pump(const Duration(milliseconds: 100));
      final exitDx = tester
          .widgetList<SlideTransition>(find.byType(SlideTransition))
          .map((s) => s.position.value.dx)
          .reduce((a, b) => a > b ? a : b);
      expect(exitDx, greaterThan(0.3), reason: '退出应走完整屏位移，而不是 0.35 屏');
      await tester.pumpAndSettle();
      expect(find.text('OPEN_MARK'), findsOneWidget);
    });

  });

  group('设置页逐层返回', () {
    testWidgets('侧滑先回设置主目录，再退出设置', (tester) async {
      final st = AppState()..settings = (AppSettings()..ensurePresets());
      await tester.pumpWidget(
        ChangeNotifierProvider<AppState>.value(
          value: st,
          child: MaterialApp(
            home: Scaffold(
              body: Builder(
                builder: (c) => Center(
                  child: TextButton(
                    onPressed: () => Navigator.of(c).push(
                      MaterialPageRoute(builder: (_) => const SettingsScreen()),
                    ),
                    child: const Text('HOME_MARK'),
                  ),
                ),
              ),
            ),
          ),
        ),
      );

      await tester.tap(find.text('HOME_MARK'));
      await tester.pumpAndSettle();
      expect(find.text('偏好设置'), findsOneWidget);

      // 进「语言与地区」
      await tester.tap(find.text('语言与地区').first);
      await tester.pumpAndSettle();
      expect(find.text('界面语言'), findsWidgets);

      // 第一次系统返回：只退一层，回到设置主目录
      await tester.binding.handlePopRoute();
      await tester.pumpAndSettle();
      expect(find.text('界面语言'), findsNothing,
          reason: '子页侧滑应当退回设置主目录，子页本身要离开渲染树');
      expect(find.text('HOME_MARK'), findsNothing,
          reason: '只退一层，设置页仍在栈上');

      // 第二次系统返回：退出设置，回到主界面
      await tester.binding.handlePopRoute();
      await tester.pumpAndSettle();
      expect(find.text('HOME_MARK'), findsOneWidget);
    });

    testWidgets('连续进两个子页后仍逐层退出', (tester) async {
      final st = AppState()..settings = (AppSettings()..ensurePresets());
      await tester.pumpWidget(
        ChangeNotifierProvider<AppState>.value(
          value: st,
          child: MaterialApp(
            home: Scaffold(
              body: Builder(
                builder: (c) => Center(
                  child: TextButton(
                    onPressed: () => Navigator.of(c).push(
                      MaterialPageRoute(builder: (_) => const SettingsScreen()),
                    ),
                    child: const Text('HOME_MARK'),
                  ),
                ),
              ),
            ),
          ),
        ),
      );

      await tester.tap(find.text('HOME_MARK'));
      await tester.pumpAndSettle();

      await tester.tap(find.text('外观主题').first);
      await tester.pumpAndSettle();
      expect(find.text('明暗模式'), findsWidgets);

      // 子页内返回 → 主目录
      await tester.binding.handlePopRoute();
      await tester.pumpAndSettle();
      expect(find.text('偏好设置'), findsOneWidget);

      // 再进另一个子页，返回同样只退一层
      await tester.tap(find.text('连接与模型').first);
      await tester.pumpAndSettle();
      expect(find.text('API BASE URL'), findsOneWidget);

      await tester.binding.handlePopRoute();
      await tester.pumpAndSettle();
      expect(find.text('偏好设置'), findsOneWidget);

      await tester.binding.handlePopRoute();
      await tester.pumpAndSettle();
      expect(find.text('HOME_MARK'), findsOneWidget);
    });
  });

  group('返回手势结束后不再吞点击', () {
    /// 走真实平台通道模拟一次预测性返回手势。
    Future<void> gesture(WidgetTester tester, String method,
        {double progress = 0}) async {
      final Object? args =
          method == 'commitBackGesture' || method == 'cancelBackGesture'
              ? null
              : <String, Object?>{
                  'touchOffset': <double>[0.0, 400.0],
                  'progress': progress,
                  'swipeEdge': 0,
                };
      final data =
          const StandardMethodCodec().encodeMethodCall(MethodCall(method, args));
      await tester.binding.defaultBinaryMessenger.handlePlatformMessage(
        SystemChannels.backGesture.name,
        data,
        (_) {},
      );
    }

    testWidgets('侧滑返回后立刻可以点下一项', (tester) async {
      final st = AppState()..settings = (AppSettings()..ensurePresets());
      await tester.pumpWidget(
        ChangeNotifierProvider<AppState>.value(
          value: st,
          child: const MaterialApp(
            home: Scaffold(body: Center(child: Text('HOME_MARK'))),
          ),
        ),
      );
      final nav = tester.state<NavigatorState>(find.byType(Navigator));

      nav.push(SoftPageRoute<void>(
        keepBelow: true,
        builder: (_) => const SettingsScreen(),
      ));
      await tester.pumpAndSettle();

      nav.push(SoftPageRoute<void>(
        keepBelow: true,
        builder: (_) => const SettingsScreen(initialCat: 'language'),
      ));
      await tester.pumpAndSettle();
      expect(find.text('界面语言'), findsWidgets);

      await gesture(tester, 'startBackGesture', progress: 0.1);
      await tester.pump();
      await gesture(tester, 'updateBackGestureProgress', progress: 0.55);
      await tester.pump();

      // 手指抬起：这一瞬间必须解除「用户手势进行中」的全局指针锁。
      // 修复前这个标志会一直保持到最长 800ms 的拖尾动画结束，
      // 页面看着已经停稳，点什么都没反应——用户只能再点一次。
      await gesture(tester, 'commitBackGesture');
      await tester.pump();
      expect(nav.userGestureInProgress, isFalse,
          reason: '手势一结束就该能点，而不是等退场动画的 800ms 拖尾');

      await tester.pumpAndSettle();
      expect(find.text('界面语言'), findsNothing, reason: '只退一层，回到设置目录');

      // 同一帧内立刻点下一项，必须一次就进。
      await tester.tap(find.text('外观主题').first);
      await tester.pumpAndSettle();
      expect(find.text('明暗模式'), findsWidgets,
          reason: '返回后第一次点击就要生效');
    });

    testWidgets('手势进行中仍然屏蔽点击（不能误触下层）', (tester) async {
      final st = AppState()..settings = (AppSettings()..ensurePresets());
      await tester.pumpWidget(
        ChangeNotifierProvider<AppState>.value(
          value: st,
          child: const MaterialApp(
            home: Scaffold(body: Center(child: Text('HOME_MARK'))),
          ),
        ),
      );
      final nav = tester.state<NavigatorState>(find.byType(Navigator));
      nav.push(SoftPageRoute<void>(
        keepBelow: true,
        builder: (_) => const SettingsScreen(),
      ));
      await tester.pumpAndSettle();

      await gesture(tester, 'startBackGesture', progress: 0.05);
      await tester.pump();
      expect(nav.userGestureInProgress, isTrue);

      await tester.tap(find.text('外观主题').first, warnIfMissed: false);
      await tester.pumpAndSettle();
      expect(find.text('明暗模式'), findsNothing, reason: '拖动过程中不应该点穿');

      await gesture(tester, 'cancelBackGesture');
      await tester.pumpAndSettle();
      expect(nav.userGestureInProgress, isFalse, reason: '取消后锁必须还回去');
      expect(find.text('外观主题'), findsWidgets);
    });
  });
}

import 'package:dio/dio.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:ai_agent_app/services/llm_client.dart';
import 'package:ai_agent_app/services/roundtable.dart';

Seat _seat(String id, String model, {bool enabled = true}) => Seat(
      id: id,
      name: '席位$id',
      role: '立场$id',
      baseUrl: 'https://example.com/v1',
      apiKey: 'key-$id',
      model: model,
      enabled: enabled,
    );

void main() {
  group('议程解析', () {
    test('清洗编号、Markdown 标题与项目符号', () {
      const raw = '以下是大纲\n'
          '1. 问题界定\n'
          '2、关键事实\n'
          '- 分歧点\n'
          '## 风险与约束\n'
          '• 下一步\n'
          '这一行非常非常长，长到不应该被当成一条议程条目，'
          '所以必须被过滤掉，否则会议大纲会被一句废话占满整整一屏。';
      final out = parseAgenda(raw);
      expect(out, ['问题界定', '关键事实', '分歧点', '风险与约束', '下一步']);
    });

    test('去重且不超过上限', () {
      final out = parseAgenda(
          '条目一\n条目二\n条目一\n条目三\n条目四\n条目五', max: 3);
      expect(out, ['条目一', '条目二', '条目三']);
      expect(out.length, 3);
      expect(out.toSet().length, 3);
    });

    test('空文本返回空列表', () => expect(parseAgenda(''), isEmpty));
  });

  group('讨论上下文', () {
    test('没有发言时给出占位说明', () {
      expect(buildDiscussionContext([]), contains('尚无其他人发言'));
    });

    test('只取最近若干条并逐条截断', () {
      final turns = [
        for (var i = 0; i < 15; i++)
          MeetingTurn(
              seatId: 's$i',
              seatName: '席位$i',
              model: 'm',
              round: 1,
              content: '甲' * 500),
      ];
      final ctx = buildDiscussionContext(turns, limit: 3, perTurn: 20);
      expect(ctx, contains('席位14'));
      expect(ctx, isNot(contains('席位11')));
      expect(ctx.split('甲' * 21).length, 1);
    });

    test('失败的发言不进入上下文', () {
      final bad = MeetingTurn(
          seatId: 'x', seatName: '失败者', model: 'm', round: 1, error: 'boom');
      expect(buildDiscussionContext([bad]), contains('尚无其他人发言'));
    });
  });

  group('会议数据与纪要', () {
    test('JSON 往返不丢字段', () {
      final m = Meeting(
        id: 'm1',
        topic: '要不要做 X',
        agenda: '界定\n风险',
        seats: [_seat('a', 'gpt-a'), _seat('b', 'gpt-b')],
        rounds: 3,
      );
      m.turns.add(MeetingTurn(
          seatId: 'a', seatName: '席位a', model: 'gpt-a', round: 1, content: '支持'));
      m.summary = '结论：先做小规模验证';
      m.phase = MeetingPhase.done;
      final back = Meeting.fromJson(m.toJson());
      expect(back.topic, '要不要做 X');
      expect(back.rounds, 3);
      expect(back.seats.length, 2);
      expect(back.turns.single.content, '支持');
      expect(back.summary, contains('小规模验证'));
      expect(back.phase, MeetingPhase.done);
    });

    test('纪要含大纲、逐轮发言与结论', () {
      final m = Meeting(id: 'm', topic: '议题', agenda: '界定\n分歧');
      m.turns.addAll([
        MeetingTurn(
            seatId: 'a', seatName: '甲', model: 'model-a', round: 1, content: '甲观点'),
        MeetingTurn(
            seatId: 'b', seatName: '乙', model: 'model-b', round: 2, content: '乙观点'),
      ]);
      m.summary = '共识：都不反对';
      final md = m.toMarkdown();
      expect(md, contains('# 议题'));
      expect(md, contains('## 会议大纲'));
      expect(md, contains('### 第 1 轮'));
      expect(md, contains('### 第 2 轮'));
      expect(md, contains('**甲**（model-a）'));
      expect(md, contains('## 会议结论'));
    });

    test('停用的席位不计入参会者', () {
      final m = Meeting(id: 'm', seats: [
        _seat('a', 'm1'),
        _seat('b', 'm2', enabled: false),
      ]);
      expect(m.activeSeats.length, 1);
    });
  });

  group('默认席位', () {
    test('跨连接去重、最多 5 个且角色各不相同', () {
      final seats = defaultSeats(
        fallbackBaseUrl: 'https://a/v1',
        fallbackApiKey: 'ka',
        fallbackModel: 'model-1',
        candidates: [
          (baseUrl: 'https://a/v1', apiKey: 'ka', model: 'model-1'),
          (baseUrl: 'https://a/v1', apiKey: 'ka', model: 'model-2'),
          (baseUrl: 'https://b/v1', apiKey: 'kb', model: 'model-3'),
          (baseUrl: 'https://b/v1', apiKey: 'kb', model: 'model-4'),
          (baseUrl: 'https://c/v1', apiKey: 'kc', model: 'model-5'),
          (baseUrl: 'https://c/v1', apiKey: 'kc', model: 'model-6'),
          (baseUrl: 'https://c/v1', apiKey: 'kc', model: 'model-7'),
        ],
      );
      expect(seats.length, 5);
      expect(seats.map((s) => s.model).toSet().length, 5);
      expect(seats.map((s) => s.role).toSet().length, 5);
      expect(seats.last.apiKey, anyOf('ka', 'kb', 'kc'));
    });

    test('候选为空时仍能用当前模型开一场', () {
      final seats = defaultSeats(
        fallbackBaseUrl: 'https://a/v1',
        fallbackApiKey: 'k',
        fallbackModel: 'only-model',
        candidates: [],
      );
      expect(seats.length, 1);
      expect(seats.single.model, 'only-model');
    });
  });

  group('会议引擎', () {
    Meeting meeting({int seats = 3, int rounds = 2}) => Meeting(
          id: 'm',
          topic: '是否应该做 X',
          rounds: rounds,
          seats: [for (var i = 0; i < seats; i++) _seat('s$i', 'model-$i')],
        );

    CompleteFn responder({String Function(LlmRequest req)? onReq}) =>
        (LlmRequest req, {CancelToken? cancel}) async {
          if (onReq != null) return onReq(req);
          if (req.maxTokens == 600) return '问题界定\n关键事实\n风险';
          if (req.maxTokens == 1400) return '共识\n分歧\n建议';
          return '我的观点';
        };

    test('逐轮逐个发言，最后产出结论', () async {
      final m = meeting();
      var changes = 0;
      final engine = RoundtableEngine(
          complete: responder(), onChanged: () => changes++);
      await engine.run(m);
      expect(m.phase, MeetingPhase.done);
      expect(m.agenda.split('\n').length, 3);
      expect(m.turns.length, 6);
      expect(m.turns.where((t) => t.round == 1).length, 3);
      expect(m.turns.where((t) => t.round == 2).length, 3);
      expect(m.turns.every((t) => t.ok), isTrue);
      expect(m.summary, contains('共识'));
      expect(changes, greaterThan(5));
    });

    test('后发言者能看到前面席位的观点', () async {
      final seen = <String>[];
      final engine = RoundtableEngine(
        complete: (req, {cancel}) async {
          seen.add('${req.messages.last['content']}');
          if (req.maxTokens == 600) return '大纲';
          if (req.maxTokens == 1400) return '结论';
          return '观点 ${seen.length}';
        },
      );
      final m = meeting(seats: 2, rounds: 2);
      await engine.run(m);
      expect(seen.length, 1 + 4 + 1); // 大纲 + 4 次发言 + 总结
      expect(seen[2], contains('观点 2')); // 第二位能看到第一位
      expect(seen[5], contains('观点 5')); // 总结能看到全部
    });

    test('单个席位失败不会拖垮整场会议', () async {
      final engine = RoundtableEngine(
        complete: (req, {cancel}) async {
          if (req.maxTokens == 600) return '大纲';
          if (req.maxTokens == 1400) return '结论';
          if (req.model == 'model-1') throw StateError('模型不可用');
          return '观点';
        },
      );
      final m = meeting(seats: 3, rounds: 1);
      await engine.run(m);
      expect(m.phase, MeetingPhase.done);
      expect(m.turns.length, 3);
      expect(m.turns.where((t) => t.ok).length, 2);
      expect(m.turns[1].error, contains('模型不可用'));
      expect(m.summary, '结论');
    });

    test('取消后标记失败且不再继续请求', () async {
      var calls = 0;
      final engine = RoundtableEngine(
        complete: (req, {cancel}) async {
          calls++;
          return '内容';
        },
      );
      final m = meeting(seats: 2, rounds: 3);
      final token = CancelToken()..cancel();
      await engine.run(m, cancel: token);
      expect(m.phase, MeetingPhase.failed);
      expect(calls, 0);
      expect(m.turns, isEmpty);
    });

    test('没有议题或没有可用席位时直接拒绝', () async {
      final engine = RoundtableEngine(complete: responder());
      final noTopic = meeting()..topic = '';
      await expectLater(engine.run(noTopic), throwsA(isA<StateError>()));
      final noSeat = Meeting(id: 'x', topic: '议题');
      await expectLater(engine.run(noSeat), throwsA(isA<StateError>()));
    });

    test('单独生成大纲后可手动修改再开会', () async {
      final m = meeting();
      final engine = RoundtableEngine(complete: responder());
      final agenda = await engine.outline(m);
      expect(agenda.split('\n').length, 3);
      expect(m.phase, MeetingPhase.idle);
      m.agenda = '我改过的大纲';
      await engine.run(m, autoOutline: false);
      expect(m.agenda, '我改过的大纲');
      expect(m.turns.length, 6);
    });
  });
}

import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

import 'package:ai_agent_app/i18n.dart';
import 'package:ai_agent_app/skin.dart';
import 'package:ai_agent_app/theme.dart';
import 'package:ai_agent_app/ui/settings_screen.dart';

void main() {
  group('v4.15 界面语言', () {
    tearDown(() => L10n.useTable('zh', const {}));

    Map<String, String> tsv(String code) => L10n.parseTsv(
        File('assets/i18n/$code.tsv').readAsStringSync());

    test('中文是原文，不做任何替换', () {
      L10n.lang = 'zh';
      expect(t('复制'), '复制');
      expect(t('连接与模型'), '连接与模型');
    });

    test('切到英文后，界面词条全部变英文', () {
      L10n.lang = 'en';
      expect(t('复制'), 'Copy');
      expect(t('发送'), 'Send');
      expect(t('外观主题'), 'Appearance');
      expect(t('设置'), 'Settings');
    });

    test('英文缺词条时回退原文，而不是露 key', () {
      L10n.lang = 'en';
      // 这条故意不在词表里：宁可看到一句中文，也不显示 raw key。
      expect(t('这是一条不存在的词条'), '这是一条不存在的词条');
    });

    test('繁体中文按台湾用语转换', () {
      L10n.useTable('zh-TW', tsv('zh-TW'));
      expect(t('复制'), '複製');
      expect(t('保存'), '儲存');
      expect(t('删除'), '刪除');
    });

    test('日文词表覆盖全部可见文案，不剩中文', () {
      L10n.useTable('ja', tsv('ja'));
      expect(t('发送'), '送信');
      expect(t('取消'), 'キャンセル');
      // 日文本身也用汉字（「例」「設定」），不能靠「不含 CJK」判断，
      // 只能确认它已经不是原来那串中文。
      for (final k in ['按路径筛选，如 app_state / AndroidManifest', '连接与模型', '外观主题']) {
        expect(t(k), isNot(k), reason: '「$k」日文缺失');
      }
    });

    test('设置分类标题跟随界面语言重算，不缓存旧文字', () {
      L10n.lang = 'zh';
      expect(kSettingsCats.first.title, '连接与模型');
      L10n.lang = 'en';
      expect(kSettingsCats.first.title, 'Connection & models');
      expect(kSettingsCats.first.desc, contains('Endpoint'));
    });

    test('语言表里每个界面语言都有本地写法', () {
      expect(kUiLangs.length, greaterThanOrEqualTo(30));
      for (final l in kUiLangs) {
        expect(l.code.trim(), isNotEmpty);
        expect(l.native.trim(), isNotEmpty);
      }
    });

    test('列表里的每种语言都真的有词表，不摆假选项', () {
      var covered = 0;
      for (final l in kUiLangs) {
        if (l.code == 'zh' || l.code == 'en') continue;
        final f = File('assets/i18n/${l.code}.tsv');
        expect(f.existsSync(), isTrue, reason: '${l.code} 列在语言表里却没有词表');
        final rows = L10n.parseTsv(f.readAsStringSync());
        expect(rows.length, greaterThanOrEqualTo(280),
            reason: '${l.code} 词条只有 ${rows.length} 条');
        covered++;
      }
      expect(covered, greaterThanOrEqualTo(30));
    });
  });

  group('v4.15 主题皮肤', () {
    tearDown(() => applySkinFromSettings(
          id: 'github',
          accent: '',
          canvas: '',
          radius: 1.0,
        ));

    test('换主题后语义色跟着换', () {
      applySkinFromSettings(
          id: 'github', accent: '', canvas: '', radius: 1.0);
      final ghSurface = C.surface;
      final ghInk = C.ink;

      applySkinFromSettings(
          id: 'dracula', accent: '', canvas: '', radius: 1.0);
      expect(C.surface, isNot(ghSurface));
      // 墨色统一由明暗决定，主题换的是画布与纸面；
      // 这里用 ink 做对照，确认它没有被主题误伤。
      expect(C.ink, ghInk);
      expect(Skin.preset.name, 'Dracula');
    });

    test('圆角强度只改圆角，不改颜色', () {
      applySkinFromSettings(
          id: 'nord', accent: '', canvas: '', radius: 0.6);
      final tight = D.r;
      final color = C.brand;
      applySkinFromSettings(
          id: 'nord', accent: '', canvas: '', radius: 1.4);
      expect(D.r, greaterThan(tight));
      expect(C.brand, color);
    });

    test('自定义主色与页面底色生效', () {
      applySkinFromSettings(
        id: 'custom',
        accent: '#17A34A',
        canvas: '#FAF9F5',
        radius: 1.0,
      );
      expect(C.brand, const Color(0xFF17A34A));
      expect(C.bg, const Color(0xFFFAF9F5));
      // 纸面要比画布亮，否则卡片浮不起来。
      expect(C.surface.computeLuminance(),
          greaterThan(C.bg.computeLuminance()));
    });

    test('无效色值回退默认，不把界面刷成透明', () {
      applySkinFromSettings(
        id: 'custom',
        accent: 'not-a-color',
        canvas: '',
        radius: 1.0,
      );
      expect(C.brand, const Color(0xFF3478F6));
    });

    test('十八套内置主题都提供了亮暗两套完整色板', () {
      expect(kSkinPresets.length, greaterThanOrEqualTo(18));
      for (final p in kSkinPresets) {
        // 强调色允许亮暗共用（ChatGPT 就是一支绿），
        // 但画布与纸面必须分开，否则深浅色模式会糊成一片。
        expect(p.light.surface, isNot(p.dark.surface));
        expect(p.light.bg, isNot(p.dark.bg));
      }
    });
  });
}

import 'package:ai_agent_app/services/think_splitter.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  group('思考流拆分', () {
    test('把 <thinking> 段抽到思考区，正文只留答案', () {
      final s = ThinkSplitter();
      final p = s.add('<thinking>先看前提，再看结论。</thinking>答案是 42。');
      expect(p.thinking, '先看前提，再看结论。');
      expect(p.content, '答案是 42。');
    });

    test('标签被切成两半时不会漏字', () {
      final s = ThinkSplitter();
      final a = s.add('开头<thin');
      final b = s.add('king>中间</think');
      final c = s.add('ing>结尾');
      final d = s.flush();
      final content = a.content + b.content + c.content + d.content;
      final thinking = a.thinking + b.thinking + c.thinking + d.thinking;
      expect(content, '开头结尾');
      expect(thinking, '中间');
    });

    test('没有思考标签的普通正文原样透传', () {
      final s = ThinkSplitter();
      final p = s.add('直接给答案，不做推理。');
      expect(p.thinking, isEmpty);
      expect(p.content, '直接给答案，不做推理。');
      expect(s.flush().isEmpty, isTrue);
    });

    test('半个标签不会提前吐到正文', () {
      final s = ThinkSplitter();
      final p = s.add('结论在下面 <');
      expect(p.content, '结论在下面 ');
      final q = s.add('think>补一句</think>然后');
      expect(q.thinking, '补一句');
      expect(q.content, '然后');
    });

    test('流结束时仍未闭合，残余内容算思考', () {
      final s = ThinkSplitter();
      final p = s.add('<thinking>话没说完');
      expect(p.content, isEmpty);
      expect(p.thinking, '话没说完');
      final t = s.flush();
      expect(t.thinking, isEmpty);
    });

    test('多段思考与正文交替出现时顺序不乱', () {
      final s = ThinkSplitter();
      final p = s.add(
        '<think>一</think>甲<think>二</think>乙',
      );
      expect(p.thinking, '一二');
      expect(p.content, '甲乙');
    });
  });
}

import 'dart:convert';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
